(window.CLAVE_TODO=window.CLAVE_TODO||{})[13]=[{"a":"De la Sentencia y otros Modos de Terminación del Procedimiento","q":[{"i":"13-2","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Otros modos de terminación de los procedimientos. En relación al Acuerdo entre partes: Señale la incorrecta.","o":["El intento de conciliación no suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen y podrá producirse en cualquier momento anterior al día en que el pleito haya sido declarado concluso para sentencia.","Si las partes llegaran a un acuerdo que implique la desaparición de la controversia y estuviera dentro del objeto de interés público o de terceros, el Juez o Tribunal declarará terminado el procedimiento, salvo que por Ley se hubiese manifestado contrario al sometimiento judicial del mismo del interés público o de terceros.","En los procedimientos en primera o única instancia, el Juez o Tribunal, de oficio o a solicitud de parte, una vez formalizada la demanda y la contestación, podrá someter a la consideración de las partes el reconocimiento de hechos o documentos, así como la posibilidad de alcanzar un acuerdo que ponga fin a la controversia, cuando el juicio se promueva sobre materias susceptibles de transacción y, en particular, cuando verse sobre estimación de cantidad.","Los representantes de las Administraciones públicas demandadas necesitarán la autorización oportuna para llevar a efecto la transacción, con arreglo a las normas que regulen la disposición de la acción por parte de las mismas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Si las partes llegaran a un acuerdo que implique la desaparición de la controversia y estuviera dentro del objeto de interés público o de terceros, el Juez o Tribunal declarará terminado el procedimiento, salvo que por Ley se hubiese manifestado contrario al sometimiento judicial del mismo del interés público o de terceros</mark></span>La B es la incorrecta: el acuerdo no puede ser lesivo del interés público o de terceros (no basta con que «esté dentro del objeto» de ese interés). Según el <span class=\"ref-norma\">art. 77.2 y 77.3 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El intento de conciliación no suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen y podrá producirse en cualquier momento anterior al día en que el pleito haya sido declarado concluso para sentencia. [...] El Juez o Tribunal dictará auto declarando terminado el procedimiento, siempre que lo acordado no fuera manifiestamente contrario al ordenamiento jurídico ni lesivo del interés público o de terceros.\"</span> (verificado con el texto del temario)."},{"i":"13-49","p":"Ley reguladora de la jurisdicción contencioso-administrativa. La sentencia. La sentencia se dictará en el plazo de: Señale la opción correcta.","o":["Quince días.","Veinte días.","Diez días.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 67.5 · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. Fundamento: El Art. 67.5 de la LJCA establece que la sentencia se dictará en el plazo de diez días desde que el pleito haya sido declarado concluso."},{"i":"13-52","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Sentencia. Cuando la sentencia estimase el recurso contencioso-administrativo: Señale la incorrecta.","o":["Si se hubiera pretendido el reconocimiento o restablecimiento de una situación jurídica individualizada, se reconocerá dicha situación jurídica y se adoptarán cuantas medidas sean necesarias para el pleno restablecimiento de la misma.","Si fuera estimada una pretensión de reparación de daños y perjuicios, se declarará en todo caso el derecho a la reparación, solicitando asimismo quien quiera obligar a indemnizar.","Si la misma consistiera en la anulación de un acto o en la práctica de una actuación por la Administración, la sentencia podrá establecer plazo para que se cumpla el fallo.","Declarará no ser conforme a Derecho y, en todo caso, anulará total o parcialmente la disposición o acto recurrido o dispondrá lo que sea o se modifique la actuación impugnada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Si fuera estimada una pretensión de reparación de daños y perjuicios, se declarará en todo caso el derecho ...</mark></span><span class=\"ref-norma\">Art. 71.1.b) · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. Fundamento: El Art. 71.1.b) de la LJCA establece que si la sentencia estima una pretensión de reparación de daños y perjuicios, se declarará el derecho a la reparación, sin necesidad de que el demandante solicite obligar a la indemnización, ya que el Tribunal lo establecerá. Por lo tanto, es incorrecto que se exija \"solicitando asimismo quien quiera obligar a indemnizar\". (El texto de la LJCA dice: \"\\...se declarará el derecho a la reparación\\...\")."},{"i":"13-65","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Otros modos de terminación del procedimiento. El recurrente podrá desistir del recurso","o":["En cualquier momento anterior al día en que el juez o tribunal haya dictado sentencia.","En cualquier momento anterior a la sentencia.","En cualquier momento anterior a la finalización de la fase intermedia.","En cualquier momento anterior al juicio oral."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En cualquier momento anterior a la sentencia</mark></span><span class=\"ref-norma\">Art. 74.1 · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. Fundamento: El artículo 74.1 de la LJCA establece que el recurrente podrá desistir del recurso en cualquier momento antes de la sentencia."},{"i":"13-96","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Otros modos de terminación del procedimiento. El desistimiento","o":["A un recurrente contencioso-administrativo no se condenará nunca en costas.","Implicará necesariamente la condena en costas.","No implicará necesariamente la condena en costas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No implicará necesariamente la condena en costas</mark></span><span class=\"ref-norma\">Art. 74.5 · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. Fundamento: El artículo 74.5 de la LJCA establece que el desistimiento no implicará necesariamente la condena en costas, pudiendo el Juez o Tribunal imponerlas si aprecia mala fe o temeridad."},{"i":"13-176","p":"Contencioso-Administrativa. Sentencia. La sentencia se dictará en el plazo de __________ desde que el pleito haya sido declarado concluso y decidirá todas las cuestiones controvertidas en el proceso.","o":["Diez días.","Quince días.","Veinte días.","Treinta días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>En el procedimiento de derechos fundamentales (art. 121.1) el plazo es de cinco días. Según el <span class=\"ref-norma\">art. 67.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"La sentencia se dictará en el plazo de diez días desde que el pleito haya sido declarado concluso y decidirá todas las cuestiones controvertidas en el proceso.\"</span> (verificado con el texto del temario)."},{"i":"13-186","p":"Terminación del procedimiento. Señale la INCORRECTA.","o":["El recurso se podrá desistir en cualquier momento anterior a la sentencia.","Para que el desistimiento del representante en juicio produzca efectos será necesario que lo ratifique el recurrente o que esté autorizado para ello.","Cuando el procedimiento afecte a otros posibles interesados, el Juez o Tribunal les dará cuenta para que reanuden la que les convenga.","El desistimiento implicará necesariamente la condena en costas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El desistimiento implicará necesariamente la condena en costas</mark></span><span class=\"ref-norma\">Art. 74.6 · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. Fundamento: El artículo 74.6 de la LJCA, sobre el desistimiento, no establece la condena en costas como algo necesario (implica necesariamente la condena). De hecho, lo normal es que no haya condena, pues el desistimiento no es un modo de terminación con el que se condene al recurrente en costas."},{"i":"13-223","p":"Jurisdicción Contencioso-administrativa. Sentencia. Cuando la disposición, la actuación o el acto incurrieran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder","o":["La sentencia declarará la inadmisibilidad del recurso contencioso-administrativo.","La sentencia estimará el recurso contencioso-administrativo.","La sentencia desestimará el recurso contencioso-administrativo.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La sentencia estimará el recurso contencioso-administrativo</mark></span>Fundamento: Si se produce una infracción del ordenamiento jurídico, incluyendo la desviación de poder, la sentencia debe estimar el recurso contencioso-administrativo (declarando la nulidad del acto o disposición)."},{"i":"13-225","p":"Jurisdicción Contencioso-administrativa. Sentencia. Cuando la disposición, la actuación o el acto incurrieran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder","o":["La sentencia declarará la inadmisibilidad del recurso contencioso-administrativo.","La sentencia estimará el recurso contencioso-administrativo.","La sentencia desestimará el recurso contencioso-administrativo.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La sentencia estimará el recurso contencioso-administrativo</mark></span>Fundamento: Pregunta idéntica a la 7. Si se produce una infracción del ordenamiento jurídico, incluyendo la desviación de poder, la sentencia debe estimar el recurso contencioso-administrativo."},{"i":"13-230","p":"Jurisdicción Contencioso-administrativa. Otros modos de terminación del procedimiento. El intento de conciliación","o":["Suspenderá el curso de las actuaciones hasta que se obtenga el resultado o bien se rechace el intento de conciliación.","No suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen.","No suspenderá el curso de las actuaciones salvo que contare con informe favorable del Ministerio Fiscal.","No suspenderá el curso de las actuaciones salvo que provoquen un perjuicio grave e irreparable para las partes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen</mark></span>Según el <span class=\"ref-norma\">art. 77.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El intento de conciliación no suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen y podrá producirse en cualquier momento anterior al día en que el pleito haya sido declarado concluso para sentencia.\"</span> (verificado con el texto del temario)."},{"i":"13-268","p":"Jurisdicción Contencioso-administrativa. Otros modos de terminación del procedimiento. El recurrente podrá ______ del recurso en cualquier momento anterior a la sentencia.","o":["Desistir.","Renunciar.","Allanarse.","Suspender."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Desistir</mark></span>Según el <span class=\"ref-norma\">art. 74.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El recurrente podrá desistir del recurso en cualquier momento anterior a la sentencia.\"</span> (verificado con el texto del temario)."},{"i":"13-270","p":"Jurisdicción Contencioso-administrativa. Sentencia. La sentencia se dictará en el plazo de _____ desde que el pleito haya sido declarado concluso y decidirá todas las cuestiones controvertidas en el proceso","o":["Cinco días.","Diez días.","Quince días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 67 · De la Sentencia y otros Modos de Terminación del Procedimiento</span> dispone: <span class=\"ref-concepto\">\"La sentencia se dictará en el plazo de diez días desde que el pleito haya sido declarado concluso y decidirá todas las cuestiones controvertidas en el proceso.\"</span> Fundamento: La sentencia se dictará en el plazo de diez días desde que el pleito haya sido declarado concluso (art. 67.1 LJCA)."},{"i":"13-284","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Sentencia. Cuando la sentencia estimase el recurso contencioso-administrativo: Señale la incorrecta.","o":["Si se hubiera pretendido el reconocimiento o restablecimiento de una situación jurídica individualizada, se reconocerá dicha situación jurídica y se adoptarán cuantas medidas sean necesarias para el pleno restablecimiento de la misma.","Si fuera estimada una pretensión de reparación de daños y perjuicios, se declarará en todo caso el derecho a la reparación, solicitando asimismo quien quiera obligar a indemnizar.","Si la misma consistiera en la anulación de un acto o en la práctica de una actuación por la Administración, la sentencia podrá establecer plazo para que se cumpla el fallo.","Declarará no ser conforme a Derecho y, en todo caso, anulará total o parcialmente la disposición o acto recurrido o dispondrá lo que sea o se modifique la actuación impugnada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Si fuera estimada una pretensión de reparación de daños y perjuicios, se declarará en todo caso el derecho a la reparación, solicitando asimismo quien quiera obligar a indemnizar.</mark></span><span class=\"ref-norma\">Art. 71.1.d) · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. De conformidad con el artículo 71.1.d) LJCA, que dispone que la sentencia señalará quién viene obligado a indemnizar, no que lo \\\"solicite quien quiera\\\"."},{"i":"13-296","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Otros modos de terminación del procedimiento. El recurrente podrá desistir del recurso:","o":["En cualquier momento anterior al día en que el juez o tribunal haya dictado sentencia.","En cualquier momento anterior a la sentencia.","En cualquier momento anterior a la finalización de la fase intermedia.","En cualquier momento anterior al juicio oral."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En cualquier momento anterior a la sentencia.</mark></span><span class=\"ref-norma\">Art. 74.1 · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. De conformidad con el artículo 74.1 LJCA."},{"i":"13-299","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Sentencia. Cuando la sentencia estimase el recurso contencioso-administrativo, si fuera ejercitada una pretensión de resarcir daños y perjuicios, se declarará en todo caso el derecho a la reparación, señalando asimismo quién viene obligado a indemnizar. La sentencia fijará la cuantía de la indemnización:","o":["En todo caso.","Cuando lo pida expresamente el demandante y consten probados en autos elementos suficientes para ello.","Cuando lo pida expresamente al demandante o al Ministerio Fiscal y consten probados en autos elementos suficientes para ello.","Solo cuando lo solicite el Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando lo pida expresamente el demandante y consten probados en autos elementos suficientes para ello.</mark></span><span class=\"ref-norma\">Art. 71.1.d) · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. De conformidad con el artículo 71.1.d) LJCA."},{"i":"13-325","p":"Otros modos de terminación del procedimiento. Señale la INCORRECTA.","o":["El recurso se podrá desistir en cualquier momento anterior a la sentencia.","Para que el desistimiento del representante en juicio produzca efectos será necesario que lo ratifique el recurrente o que esté autorizado para ello.","Cuando el procedimiento afecte a otros posibles interesados, el Juez o Tribunal les dará cuenta para que reanuden la que les convenga.","El desistimiento implicará necesariamente la condena en costas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El desistimiento implicará necesariamente la condena en costas.</mark></span><span class=\"ref-norma\">Art. 74.6 · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. De conformidad con el artículo 74.6 LJCA."},{"i":"13-350","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-administrativa. Otros modos de terminación del procedimiento. El recurrente podrá ______ del recurso en cualquier momento anterior a la sentencia.","o":["Desistir.","Renunciar.","Allanarse.","Suspender."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Desistir.</mark></span><span class=\"ref-norma\">Art. 74.1 · De la Sentencia y otros Modos de Terminación del Procedimiento</span>. De conformidad con el artículo 74.1 LJCA."},{"i":"13-ia-5","p":"Ley 29/1998, art. 74.5. Si fueren varios los recurrentes y alguno de ellos desiste del recurso, ¿qué ocurre con el procedimiento?","o":["Terminará para todos los recurrentes.","Quedará suspendido hasta que los demás ratifiquen el desistimiento.","Continuará solo si el Ministerio Fiscal así lo solicita.","Continuará respecto de aquellos que no hubieren desistido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Continuará respecto de aquellos que no hubieren desistido</mark></span>El <span class=\"ref-norma\">art. 74.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si fueren varios los recurrentes, el procedimiento continuará respecto de aquellos que no hubieren desistido.\"</span>. Por qué fallan las otras: el desistimiento de uno no arrastra a los demás. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-12","p":"Ley 29/1998, art. 71.2. ¿Qué no podrán determinar los órganos jurisdiccionales cuando estimen un recurso contra una disposición general?","o":["La forma en que han de quedar redactados los preceptos de la disposición en sustitución de los que anularen.","La anulación total o parcial de la disposición o del acto recurrido, cuando proceda.","Que cese o se modifique la actuación impugnada, si la sentencia estima el recurso.","El plazo para que se cumpla el fallo, cuando consista en emitir un acto obligatorio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La forma en que han de quedar redactados los preceptos de la disposición en sustitución de los que anularen</mark></span>El <span class=\"ref-norma\">art. 71.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Los órganos jurisdiccionales no podrán determinar la forma en que han de quedar redactados los preceptos de una disposición general en sustitución de los que anularen ni podrán determinar el contenido discrecional de los actos anulados.\"</span>. Por qué fallan las otras: anular la disposición, ordenar que cese o se modifique la actuación y fijar plazo de cumplimiento son pronunciamientos que sí puede hacer la sentencia estimatoria (art. 71.1). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-14","p":"Ley 29/1998, art. 74.3. Presentado el desistimiento, ¿por qué plazo común da traslado el letrado de la Administración de Justicia a las demás partes (y al Ministerio Fiscal en los supuestos de acción popular)?","o":["Diez días.","Cinco días.","Tres días.","Quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cinco días</mark></span>El <span class=\"ref-norma\">art. 74.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El letrado o letrada de la Administración de Justicia dará traslado a las demás partes, y en los supuestos de acción popular al Ministerio Fiscal, por plazo común de cinco días.\"</span>. Por qué fallan las otras: el plazo de diez días del art. 74.7 es para las alegaciones complementarias sobre la revocación del reconocimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-16","p":"Ley 29/1998, art. 77.1. ¿En qué momento puede el Juez o Tribunal, de oficio o a solicitud de parte, someter a la consideración de las partes el reconocimiento de hechos o documentos o la posibilidad de un acuerdo que ponga fin a la controversia?","o":["Antes de admitir a trámite el recurso.","Una vez practicada la prueba y antes de las conclusiones.","Una vez formuladas la demanda y la contestación.","Solo tras haber sido declarado el pleito concluso para sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una vez formuladas la demanda y la contestación</mark></span>El <span class=\"ref-norma\">art. 77.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En los procedimientos en primera o única instancia, el Juez o Tribunal, de oficio o a solicitud de parte, una vez formuladas la demanda y la contestación, podrá someter a la consideración de las partes el reconocimiento de hechos o documentos, así como la posibilidad de alcanzar un acuerdo que ponga fin a la controversia...\"</span>. Por qué fallan las otras: el momento legal es tras demanda y contestación, antes de la prueba. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-17","p":"Ley 29/1998, art. 74.2. Para que el desistimiento del representante en juicio produzca efectos será necesario:","o":["Que lo apruebe el Ministerio Fiscal.","Que lo ratifique el recurrente o que esté autorizado para ello.","Que lo ratifique el letrado de la Administración de Justicia.","Que no se oponga la parte demandada en el plazo de diez días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que lo ratifique el recurrente o que esté autorizado para ello</mark></span>El <span class=\"ref-norma\">art. 74.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Para que el desistimiento del representante en juicio produzca efectos será necesario que lo ratifique el recurrente o que esté autorizado para ello.\"</span>. Por qué fallan las otras: ni el Fiscal ni el letrado intervienen en la ratificación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-18","p":"Ley 29/1998, art. 74.8. Desistido un recurso de apelación o de casación, el letrado de la Administración de Justicia, sin más trámites, declarará terminado el procedimiento mediante:","o":["Decreto, ordenando el archivo de los autos y la devolución de las actuaciones al órgano de procedencia.","Auto, previa audiencia de las demás partes y del Ministerio Fiscal por cinco días.","Sentencia, que será recurrible en reposición ante el mismo órgano.","Diligencia de ordenación, sin devolución de las actuaciones al órgano de procedencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Decreto, ordenando el archivo de los autos y la devolución de las actuaciones al órgano de procedencia</mark></span>El <span class=\"ref-norma\">art. 74.8 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Desistido un recurso de apelación o de casación, el letrado o la letrada de la Administración de Justicia sin más trámites declarará terminado el procedimiento por decreto, ordenando el archivo de los autos y la devolución de las actuaciones recibidas al órgano jurisdiccional de procedencia.\"</span>. Por qué fallan las otras: el desistimiento de apelación o casación no exige trámite de audiencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-49","p":"Ley 29/1998, art. 73. Las sentencias firmes que anulen un precepto de una disposición general no afectarán por sí mismas a la eficacia de las sentencias o actos administrativos firmes que lo hayan aplicado antes de que la anulación alcanzara efectos generales, salvo:","o":["El caso de que la anulación afectase a más de cien personas determinadas e identificadas en la sentencia firme.","El caso de que la Administración autora de la disposición lo solicitase en el plazo de un mes.","El caso de que la anulación del precepto supusiera la exclusión o la reducción de las sanciones aún no ejecutadas completamente.","El caso de que se tratase de disposiciones generales de las Entidades locales o de las Comunidades Autónomas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El caso de que la anulación del precepto supusiera la exclusión o la reducción de las sanciones aún no ejecutadas completamente</mark></span>El <span class=\"ref-norma\">art. 73 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Las sentencias firmes que anulen un precepto de una disposición general no afectarán por sí mismas a la eficacia de las sentencias o actos administrativos firmes que lo hayan aplicado antes de que la anulación alcanzara efectos generales, salvo en el caso de que la anulación del precepto supusiera la exclusión o la reducción de las sanciones aún no ejecutadas completamente.\"</span>. Por qué fallan las otras: la única excepción legal es la de las sanciones aún no ejecutadas por completo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-58","p":"Ley 29/1998, art. 68.1. ¿Cuál de los siguientes NO es uno de los fallos que puede pronunciar la sentencia?","o":["Inadmisibilidad del recurso contencioso-administrativo.","Estimación del recurso contencioso-administrativo.","Sobreseimiento del recurso.","Desestimación del recurso contencioso-administrativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sobreseimiento del recurso</mark></span>El <span class=\"ref-norma\">art. 68.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La sentencia pronunciará alguno de los fallos siguientes: a) Inadmisibilidad del recurso contencioso-administrativo. b) Estimación o desestimación del recurso contencioso-administrativo\"</span>. Por qué fallan las otras: solo existen esos fallos; el sobreseimiento no figura entre ellos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-59","p":"Ley 29/1998, art. 68.2. Además del fallo que corresponda, ¿qué contendrá la sentencia?","o":["La condena en costas al recurrente en todo caso.","El pronunciamiento que corresponda respecto de las costas.","La fijación de los honorarios del Abogado de la parte vencedora.","La orden de publicación del fallo en el periódico oficial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El pronunciamiento que corresponda respecto de las costas</mark></span>El <span class=\"ref-norma\">art. 68.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La sentencia contendrá además el pronunciamiento que corresponda respecto de las costas\"</span>. Por qué fallan las otras: la sentencia siempre se pronuncia sobre las costas, pero el sentido del pronunciamiento no está predeterminado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-62","p":"Ley 29/1998, art. 71.1.d). Si la sentencia estima una pretensión de resarcir daños y perjuicios pero no fija la cuantía de la indemnización, ¿qué establecerá?","o":["Las bases para la determinación de la cuantía, cuya definitiva concreción quedará diferida al período de ejecución de sentencia.","Una cantidad simbólica que se fijará de oficio.","La remisión a la jurisdicción civil para fijar la cuantía.","El archivo de la pretensión indemnizatoria por falta de prueba."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las bases para la determinación de la cuantía, cuya definitiva concreción quedará diferida al período de ejecución de sentencia</mark></span>El <span class=\"ref-norma\">art. 71.1.d) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si fuera estimada una pretensión de resarcir daños y perjuicios, se declarará en todo caso el derecho a la reparación, señalando asimismo quién viene obligado a indemnizar. La sentencia fijará también la cuantía de la indemnización cuando lo pida expresamente el demandante y consten probados en autos elementos suficientes para ello. En otro caso, se establecerán las bases para la determinación de la cuantía, cuya definitiva concreción quedará diferida al período de ejecución de sentencia\"</span>. Por qué fallan las otras: la cuantía solo se fija en sentencia si se pide y consta prueba; si no, bases y concreción en ejecución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-95","p":"Ley 29/1998, art. 72.3. La estimación de pretensiones de reconocimiento o restablecimiento de una situación jurídica individualizada:","o":["Producirá efectos para todas las personas afectadas.","Producirá efectos generales desde la publicación del fallo.","Solo producirá efectos entre las partes, sin posibilidad alguna de extensión a terceros.","Solo producirá efectos entre las partes, sin perjuicio de que puedan extenderse a terceros en los términos de los arts. 110 y 111."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Solo producirá efectos entre las partes, sin perjuicio de que puedan extenderse a terceros en los términos de los arts. 110 y 111</mark></span>El <span class=\"ref-norma\">art. 72.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La estimación de pretensiones de reconocimiento o restablecimiento de una situación jurídica individualizada sólo producirá efectos entre las partes. No obstante, tales efectos podrán extenderse a terceros en los términos previstos en los artículos 110 y 111\"</span>. Por qué fallan las otras: efectos entre las partes, con la vía de la extensión (arts. 110 y 111); los efectos generales son de la anulación de disposiciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-96","p":"Ley 29/1998, art. 77.2. Sobre el intento de conciliación en el procedimiento en primera o única instancia (art. 77.2):","o":["Suspenderá siempre el curso de las actuaciones y solo podrá intentarse antes de la contestación a la demanda.","No suspenderá el curso de las actuaciones en ningún caso y deberá intentarse antes de la demanda.","No suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen, y podrá producirse en cualquier momento anterior al día en que el pleito haya sido declarado concluso para sentencia.","Suspenderá el curso de las actuaciones si lo solicita la Administración demandada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen, y podrá producirse en cualquier momento anterior al día en que el pleito haya sido declarado concluso para sentencia</mark></span>El <span class=\"ref-norma\">art. 77.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El intento de conciliación no suspenderá el curso de las actuaciones salvo que todas las partes personadas lo solicitasen y podrá producirse en cualquier momento anterior al día en que el pleito haya sido declarado concluso para sentencia\"</span>. Por qué fallan las otras: la suspensión exige que lo pidan todas las partes personadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-107","p":"Ley 29/1998, art. 67.2. Cuando el Juez o Tribunal aprecie que la sentencia no podrá dictarse dentro del plazo de diez días, ¿qué hará?","o":["Lo razonará debidamente y señalará una fecha posterior concreta en la que se dictará, notificándolo a las partes.","Prorrogará el plazo automáticamente por otros diez días.","Solicitará autorización a la Sala de Gobierno para dictarla fuera de plazo.","Dictará la sentencia sin plazo, notificándola cuando esté lista."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Lo razonará debidamente y señalará una fecha posterior concreta en la que se dictará, notificándolo a las partes</mark></span>El <span class=\"ref-norma\">art. 67.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Cuando el Juez o Tribunal apreciase que la sentencia no podrá dictarse dentro del plazo indicado, lo razonará debidamente y señalará una fecha posterior concreta en la que se dictará la misma, notificándolo a las partes\"</span>. Por qué fallan las otras: debe razonarlo, fijar fecha concreta y notificarlo a las partes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-125","p":"Ley 29/1998, art. 71.1.c). Si la medida a adoptar por la sentencia estimatoria consistiera en la emisión de un acto o en la práctica de una actuación jurídicamente obligatoria, la sentencia:","o":["Podrá establecer plazo para que se cumpla el fallo.","Deberá establecer siempre un plazo de un mes.","No podrá fijar plazo alguno.","Remitirá al órgano administrativo para que fije el plazo libremente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Podrá establecer plazo para que se cumpla el fallo</mark></span>El <span class=\"ref-norma\">art. 71.1.c) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si la medida consistiera en la emisión de un acto o en la práctica de una actuación jurídicamente obligatoria, la sentencia podrá establecer plazo para que se cumpla el fallo\"</span>. Por qué fallan las otras: fijar plazo es una facultad («podrá»), no una obligación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-126","p":"Ley 29/1998, art. 74.6. El desistimiento del recurso:","o":["Implicará siempre la condena en costas al recurrente.","No implicará necesariamente la condena en costas.","Eximirá en todo caso de costas al recurrente.","Implicará la condena en costas solo si el desistimiento es de la Administración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No implicará necesariamente la condena en costas</mark></span>El <span class=\"ref-norma\">art. 74.6 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El desistimiento no implicará necesariamente la condena en costas\"</span>. Por qué fallan las otras: la condena en costas no es automática. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"}]},{"a":"De la Ejecución de Sentencias","q":[{"i":"13-3","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Ejecución de sentencias. Transcurridos __________ a partir de la comunicación de la sentencia o el plazo fijado en ésta para el cumplimiento del fallo conforme al artículo 71.1.c), cualquiera de las partes y personas afectadas podrá instar su ejecución forzosa.","o":["Veinte días.","Treinta días.","Dos meses.","Seis meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos meses.</mark></span><span class=\"ref-norma\">Art. 104 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Transcurridos dos meses a partir de la comunicación de la sentencia o el plazo fijado en ésta para el cumplimiento del fallo conforme al artículo 71.1.c), cualquiera de las partes y personas afectadas podrá instar su ejecución forzosa.\"</span> Fundamento: TÍTULO IV. Capítulo IV. Ejecución de sentencias. Artículo 104.2 LJCA: “Transcurridos dos meses a partir de la comunicación de la sentencia o el plazo fijado en ésta para el cumplimiento del fallo conforme al artículo 71.1.c), cualquiera de las partes y personas afectadas podrá instar su ejecución forzosa.”"},{"i":"13-4","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Cuando la sentencia estimare el recurso contencioso-administrativo: Señale la incorrecta.","o":["Si lo hubiese pretendido, el reconocimiento y restablecimiento de una situación jurídica individualizada, reconocerá dicha situación jurídica y adoptará cuantas medidas sean necesarias para el restablecimiento parcial de la misma.","Si la medida consistiera en la emisión de un acto o en la práctica de una actuación jurídicamente obligatoria, la sentencia podrá establecer plazo para que se cumpla lo fallado.","Declarará no ser conforme a Derecho y, en su caso, anulará total o parcialmente la disposición o acto recurrido o dispondrá que cese o se modifique la actuación impugnada.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El restablecimiento debe ser pleno, no 'parcial'.</mark></span><span class=\"ref-norma\">Art. 71.1.c) · De la Ejecución de Sentencias</span>. Fundamento: TÍTULO IV. Capítulo IV. Ejecución de sentencias / Sentencia. Artículo 71.1.c) LJCA: “Si lo hubiese pretendido, el reconocimiento de una situación jurídica individualizada y el restablecimiento de la misma, reconocerá dicha situación jurídica y adoptará cuantas medidas sean necesarias para el pleno restablecimiento de la misma.” La ley exige el restablecimiento pleno, no parcial."},{"i":"13-9","p":"Ley 29/1998, reguladora de la Jurisdicción Contencioso-Administrativa. Los actos y disposiciones contrarios a los pronunciamientos de las sentencias que se dicten con la finalidad de eludir su cumplimiento serán:","o":["Nulos de pleno derecho.","Suspendidos de pleno derecho.","Anulables.","Inaplicables y posteriormente anulados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Nulos de pleno derecho.</mark></span><span class=\"ref-norma\">Art. 103 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Todas las personas y entidades públicas y privadas están obligadas a prestar la colaboración requerida por los Jueces y Tribunales de lo Contencioso-administrativo para la debida y completa ejecución de lo resuelto. Serán nulos de pleno derecho los actos y disposiciones contrarios a los pronunciamientos de las sentencias, que se dicten con la finalidad de eludir su cumplimiento.\"</span> Fundamento: TÍTULO IV. Capítulo IV. Ejecución de sentencias. Artículo 103.4 LJCA: “Serán nulos de pleno derecho los actos y disposiciones contrarios a los pronunciamientos de las sentencias, que se dicten con la finalidad de eludir su cumplimiento.”"},{"i":"13-20","p":"De la Jurisdicción Contencioso-Administrativa. Los actos y disposiciones contrarios a los pronunciamientos de las sentencias, que se dicten con la finalidad de eludir su cumplimiento","o":["Serán anulables de pleno derecho.","Serán anulables.","Producirán el efecto de caducidad de los mismos.","Serán nulos de pleno derecho."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Serán nulos de pleno derecho</mark></span><span class=\"ref-norma\">Art. 105.1 · De la Ejecución de Sentencias</span>. Fundamento: Según el artículo 105.1 de la LJCA, los actos y disposiciones que se dicten con la finalidad de eludir el cumplimiento de las sentencias son nulos de pleno derecho."},{"i":"13-21","p":"De la Jurisdicción Contencioso-Administrativa. Del escrito planteando la cuestión incidental el Secretario Judicial dará traslado a las partes para que, en plazo común que ________ aleguen lo que estimen procedente.","o":["Excederá de diez días.","No excederá de quince días.","No excederá de veinte días.","No excederá de veintidós días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No excederá de veinte días</mark></span>Fundamento: Ejecución de sentencias y demás títulos ejecutivos. Según el esquema-resumen del temario (bloque de repaso de la Ley de la Jurisdicción Contencioso-administrativa), del escrito planteando la cuestión incidental el Secretario judicial (hoy Letrado de la Administración de Justicia) dará traslado a las partes para que, en plazo común que no excederá de veinte días, aleguen lo que estimen procedente."},{"i":"13-27","p":"Reguladora de la Jurisdicción Contencioso-Administrativa. Cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por","o":["El procedimiento especial.","El procedimiento abreviado.","El procedimiento ordinario.","El procedimiento general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El procedimiento abreviado</mark></span>Según el <span class=\"ref-norma\">art. 29.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por el procedimiento abreviado regulado en el artículo 78.\"</span> (verificado con el texto del temario)."},{"i":"13-28","p":"Reguladora de la Jurisdicción Contencioso-Administrativa. Transcurrido el plazo de remisión del expediente sin haberse recibido completo, se reiterará la reclamación y, si no se enviara se impondrá una multa coercitiva. La multa será reiterada cada ________ hasta el cumplimiento de lo requerido.","o":["Diez días.","Quince días.","Veinte días.","Treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días</mark></span><span class=\"ref-norma\">Art. 48.7 · De la Ejecución de Sentencias</span>. Fundamento: El artículo 48.7 de la LJCA dispone que, una vez impuesta la multa coercitiva por no remitir el expediente completo, esta será reiterada cada veinte días hasta el cumplimiento de lo requerido."},{"i":"13-51","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición del recurso y reclamación del expediente. Transcurrido el plazo de remisión del expediente sin haberse recibido completo, se reiterará la reclamación y, si no se enviara en el plazo determinado, tras constatarse su responsabilidad, previo apercibimiento del Secretario Judicial notificado personalmente para formulación de alegaciones, el Juez o Tribunal impondrá una multa coercitiva a la autoridad o empleado responsable de","o":["Ciento cincuenta a mil doscientos euros.","Trescientos a mil doscientos euros.","Trescientos a mil quinientos euros.","Cuatrocientos a mil euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Trescientos a mil doscientos euros</mark></span>Los 150 a 1.500 euros son las multas del art. 112 (incumplimiento del fallo), no las del art. 48. Según el <span class=\"ref-norma\">art. 48.7 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...el juez, la jueza o el tribunal impondrán una multa coercitiva de trescientos a mil doscientos euros a la autoridad o empleado responsable. La multa será reiterada cada veinte días, hasta el cumplimiento de lo requerido.\"</span> (verificado con el texto del temario)."},{"i":"13-60","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Actividad administrativa impugnable. Cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de ___________ desde tal petición, podrán los solicitantes formular recurso contencioso- administrativo.","o":["Un mes.","Tres meses.","Diez días.","Dos meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un mes</mark></span><span class=\"ref-norma\">Art. 29.2 · De la Ejecución de Sentencias</span>. Fundamento: El artículo 29.2 de la LJCA, relativo al recurso por inactividad de la Administración, establece que si la Administración no ejecutare lo solicitado en el plazo de un mes desde la petición, se podrá formular recurso contencioso-administrativo."},{"i":"13-62","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia, de las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la Administración pública, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia?","o":["La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados de lo Contencioso-administrativo.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo</mark></span><span class=\"ref-norma\">Art. 8 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Conocerán también los Juzgados de lo Contencioso-administrativo de las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la administración pública, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia.\"</span> Fundamento: El artículo 8.6 de la LJCA atribuye esta competencia a los Juzgados de lo Contencioso-administrativo, para autorizar la entrada en domicilios para la ejecución forzosa de actos administrativos."},{"i":"13-72","p":"Contencioso-administrativa. Interposición de recurso y reclamación del expediente. En relación con el requerimiento efectuado por el Secretario judicial para la remisión del expediente por parte de la Administración. El expediente deberá ser remitido en el plazo improrrogable de ________, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido.","o":["Quince días.","Veinte días.","Diez días.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Veinte días</mark></span>El plazo es de veinte días, no quince. Según el <span class=\"ref-norma\">art. 48.3 de la Ley 29/1998 (LJCA)</span>: <span class=\"ref-concepto\">\"El expediente deberá ser remitido en el plazo improrrogable de veinte días, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido\"</span> (verificado con el texto oficial)."},{"i":"13-91","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Ejecución de sentencias. Luego que sea firme una sentencia, el Secretario Judicial lo comunicará en el plazo de _____ al órgano que hubiera realizado la actividad objeto del recurso. Señale la opción correcta.","o":["Quince días.","Diez días.","Tres días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 104.1 · De la Ejecución de Sentencias</span>. Fundamento: El artículo 104.1 de la LJCA establece que, una vez firme la sentencia, el Letrado de la Administración de Justicia (anteriormente Secretario Judicial) la comunicará al órgano competente en el plazo de diez días."},{"i":"13-101","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Ejecución de sentencias. ¿Quiénes estarán obligados a prestar la colaboración requerida por los Jueces y Tribunales de lo Contencioso-administrativo para la debida y completa ejecución de lo resuelto?","o":["Todas las personas.","Todas las entidades públicas.","Todas las entidades privadas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 104.2 · De la Ejecución de Sentencias</span>. Fundamento: El artículo 104.2 de la LJCA indica que todas las personas y entidades públicas y privadas están obligadas a prestar la colaboración requerida."},{"i":"13-107","p":"Jurisdicción Contencioso-Administrativa, establece que cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de ____ desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo.","o":["Un mes desde la fecha de la petición.","Dos meses desde la fecha de la petición.","Tres meses desde la fecha de la petición.","Dos meses desde el día siguiente de la petición."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un mes desde la fecha de la petición</mark></span><span class=\"ref-norma\">Art. 29.2 · De la Ejecución de Sentencias</span>. Fundamento: Según el Art. 29.2 de la LJCA, si la Administración no ejecuta un acto firme en el plazo de un mes desde que el interesado solicita la ejecución, este puede interponer recurso contencioso-administrativo por inactividad."},{"i":"13-112","p":"Contencioso-Administrativa. Los actos y disposiciones contrarios a los pronunciamientos de las sentencias, que se dicten con la finalidad de eludir su cumplimiento se declararán nulos","o":["En cualquier caso por el órgano jurisdiccional a quien corresponda la ejecución de la sentencia.","Por el órgano jurisdiccional a quien corresponda la ejecución de la sentencia.","Por el órgano jurisdiccional o quien corresponda la ejecución de la sentencia, salvo que careciese de competencia para ello conforme a lo dispuesto en esta Ley.","Por los Juzgados y Tribunales de éste orden jurisdiccional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por el órgano jurisdiccional a quien corresponda la ejecución de la sentencia</mark></span><span class=\"ref-norma\">Art. 103.4 · De la Ejecución de Sentencias</span>. Fundamento: El Art. 103.4 de la LJCA establece que los actos contrarios a sentencias firmes son nulos de pleno derecho y que El órgano jurisdiccional a quien corresponda la ejecución declarará esta circunstancia."},{"i":"13-148","p":"Reguladora de la Jurisdicción Contencioso-Administrativa. Las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la administración pública corresponderán a","o":["Los Juzgados de lo Contencioso-administrativo.","Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo</mark></span><span class=\"ref-norma\">Art. 8 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Conocerán también los Juzgados de lo Contencioso-administrativo de las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la administración pública, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia.\"</span> Fundamento: Corresponde a los Juzgados de lo Contencioso-Administrativo conocer de las autorizaciones para la entrada en domicilios y lugares que requieran el consentimiento del titular, siempre que procedan para la ejecución forzosa de actos de la Administración Pública (Art. 8.2.j) LJCA)."},{"i":"13-195","p":"La Administración pública, los demás partes procesales y las personas afectadas por el fallo, mientras no conste en autos la total ejecución de la sentencia, podrán promover incidente para decidir, sin contrariar el contenido del fallo, cuantas cuestiones se planteen en la ejecución y especialmente las siguientes","o":["Si un tercero o interesado debe reponer o no la legalidad vulnerada por actos o disposiciones recurridas y anuladas, por los órganos jurisdiccionales de lo contencioso-administrativo.","Plazo máximo para su cumplimiento, en atención a las circunstancias que concurran.","Medios con que ha de llevarse a efecto el procedimiento a seguir.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 109.1 · De la Ejecución de Sentencias</span>. Fundamento: Ejecución de sentencias. El artículo 109.1 LJCA establece que la Administración pública, las demás partes procesales y las personas afectadas por el fallo, mientras no conste en autos la total ejecución de la sentencia, podrán promover incidente para decidir, sin contrariar el contenido del fallo, cuantas cuestiones se planteen en la ejecución, y especialmente sobre: a) órgano administrativo que ha de responsabilizarse de realizar las actuaciones; b) plazo máximo para su cumplimiento, en atención a las circunstancias que concurran; y c) medios con que ha de llevarse a efecto y procedimiento a seguir. Por tanto, todas las opciones enumeradas son correctas."},{"i":"13-207","p":"Jurisdicción Contencioso-administrativa. Ejecución de sentencias. Luego que sea firme una sentencia, el letrado o letrada de la Administración de Justicia lo comunicará en el plazo de __________ al órgano previamente identificado como responsable de su cumplimiento, a fin de que, recibida la comunicación, la lleve a puro y debido efecto y practique lo que exija el cumplimiento de las declaraciones contenidas en el fallo.","o":["Seis días.","Diez días.","Quince días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 104 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Luego que sea firme una sentencia, el letrado o letrada de la Administración de Justicia lo comunicará en el plazo de diez días al órgano previamente identificado como responsable de su cumplimiento, a fin de que, recibida la comunicación, la lleve a puro y debido efecto y practique lo que exija el cumplimiento de las declaraciones contenidas en el fallo.\"</span> Fundamento: El artículo 104.1 de la LJCA establece que el Letrado de la Administración de Justicia comunicará la sentencia en el plazo de diez días al órgano responsable de su cumplimiento. (Aunque la pregunta 13 es una repetición con distintas opciones, la correcta se encuentra en la base del artículo 104.1)."},{"i":"13-208","p":"Jurisdicción Contencioso-administrativa. Ejecución de sentencias. Luego que sea firme una sentencia, el letrado o letrada de la Administración de Justicia lo comunicará en el plazo de ____________ al órgano previamente identificado como responsable de su cumplimiento, a fin de que, recibida la comunicación, la lleve a puro y debido efecto y practique lo que exija el cumplimiento de las declaraciones contenidas en el fallo.","o":["Seis días.","Diez días.","Quince días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span>Fundamento: Esta es una repetición de la"},{"i":"13-209","p":"Jurisdicción Contencioso-administrativa. Ejecución de sentencias. Luego que sea firme una sentencia, el letrado o letrada de la Administración de Justicia lo comunicará en el plazo de ____________ al órgano previamente identificado como responsable de su cumplimiento, a fin de que, recibida la comunicación, la lleve a puro y debido efecto y practique lo que exija el cumplimiento de las declaraciones contenidas en el fallo.","o":["Seis días.","Diez días.","Quince días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span>Fundamento: Esta es una repetición de la"},{"i":"13-211","p":"Jurisdicción Contencioso-administrativa. Actividad Administrativa Impugnable. Cuando la Administración no ejecute sus actos firmes podrán los solicitantes solicitar su ejecución, y si ésta no se produce en el plazo de ____________ desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por el procedimiento abreviado.","o":["Quince días.","Un mes.","Dos meses.","Tres meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un mes</mark></span>Según el <span class=\"ref-norma\">art. 29.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...si ésta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por el procedimiento abreviado regulado en el artículo 78.\"</span> (verificado con el texto del temario)."},{"i":"13-212","p":"Jurisdicción Contencioso-administrativa. Actividad Administrativa Impugnable. Cuando la Administración no ejecute sus actos firmes podrán los solicitantes solicitar su ejecución, y si ésta no se produce en el plazo de ____________ desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por el procedimiento abreviado.","o":["Quince días.","Un mes.","Dos meses.","Tres meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un mes</mark></span>Según el <span class=\"ref-norma\">art. 29.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...si ésta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por el procedimiento abreviado regulado en el artículo 78.\"</span> (verificado con el texto del temario)."},{"i":"13-228","p":"Jurisdicción Contencioso-administrativa. Ejecución de sentencias y demás títulos ejecutivos. La potestad de hacer ejecutar las sentencias y demás títulos ejecutivos adoptados en el proceso corresponde","o":["A los Jueces, Juzgados y Tribunales de este orden jurisdiccional.","A los Juzgados y Tribunales de cualquier orden jurisdiccional.","A los procuradores, abogados, jueces, juzgados, tribunales y al Ministerio Fiscal.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los Jueces, Juzgados y Tribunales de este orden jurisdiccional</mark></span>Fundamento: Corresponde a los Jueces, Juzgados y Tribunales de este orden jurisdiccional la potestad de hacer ejecutar las sentencias."},{"i":"13-238","p":": Ejecución de sentencias. Transcurridos _____________ a partir de la comunicación de la sentencia o el plazo fijado en ésta para el cumplimiento del fallo conforme a esta ley, cualquiera de las partes y personas afectadas podrá instar su ejecución forzosa.","o":["Tres meses.","Cuatro meses.","Dos meses.","Un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos meses</mark></span><span class=\"ref-norma\">Art. 104 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Transcurridos dos meses a partir de la comunicación de la sentencia o el plazo fijado en ésta para el cumplimiento del fallo conforme al artículo 71.1.c), cualquiera de las partes y personas afectadas podrá instar su ejecución forzosa.\"</span> Fundamento: El plazo es de dos meses a partir de la comunicación de la sentencia o el plazo menor fijado en ella para instar la ejecución forzosa. (Art. 104.2 LJCA)."},{"i":"13-243","p":": Procedimientos especiales. Una vez que se interponga el escrito de interposición del recurso de amparo judicial, ¿en qué plazo efectuará el requerimiento el Secretario Judicial al órgano administrativo correspondiente para que remita el expediente acompañado de los informes y datos que estime procedentes?","o":["En el mismo día de la presentación del recurso.","En los tres días siguientes a la presentación del recurso.","En el mismo día de la presentación del recurso o en el siguiente.","En los cinco días siguientes a la presentación del recurso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el mismo día de la presentación del recurso o en el siguiente</mark></span><span class=\"ref-norma\">Art. 117.1 · De la Ejecución de Sentencias</span>. Fundamento: El Letrado de la Administración de Justicia (antes Secretario Judicial) acordará la remisión del expediente en el mismo día de la presentación del escrito o en el siguiente. (Art. 117.1 LJCA)."},{"i":"13-246","p":": Ejecución de sentencias y demás títulos ejecutivos. La Administración pública, las demás partes procesales y las personas afectadas por el fallo, mientras no conste en autos la total ejecución de la sentencia, podrán promover incidente para decidir, sin contrariar el contenido del fallo, cuantas cuestiones se planteen en la ejecución y especialmente las siguientes","o":["Medios con que ha de llevarse a efecto el procedimiento a seguir.","Órgano que ha de responsabilizarse de realizar las actuaciones.","Plazo mínimo para su cumplimiento en atención a las circunstancias que concurran.","Plazo máximo para su aprobación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Medios con que ha de llevarse a efecto el procedimiento a seguir</mark></span><span class=\"ref-norma\">Art. 105.2 · De la Ejecución de Sentencias</span>. Fundamento: En el incidente de ejecución se pueden decidir cuestiones como los medios con que ha de llevarse a efecto el procedimiento a seguir. Las otras opciones no se mencionan expresamente en el listado de cuestiones del artículo 105.2 de la LJCA, aunque podrían estar relacionadas indirectamente con las que sí aparecen."},{"i":"13-248","p":": Interposición del recurso y reclamación del expediente. Transcurrido el plazo de remisión del expediente sin haberse recibido completo, se reiterará la reclamación y, si no se enviara, previo apercibimiento del Secretario Judicial, el Juez o Tribunal impondrá una multa coercitiva que será reiterada hasta el cumplimiento de lo requerido, cada","o":["Siete días.","Diez días.","Veinte días.","Treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días</mark></span><span class=\"ref-norma\">Art. 48.4 · De la Ejecución de Sentencias</span>. Fundamento: La multa coercitiva se impondrá, previo apercibimiento, y será reiterada hasta el cumplimiento de lo requerido, cada veinte días. (Art. 48.4 LJCA)."},{"i":"13-251","p":": Ejecución de sentencias. En materia tributaria, de personal al servicio de la Administración pública, los efectos de una sentencia firme que hubiera reconocido una situación jurídica individualizada a favor de una o varias personas podrán extenderse a otras, en ejecución de la sentencia, cuando concurran las siguientes circunstancias","o":["Que los interesados se encuentren en idéntica situación jurídica que los favorecidos por el fallo.","Que el juez o tribunal sentenciador fuera también competente, por razón del territorio, para conocer de sus pretensiones de reconocimiento de dicha situación individualizada.","Que soliciten la extensión de los efectos de la sentencia en el plazo de un año desde la última notificación de esta a quienes fueron parte en el proceso.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 110.1 · De la Ejecución de Sentencias</span>. Fundamento: El artículo 110.1 de la LJCA establece tres requisitos para la extensión de efectos, siendo las opciones a), b) y c) correctas. Por lo tanto, todas son correctas."},{"i":"13-257","p":"Jurisdicción Contencioso-administrativa. Ejecución de sentencias. Si la sentencia anulara total o parcialmente una disposición general o un acto administrativo que afecte a una pluralidad indeterminada de personas, el Secretario del órgano judicial ordenará su publicación en diario oficial en el plazo de _____ a contar desde la firmeza de la sentencia.","o":["Diez días.","Quince días.","Veinte días.","Treinta días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span>Fundamento: La LJCA establece el plazo de diez días para la publicación en diario oficial de la anulación de una disposición general o un acto que afecte a una pluralidad indeterminada de personas."},{"i":"13-262","p":"Jurisdicción Contencioso-administrativa. Si no se hubiere fijado plazo para el cumplimiento de las obligaciones derivadas del acuerdo, la parte perjudicada podrá requerir a la otra su cumplimiento y transcurridos _____ podrá proceder a instar su ejecución forzosa.","o":["Seis meses.","Ocho meses.","Dos meses.","Cuatro meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos meses</mark></span>Según el <span class=\"ref-norma\">art. 113.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Si no se hubiere fijado plazo para el cumplimiento de las obligaciones derivadas del acuerdo, la parte perjudicada podrá requerir a la otra su cumplimiento y transcurridos dos meses podrá proceder a instar su ejecución forzosa.\"</span> (verificado con el texto del temario)."},{"i":"13-267","p":"Jurisdicción Contencioso-administrativa. Ejecución de Sentencias. La Administración pública, las demás partes procesales y las personas afectadas por el fallo, mientras no conste en autos la total ejecución de la sentencia, podrán promover incidente para decidir, sin contrariar el contenido del fallo, cuantas cuestiones se planteen en la ejecución y especialmente las siguientes","o":["Órgano administrativo que ha de responsabilizarse de realizar las actuaciones.","Plazo máximo para su cumplimiento, en atención a las circunstancias que concurran.","Medios con que ha de llevarse a efecto y procedimiento a seguir.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 109 · De la Ejecución de Sentencias</span>. Fundamento: El incidente de ejecución (art. 109 LJCA) puede promoverse para decidir las cuestiones que se planteen en la ejecución sin contrariar el fallo, incluyendo las mencionadas en las opciones a), b) y c), por lo que Todas son correctas."},{"i":"13-269","p":"Jurisdicción Contencioso-administrativa. Ejecución de sentencias y demás títulos ejecutivos. Señale la INCORRECTA","o":["Podrá suspenderse el cumplimiento si desluce la impugnación total o parcial del fallo.","Luego que sea firme una sentencia, el letrado o letrada de la Administración de Justicia lo comunicará en el plazo de diez días al órgano previamente identificado como responsable de su cumplimiento, a fin de que, recibida la comunicación, la lleve a puro y debido efecto y practique lo que exija el cumplimiento de las declaraciones contenidas en el fallo.","Serán nulos de pleno derecho los actos y disposiciones contrarios a los pronunciamientos de las sentencias, que se dicten con la finalidad de eludir su cumplimiento.","Las partes están obligadas a cumplir las sentencias en la forma y términos que en éstas se consignen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Podrá suspenderse el cumplimiento si desluce la impugnación total o parcial del fallo</mark></span><span class=\"ref-norma\">Art. 104 · De la Ejecución de Sentencias</span>. Fundamento: La opción a) es la INCORRECTA. No se contempla la suspensión del cumplimiento por la impugnación; al contrario, las sentencias firmes deben cumplirse. Las opciones b), c) y d) son correctas según la LJCA (art. 104, 103, y 103, respectivamente)."},{"i":"13-272","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. Los actos y disposiciones contrarios a los pronunciamientos de las sentencias, que se dicten con la finalidad de eludir su cumplimiento:","o":["Serán anulables de pleno derecho.","Serán anulables.","Producirán el efecto de caducidad de los mismos.","Serán nulos de pleno derecho."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Serán nulos de pleno derecho.</mark></span><span class=\"ref-norma\">Art. 103.4 · De la Ejecución de Sentencias</span>. De conformidad con el artículo 103.4 LJCA."},{"i":"13-279","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. Cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por:","o":["El procedimiento especial.","El procedimiento abreviado.","El procedimiento ordinario.","El procedimiento general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El procedimiento abreviado.</mark></span><span class=\"ref-norma\">Art. 29 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por el procedimiento abreviado regulado en el artículo 78.\"</span> De conformidad con el artículo 29.2 LJCA."},{"i":"13-280","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. Transcurrido el plazo de remisión del expediente sin haberse recibido completo, se reiterará la reclamación y, si no se enviara se impondrá una multa coercitiva. La multa será reiterada cada ________ hasta el cumplimiento de lo requerido.","o":["Diez días.","Quince días.","Veinte días.","Treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días.</mark></span><span class=\"ref-norma\">Art. 48.7 · De la Ejecución de Sentencias</span>. De conformidad con el artículo 48.7 LJCA."},{"i":"13-291","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Actividad administrativa impugnable. Cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de ___________ desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo.","o":["Un mes.","Tres meses.","Diez días.","Dos meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un mes.</mark></span><span class=\"ref-norma\">Art. 29.2 · De la Ejecución de Sentencias</span>. De conformidad con el artículo 29.2 LJCA."},{"i":"13-293","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia, de las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la Administración pública, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia?","o":["La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados de lo Contencioso-administrativo.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo.</mark></span><span class=\"ref-norma\">Art. 8 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Conocerán también los Juzgados de lo Contencioso-administrativo de las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la administración pública, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia.\"</span> De conformidad con el artículo 8.6 LJCA."},{"i":"13-301","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recurso y reclamación del expediente. En relación con el requerimiento efectuado por el Secretario judicial para la remisión del expediente por parte de la Administración. El expediente deberá ser remitido en el plazo improrrogable de ________, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido.","o":["Quince días.","Veinte días.","Diez días.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Veinte días.</mark></span><span class=\"ref-norma\">Art. 48.3 · De la Ejecución de Sentencias</span>. De conformidad con el artículo 48.3 LJCA."},{"i":"13-308","p":"La Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa, establece que cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de ____ desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo.","o":["Un mes desde la fecha de la petición","Dos meses desde la fecha de la petición","Tres meses desde la fecha de la petición","Dos meses desde el día siguiente de la petición"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un mes desde la fecha de la petición.</mark></span><span class=\"ref-norma\">Art. 29.2 · De la Ejecución de Sentencias</span>. De conformidad con el artículo 29.2 LJCA."},{"i":"13-317","p":"Ley 29/1998, de 13 de Julio, Reguladora de la Jurisdicción Contencioso-Administrativa. Las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la administración pública corresponderán a:","o":["Los Juzgados de lo Contencioso-administrativo.","Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo.</mark></span><span class=\"ref-norma\">Art. 8 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Conocerán también los Juzgados de lo Contencioso-administrativo de las autorizaciones para la entrada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la administración pública, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia.\"</span> De conformidad con el artículo 8.6 LJCA."},{"i":"13-333","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Ejecución de sentencias. Luego que sea firme una sentencia, el letrado o letrada de la Administración de Justicia lo comunicará en el plazo de __________ al órgano previamente identificado como responsable de su cumplimiento, a fin de que, recibida la comunicación, la lleve a puro y debido efecto y practique lo que exija el cumplimiento de las declaraciones contenidas en el fallo.","o":["Seis días.","Diez días.","Quince días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días.</mark></span><span class=\"ref-norma\">Art. 104 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Luego que sea firme una sentencia, el letrado o letrada de la Administración de Justicia lo comunicará en el plazo de diez días al órgano previamente identificado como responsable de su cumplimiento, a fin de que, recibida la comunicación, la lleve a puro y debido efecto y practique lo que exija el cumplimiento de las declaraciones contenidas en el fallo.\"</span> De conformidad con el artículo 104.1 LJCA."},{"i":"13-335","p":"Ejecución de sentencias. Transcurridos _____________ a partir de la comunicación de la sentencia o el plazo fijado en ésta para el cumplimiento del fallo conforme a esta ley, cualquiera de las partes y personas afectadas podrá instar su ejecución forzosa.","o":["Tres meses.","Cuatro meses.","Dos meses.","Un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos meses.</mark></span><span class=\"ref-norma\">Art. 104 · De la Ejecución de Sentencias</span> dispone: <span class=\"ref-concepto\">\"Transcurridos dos meses a partir de la comunicación de la sentencia o el plazo fijado en ésta para el cumplimiento del fallo conforme al artículo 71.1.c), cualquiera de las partes y personas afectadas podrá instar su ejecución forzosa.\"</span> De conformidad con el artículo 104.2 LJCA."},{"i":"13-342","p":"Ejecución de sentencias y demás títulos ejecutivos. La Administración pública, las demás partes procesales y las personas afectadas por el fallo, mientras no conste en autos la total ejecución de la sentencia, podrán promover incidente para decidir, sin contrariar el contenido del fallo, cuantas cuestiones se planteen en la ejecución y especialmente las siguientes:","o":["Medios con que ha de llevarse a efecto el procedimiento a seguir.","Órgano que ha de responsabilizarse de realizar las actuaciones.","Plazo mínimo para su cumplimiento en atención a las circunstancias que concurran.","Plazo máximo para su aprobación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Medios con que ha de llevarse a efecto el procedimiento a seguir.</mark></span><span class=\"ref-norma\">Art. 109.1.c) · De la Ejecución de Sentencias</span>. De conformidad con el artículo 109.1.c) LJCA."},{"i":"13-344","p":"Interposición del recurso y reclamación del expediente. Transcurrido el plazo de remisión del expediente sin haberse recibido completo, se reiterará la reclamación y, si no se enviara, previo apercibimiento del Secretario Judicial, el Juez o Tribunal impondrá una multa coercitiva que será reiterada hasta el cumplimiento de lo requerido, cada:","o":["Siete días.","Diez días.","Veinte días.","Treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días.</mark></span><span class=\"ref-norma\">Art. 48.7 · De la Ejecución de Sentencias</span>. De conformidad con el artículo 48.7 LJCA."},{"i":"13-347","p":"Ejecución de sentencias. En materia tributaria, de personal al servicio de la Administración pública, los efectos de una sentencia firme que hubiera reconocido una situación jurídica individualizada a favor de una o varias personas podrán extenderse a otras, en ejecución de la sentencia, cuando concurran las siguientes circunstancias:","o":["Que los interesados se encuentren en idéntica situación jurídica que los favorecidos por el fallo.","Que el juez o tribunal sentenciador fuera también competente, por razón del territorio, para conocer de sus pretensiones de reconocimiento de dicha situación individualizada.","Que soliciten la extensión de los efectos de la sentencia en el plazo de un año desde la última notificación de esta a quienes fueron parte en el proceso.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 110.1 · De la Ejecución de Sentencias</span>. De conformidad con el artículo 110.1 LJCA."},{"i":"13-ia-3","p":"Ley 29/1998, art. 103.1. ¿A quién compete el ejercicio de la potestad de hacer ejecutar las sentencias y demás títulos ejecutivos?","o":["Al juzgado o tribunal que haya conocido del asunto en primera o única instancia.","Al tribunal superior que haya resuelto el recurso en último grado.","A la Administración condenada, bajo la vigilancia del Ministerio Fiscal.","Al letrado de la Administración de Justicia, con carácter exclusivo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al juzgado o tribunal que haya conocido del asunto en primera o única instancia</mark></span>El <span class=\"ref-norma\">art. 103.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La potestad de hacer ejecutar las sentencias y demás títulos ejecutivos adoptados en el proceso corresponde exclusivamente a los juzgados y tribunales de este orden jurisdiccional, y su ejercicio compete al que haya conocido del asunto en primera o única instancia.\"</span>. Por qué fallan las otras: la potestad es exclusiva de los órganos jurisdiccionales; no se traslada ni a la Administración ni al letrado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-8","p":"Ley 29/1998, art. 113.1. Transcurrido el plazo de ejecución fijado en el acuerdo que pone fin al procedimiento por transacción (art. 77.3), ¿qué podrá hacer cualquiera de las partes?","o":["Solicitar la nulidad del acuerdo ante el mismo órgano.","Interponer recurso de apelación contra el auto que lo aprobó.","Instar su ejecución forzosa.","Desistir del recurso sin condena en costas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Instar su ejecución forzosa</mark></span>El <span class=\"ref-norma\">art. 113.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Transcurrido el plazo de ejecución que se hubiere fijado en el acuerdo a que se refiere el artículo 77.3, cualquiera de las partes podrá instar su ejecución forzosa.\"</span>. Por qué fallan las otras: el incumplimiento del acuerdo se resuelve por la vía de la ejecución forzosa, no por nulidad, apelación ni desistimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-19","p":"Ley 29/1998, art. 104.3. Atendiendo a la naturaleza de lo reclamado y a la efectividad de la sentencia, ¿qué podrá hacer ésta respecto del plazo para su cumplimiento?","o":["Fijar un plazo inferior al de dos meses cuando éste la haga ineficaz o cause grave perjuicio.","Fijar un plazo superior al de dos meses cuando lo solicite la Administración.","Suspender el plazo hasta que se resuelva el incidente de ejecución.","Eliminar todo plazo y declarar la ejecución inmediata en todo caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Fijar un plazo inferior al de dos meses cuando éste la haga ineficaz o cause grave perjuicio</mark></span>El <span class=\"ref-norma\">art. 104.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Atendiendo a la naturaleza de lo reclamado y a la efectividad de la sentencia, ésta podrá fijar un plazo inferior para el cumplimiento, cuando lo dispuesto en el apartado anterior lo haga ineficaz o cause grave perjuicio.\"</span>. Por qué fallan las otras: la sentencia solo puede ACORTAR el plazo, nunca ampliarlo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-20","p":"Ley 29/1998, art. 105.3. La declaración de concurrencia de causas de utilidad pública o interés social para expropiar los derechos reconocidos frente a la Administración en una sentencia firme habrá de efectuarse dentro de:","o":["El mes siguiente a la firmeza de la sentencia.","Los tres meses siguientes a la comunicación de la sentencia.","Los seis meses siguientes a la notificación de la sentencia.","Los dos meses siguientes a la comunicación de la sentencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los dos meses siguientes a la comunicación de la sentencia</mark></span>El <span class=\"ref-norma\">art. 105.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La declaración de concurrencia de alguna de las causas mencionadas en el párrafo anterior habrá de efectuarse dentro de los dos meses siguientes a la comunicación de la sentencia.\"</span>. Por qué fallan las otras: coincide con los dos meses del art. 104.2 para instar la ejecución forzosa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-22","p":"Ley 29/1998, art. 107.1. Si la sentencia firme anulase total o parcialmente el acto impugnado, ¿qué dispondrá el letrado de la Administración de Justicia a instancia de parte?","o":["La declaración de lesividad del acto anulado para el interés público.","La anulación de oficio de todos los actos dictados en su aplicación.","La remisión del fallo al Ministerio Fiscal para que lo ejecute.","La inscripción del fallo en los registros públicos a que hubiere tenido acceso el acto anulado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La inscripción del fallo en los registros públicos a que hubiere tenido acceso el acto anulado</mark></span>El <span class=\"ref-norma\">art. 107.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si la sentencia firme anulase total o parcialmente el acto impugnado, el Secretario judicial dispondrá, a instancia de parte, la inscripción del fallo en los registros públicos a que hubiere tenido acceso el acto anulado, así como su publicación en los periódicos oficiales o privados, si concurriere causa bastante para ello, a costa de la parte ejecutada.\"</span>. Por qué fallan las otras: solo se inscribe el fallo y, en su caso, se publica; no hay anulación en cascada ni remisión al Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-23","p":"Ley 29/1998, art. 108.3. Cuando el Juez o Tribunal ordene motivadamente la demolición de un inmueble declarado contrario a la normativa, ¿qué exigirá como condición previa, salvo situación de peligro inminente?","o":["El informe favorable del Ministerio Fiscal.","La autorización del Consejo de Gobierno de la Comunidad Autónoma.","La prestación de garantías suficientes para responder del pago de las indemnizaciones debidas a terceros de buena fe.","El pago previo de la indemnización por la Administración condenada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La prestación de garantías suficientes para responder del pago de las indemnizaciones debidas a terceros de buena fe</mark></span>El <span class=\"ref-norma\">art. 108.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"...exigirá, como condición previa a la demolición, y salvo que una situación de peligro inminente lo impidiera, la prestación de garantías suficientes para responder del pago de las indemnizaciones debidas a terceros de buena fe.\"</span>. Por qué fallan las otras: se exigen GARANTÍAS, no el pago previo ni informes o autorizaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-24","p":"Ley 29/1998, art. 111. Declarada la firmeza de la sentencia del pleito preferente, el letrado de la Administración de Justicia requerirá a los recurrentes cuyos recursos se suspendieron (art. 37.2) para que, en el plazo de ___, interesen la extensión de efectos, la continuación del pleito o manifiesten si desisten.","o":["Diez días.","Un mes.","Veinte días.","Cinco días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco días</mark></span>El <span class=\"ref-norma\">art. 111 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"...el Secretario judicial requerirá a los recurrentes afectados por la suspensión para que en el plazo de cinco días interesen la extensión de los efectos de la sentencia o la continuación del pleito suspendido, o bien manifiesten si desisten del recurso.\"</span>. Por qué fallan las otras: el plazo de un año del art. 110.1.c) es para pedir la extensión en el incidente general. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-25","p":"Ley 29/1998, art. 112.a). Transcurridos los plazos para el total cumplimiento del fallo, ¿entre qué cuantías podrá el Juez o la Sala imponer multas coercitivas a las autoridades, funcionarios o agentes que incumplan los requerimientos?","o":["De ciento cincuenta a mil quinientos euros.","De trescientos a mil doscientos euros.","De cien a mil euros.","De seiscientos a tres mil euros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De ciento cincuenta a mil quinientos euros</mark></span>El <span class=\"ref-norma\">art. 112.a) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"...Imponer multas coercitivas de ciento cincuenta a mil quinientos euros a las autoridades, funcionarios o agentes que incumplan los requerimientos del Juzgado o de la Sala, así como reiterar estas multas hasta la completa ejecución del fallo judicial...\"</span>. Por qué fallan las otras: los 300 a 1.200 euros son las multas por no remitir el expediente (art. 48.7). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-36","p":"Ley 29/1998, art. 105.3. ¿Quién efectúa la declaración de concurrencia de las causas de utilidad pública o interés social para expropiar los derechos reconocidos frente a la Administración en una sentencia firme?","o":["El Juez o Tribunal de ejecución, de oficio, previa audiencia del Ministerio Fiscal y de las partes, señalando además por el trámite de los incidentes la indemnización que proceda en todo caso.","El Consejo de Ministros, previo dictamen del Consejo de Estado, sin que el Consejo de Gobierno de la Comunidad Autónoma pueda intervenir nunca ni siquiera respecto de actos de su propia Administración.","El Gobierno de la Nación, y también el Consejo de Gobierno de la Comunidad Autónoma cuando se trate de peligro cierto de alteración grave del libre ejercicio de derechos y libertades y el acto proviniera de su Administración o de las Entidades locales de su territorio.","El Gobierno de la Nación o el Consejo de Gobierno de la Comunidad Autónoma indistintamente, en cualquiera de las tres causas legalmente previstas y con independencia de la Administración autora del acto."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Gobierno de la Nación, y también el Consejo de Gobierno de la Comunidad Autónoma cuando se trate de peligro cierto de alteración grave del libre ejercicio de derechos y libertades y el acto proviniera de su Administración o de las Entidades locales de su territorio</mark></span>El <span class=\"ref-norma\">art. 105.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La declaración de la concurrencia de alguna de las causas citadas se hará por el Gobierno de la Nación; podrá también efectuarse por el Consejo de Gobierno de la Comunidad Autónoma cuando se trate de peligro cierto de alteración grave del libre ejercicio de los derechos y libertades de los ciudadanos y el acto, actividad o disposición impugnados proviniera de los órganos de la Administración de dicha Comunidad o de las Entidades locales de su territorio...\"</span>. Por qué fallan las otras: el Juez solo fija la indemnización (y aprecia el peligro cierto); la competencia autonómica se limita a ese supuesto concreto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-38","p":"Ley 29/1998, art. 110.4. Antes de resolver sobre la extensión de efectos de una sentencia, ¿en qué plazo recabará el Secretario judicial de la Administración los antecedentes y un informe detallado sobre la viabilidad de la extensión?","o":["En los diez días siguientes.","En los cinco días siguientes.","En el mes siguiente.","En los veinte días siguientes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En los veinte días siguientes</mark></span>El <span class=\"ref-norma\">art. 110.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Antes de resolver, en los veinte días siguientes, el Secretario judicial recabará de la Administración los antecedentes que estime oportunos y, en todo caso, un informe detallado sobre la viabilidad de la extensión solicitada, poniendo de manifiesto el resultado de esas actuaciones a las partes para que aleguen por plazo común de cinco días...\"</span>. Por qué fallan las otras: los cinco días son las alegaciones de las partes sobre el resultado de esas actuaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-60","p":"Ley 29/1998, art. 105.1. Según el art. 105.1, respecto del cumplimiento del fallo de una sentencia firme:","o":["Podrá suspenderse por razones de interés público apreciadas por el Gobierno.","No podrá suspenderse el cumplimiento ni declararse la inejecución total o parcial del fallo.","Podrá declararse la inejecución parcial con audiencia de las partes.","Podrá suspenderse durante dos meses a petición de la Administración condenada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No podrá suspenderse el cumplimiento ni declararse la inejecución total o parcial del fallo</mark></span>El <span class=\"ref-norma\">art. 105.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"No podrá suspenderse el cumplimiento ni declararse la inejecución total o parcial del fallo\"</span>. Por qué fallan las otras: la regla es absoluta; la imposibilidad material o legal (art. 105.2) solo permite adoptar medidas e indemnizar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-88","p":"Ley 29/1998, art. 110.5. El incidente de extensión de efectos de una sentencia firme se desestimará, en todo caso, en ciertos supuestos. Señale el que NO figura entre ellos:","o":["Si existiera cosa juzgada.","Que el solicitante no hubiera sido parte en el proceso.","Cuando la doctrina determinante del fallo fuere contraria a la jurisprudencia del Tribunal Supremo.","Si para el interesado se hubiere dictado resolución consentida y firme por no haber promovido recurso contencioso-administrativo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que el solicitante no hubiera sido parte en el proceso</mark></span>El <span class=\"ref-norma\">art. 110.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El incidente se desestimará, en todo caso, cuando concurra alguna de las siguientes circunstancias: a) Si existiera cosa juzgada. b) Cuando la doctrina determinante del fallo cuya extensión se postule fuere contraria a la jurisprudencia del Tribunal Supremo o a la doctrina sentada por los Tribunales Superiores de Justicia en el recurso a que se refiere el artículo 99. c) Si para el interesado se hubiere dictado resolución que, habiendo causado estado en vía administrativa, fuere consentida y firme por no haber promovido recurso contencioso-administrativo\"</span>. Por qué fallan las otras: la extensión se concede precisamente a quienes no fueron parte; no ser parte no es causa de desestimación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-89","p":"Ley 29/1998, art. 110.6. Si se encuentra pendiente un recurso de revisión o un recurso de casación en interés de la ley, ¿qué ocurre con la decisión del incidente de extensión de efectos?","o":["El incidente se desestimará de plano.","El incidente se resolverá sin esperar, con carácter provisional.","El incidente se inadmitirá y podrá reproducirse tras la resolución del recurso.","Quedará en suspenso hasta que se resuelva el citado recurso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Quedará en suspenso hasta que se resuelva el citado recurso</mark></span>El <span class=\"ref-norma\">art. 110.6 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si se encuentra pendiente un recurso de revisión o un recurso de casación en interés de la ley, quedará en suspenso la decisión del incidente hasta que se resuelva el citado recurso\"</span>. Por qué fallan las otras: la decisión queda en suspenso, no se desestima ni se inadmite. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-91","p":"Ley 29/1998, art. 109.1. El incidente para decidir las cuestiones que se planteen en la ejecución de la sentencia puede promoverse sin contrariar el contenido del fallo, y especialmente sobre las siguientes. Señale la que NO figura entre ellas:","o":["La modificación del contenido del fallo para adaptarlo a las circunstancias sobrevenidas.","Órgano administrativo que ha de responsabilizarse de realizar las actuaciones.","Plazo máximo para su cumplimiento, en atención a las circunstancias que concurran.","Medios con que ha de llevarse a efecto y procedimiento a seguir."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La modificación del contenido del fallo para adaptarlo a las circunstancias sobrevenidas</mark></span>El <span class=\"ref-norma\">art. 109.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"podrán promover incidente para decidir, sin contrariar el contenido del fallo, cuantas cuestiones se planteen en la ejecución y especialmente las siguientes: a) Órgano administrativo que ha de responsabilizarse de realizar las actuaciones. b) Plazo máximo para su cumplimiento, en atención a las circunstancias que concurran. c) Medios con que ha de llevarse a efecto y procedimiento a seguir\"</span>. Por qué fallan las otras: el incidente se plantea siempre sin contrariar el contenido del fallo; solo versa sobre órgano responsable, plazo y medios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-98","p":"Ley 29/1998, art. 110.1. Para extender los efectos de una sentencia firme que reconoció una situación jurídica individualizada, los interesados deben solicitar la extensión en el plazo de:","o":["Dos meses desde la firmeza de la sentencia.","Seis meses desde la última notificación de la sentencia a quienes fueron parte.","Un año desde la última notificación de la sentencia a quienes fueron parte en el proceso.","Tres meses desde la publicación de la sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un año desde la última notificación de la sentencia a quienes fueron parte en el proceso</mark></span>El <span class=\"ref-norma\">art. 110.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Que soliciten la extensión de los efectos de la sentencia en el plazo de un año desde la última notificación de ésta a quienes fueron parte en el proceso\"</span>. Por qué fallan las otras: el plazo es de un año y se cuenta desde la última notificación a las partes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-108","p":"Ley 29/1998, art. 103.2. Las partes están obligadas a cumplir las sentencias:","o":["En la forma y términos que en éstas se consignen.","En la forma que acuerde la Administración condenada.","En el plazo de un mes desde su notificación en todo caso.","Cuando lo ordene el letrado de la Administración de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En la forma y términos que en éstas se consignen</mark></span>El <span class=\"ref-norma\">art. 103.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Las partes están obligadas a cumplir las sentencias en la forma y términos que en éstas se consignen\"</span>. Por qué fallan las otras: el cumplimiento se ajusta a lo que consigne la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-127","p":"Ley 29/1998, art. 105.2. Si concurriesen causas de imposibilidad material o legal de ejecutar una sentencia, el órgano obligado a su cumplimiento lo manifestará a la autoridad judicial:","o":["Directamente, en cualquier momento antes de la ejecución forzosa.","A través del representante procesal de la Administración, dentro del plazo previsto en el apartado segundo del artículo anterior.","A través del Ministerio Fiscal, en el plazo de diez días.","Por medio del letrado de la Administración de Justicia, en el plazo de veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A través del representante procesal de la Administración, dentro del plazo previsto en el apartado segundo del artículo anterior</mark></span>El <span class=\"ref-norma\">art. 105.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"el órgano obligado a su cumplimiento lo manifestará a la autoridad judicial a través del representante procesal de la Administración, dentro del plazo previsto en el apartado segundo del artículo anterior\"</span>. Por qué fallan las otras: se manifiesta por medio del representante procesal de la Administración y dentro del plazo de dos meses del art. 104.2. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-131","p":"Ley 29/1998, art. 108.1. Si la sentencia condenare a la Administración a realizar una determinada actividad o a dictar un acto, el Juez o Tribunal podrá, en caso de incumplimiento, adoptar las medidas necesarias para que el fallo adquiera la eficacia inherente al acto omitido, entre las que se incluye:","o":["La ejecución subsidiaria con cargo a la Administración condenada.","La imposición de sanciones disciplinarias al funcionario responsable.","La suspensión de la actividad de la Administración condenada.","La sustitución de la Administración condenada por otra Administración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La ejecución subsidiaria con cargo a la Administración condenada</mark></span>El <span class=\"ref-norma\">art. 108.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Adoptar las medidas necesarias para que el fallo adquiera la eficacia que, en su caso, sería inherente al acto omitido, entre las que se incluye la ejecución subsidiaria con cargo a la Administración condenada\"</span>. Por qué fallan las otras: la medida expresamente mencionada es la ejecución subsidiaria a costa de la Administración condenada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-133","p":"Ley 29/1998, art. 110.2. La solicitud de extensión de efectos de una sentencia firme deberá dirigirse:","o":["A la Administración condenada, que la trasladará al órgano judicial.","Al Tribunal Supremo, en todo caso.","Directamente al órgano jurisdiccional competente que hubiera dictado la resolución de la que se pretende que se extiendan los efectos.","Al letrado de la Administración de Justicia del Juzgado Decano."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Directamente al órgano jurisdiccional competente que hubiera dictado la resolución de la que se pretende que se extiendan los efectos</mark></span>El <span class=\"ref-norma\">art. 110.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La solicitud deberá dirigirse directamente al órgano jurisdiccional competente que hubiera dictado la resolución de la que se pretende que se extiendan los efectos\"</span>. Por qué fallan las otras: se dirige directamente al órgano que dictó la sentencia cuya extensión se pide. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-134","p":"Ley 29/1998, art. 110.7. El régimen de recurso del auto dictado en el incidente de extensión de efectos de una sentencia firme se ajustará:","o":["A las reglas del procedimiento de derechos fundamentales.","A las reglas generales previstas en el art. 80.","A la regla de que contra el auto no cabe recurso alguno.","A las reglas de la apelación en un solo efecto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A las reglas generales previstas en el art. 80</mark></span>El <span class=\"ref-norma\">art. 110.7 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El régimen de recurso del auto dictado se ajustará a las reglas generales previstas en el artículo 80\"</span>. Por qué fallan las otras: el auto sigue el régimen general de recursos (art. 80). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-135","p":"Ley 29/1998, art. 103.5. El órgano jurisdiccional a quien corresponda la ejecución declarará, a instancia de parte, la nulidad de los actos y disposiciones dictados con la finalidad de eludir el cumplimiento de la sentencia:","o":["De oficio, sin audiencia de las partes.","Por el procedimiento ordinario en primera instancia.","Por los trámites previstos en los apartados 2 y 3 del art. 109, salvo que careciese de competencia para ello conforme a esta Ley.","Por el procedimiento del art. 110 de extensión de efectos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por los trámites previstos en los apartados 2 y 3 del art. 109, salvo que careciese de competencia para ello conforme a esta Ley</mark></span>El <span class=\"ref-norma\">art. 103.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El órgano jurisdiccional a quien corresponda la ejecución de la sentencia declarará, a instancia de parte, la nulidad de los actos y disposiciones a que se refiere el apartado anterior, por los trámites previstos en los apartados 2 y 3 del artículo 109, salvo que careciese de competencia para ello conforme a lo dispuesto en esta Ley\"</span>. Por qué fallan las otras: es a instancia de parte y por los trámites de los apartados 2 y 3 del art. 109. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-139","p":"Ley 29/1998, art. 112. Transcurridos los plazos señalados para el total cumplimiento del fallo, el juez o tribunal adoptará, previa audiencia de las partes, las medidas necesarias para lograr la efectividad de lo mandado. Singularmente, acreditada la responsabilidad, podrá además:","o":["Declarar la inejecución del fallo por razones de oportunidad.","Suspender el cumplimiento del fallo hasta nuevo requerimiento.","Imponer sanción disciplinaria directamente a la autoridad responsable.","Deducir el oportuno testimonio de particulares para exigir la responsabilidad penal que pudiera corresponder."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Deducir el oportuno testimonio de particulares para exigir la responsabilidad penal que pudiera corresponder</mark></span>El <span class=\"ref-norma\">art. 112 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Singularmente, acreditada su responsabilidad, previo apercibimiento del Secretario judicial notificado personalmente para formulación de alegaciones, el Juez o la Sala podrán: a) Imponer multas coercitivas de ciento cincuenta a mil quinientos euros ... b) Deducir el oportuno testimonio de particulares para exigir la responsabilidad penal que pudiera corresponder\"</span>. Por qué fallan las otras: además de las multas, se puede deducir testimonio para exigir responsabilidad penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-140","p":"Ley 29/1998, art. 109.3. Evacuado el traslado o transcurrido el plazo de alegaciones en el incidente de ejecución, el Juez o Tribunal dictará auto decidiendo la cuestión planteada en el plazo de:","o":["Cinco días.","Veinte días.","Tres días.","Diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 109.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Evacuado el traslado o transcurrido el plazo a que se refiere el apartado anterior, el Juez o Tribunal dictará auto, en el plazo de diez días, decidiendo la cuestión planteada\"</span>. Por qué fallan las otras: alegaciones hasta veinte días (apartado 2) y auto en diez días (apartado 3). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"}]},{"a":"Del Objeto del Recurso Contencioso-Administrativo","q":[{"i":"13-7","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. En caso de vía de hecho, el interesado podrá formular requerimiento a la Administración actuante, intimando su cesación. Podrá deducir directamente recurso contencioso-administrativo si dicha intimación no hubiere sido formulada o no fuere atendida:","o":["Dentro de los tres días siguientes a la presentación del requerimiento.","Dentro de los diez días siguientes a la presentación del requerimiento.","Dentro de los diez días siguientes a la presentación del requerimiento y dentro de los quince días siguientes a la presentación del requerimiento.","Dentro de los quince días siguientes a la presentación del requerimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dentro de los diez días siguientes a la presentación del requerimiento.</mark></span><span class=\"ref-norma\">Art. 30 · Del Objeto del Recurso Contencioso-Administrativo</span> dispone: <span class=\"ref-concepto\">\"En caso de vía de hecho, el interesado podrá formular requerimiento a la Administración actuante, intimando su cesación. Si dicha intimación no hubiere sido formulada o no fuere atendida dentro de los diez días siguientes a la presentación del requerimiento, podrá deducir directamente recurso contencioso-administrativo.\"</span> Fundamento: TÍTULO III. Capítulo I. Actividad administrativa impugnable. Artículo 30 LJCA: “En caso de vía de hecho, el interesado podrá formular requerimiento a la Administración actuante, intimando su cesación. Dicho requerimiento no será necesario para deducir directamente recurso contencioso-administrativo. Si la Administración no hubiere cesado en la vía de hecho dentro de los diez días siguientes al de la presentación del requerimiento, o no hubiere sido formulado éste, el interesado podrá deducir directamente recurso contencioso-administrativo.”"},{"i":"13-19","p":"Recurso contencioso-administrativo se dirigiera contra una actuación de hecho, el plazo para interponer el recurso será de","o":["Dos meses.","Diez días.","Cinco meses.","Seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 46 · Del Objeto del Recurso Contencioso-Administrativo</span> dispone: <span class=\"ref-concepto\">\"Si el recurso contencioso-administrativo se dirigiera contra una actuación en vía de hecho, el plazo para interponer el recurso será de diez días a contar desde el día siguiente a la terminación del plazo establecido en el artículo 30. Si no hubiere requerimiento, el plazo será de veinte días desde el día en que se inició la actuación administrativa en vía de hecho.\"</span> Fundamento: De conformidad con el artículo 46.2 de la Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa (LJCA), si el recurso se dirige contra una actuación material constitutiva de vía de hecho, el plazo para interponerlo es de diez días a contar desde el día siguiente a la terminación de la actuación."},{"i":"13-46","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Actividad administrativa impugnable. En caso de vía de hecho, el interesado podrá formular requerimiento a la Administración actuante, intimando su cesación. Si dicha intimación no hubiere sido formulada o no fuere atendida dentro de los ____ siguientes a la presentación del requerimiento, podrá deducir directamente recurso contencioso-administrativo. Señale la opción correcta.","o":["Veinte días.","Diez días.","Quince días.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 30 · Del Objeto del Recurso Contencioso-Administrativo</span> dispone: <span class=\"ref-concepto\">\"En caso de vía de hecho, el interesado podrá formular requerimiento a la Administración actuante, intimando su cesación. Si dicha intimación no hubiere sido formulada o no fuere atendida dentro de los diez días siguientes a la presentación del requerimiento, podrá deducir directamente recurso contencioso-administrativo.\"</span> Fundamento: El Art. 30 de la LJCA establece que si la intimación de cese de la vía de hecho no es atendida dentro de los diez días siguientes, el interesado podrá interponer recurso contencioso-administrativo."},{"i":"13-55","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recursos y reclamación del expediente. El plazo para interponer el recurso contencioso-administrativo será de ___________ contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.","o":["Tres meses.","Dos meses.","Seis meses.","Nueve meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos meses</mark></span><span class=\"ref-norma\">Art. 46.1 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El plazo general para la interposición del recurso contencioso-administrativo contra disposiciones generales o actos expresos que pongan fin a la vía administrativa es de dos meses, según el artículo 46.1 de la LJCA."},{"i":"13-59","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Objeto del recurso contencioso-administrativo. Actividad administrativa impugnable. Señale la incorrecta.","o":["El acto de impugnación directo de una disposición general o la desestimación del recurso que frente a ella se hubiera interpuesto impide la impugnación de los actos que resulten de su aplicación.","Además de la impugnación directa de las disposiciones de carácter general, también es admisible la de los actos que se produzcan en aplicación de las mismas, fundada en que tales disposiciones no son conformes a Derecho.","El recurso contencioso-administrativo es admisible en relación con las disposiciones de carácter general y con los actos expresos y presuntos de la Administración pública que pongan fin a la vía administrativa, ya sean definitivos o de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos o intereses legítimos.","Es admisible el recurso contra la inactividad de la Administración y contra sus actuaciones materiales que constituyan vía de hecho, en los términos establecidos en esta Ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El acto de impugnación directo de una disposición general o la desestimación del recurso que frente a ella ...</mark></span><span class=\"ref-norma\">Art. 26.2 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El artículo 26.2 de la LJCA establece que la interposición de recurso contra una disposición general no impedirá la interposición de recurso contra los actos de aplicación. Solo la desestimación del recurso directo contra la disposición general impedirá la impugnación posterior del acto de aplicación por la misma ilegalidad (Art. 27.2). Dado que la primera parte de la opción (a) es incorrecta (el simple acto de impugnación no impide), esta es la afirmación jurídicamente incorrecta que se pide señalar."},{"i":"13-73","p":"Contencioso-administrativa. Interposición del recurso y reclamación del expediente. El plazo para interponer recurso de lesividad será de ________, a contar desde el día siguiente a la fecha de la declaración de lesividad.","o":["Un mes.","Dos meses.","Tres meses.","Seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos meses</mark></span><span class=\"ref-norma\">Art. 46 · Del Objeto del Recurso Contencioso-Administrativo</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso contencioso-administrativo se contará desde el día siguiente a aquel en que se notifique la resolución expresa del recurso potestativo de reposición o en que éste deba entenderse presuntamente desestimado. El plazo para interponer recurso de lesividad será de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad.\"</span> Fundamento: *Explicación:* Conforme al artículo 46.5 de la LJCA, en los casos de declaración de lesividad de actos favorables, el plazo para interponer el recurso es de dos meses."},{"i":"13-80","p":"Contencioso-administrativa. Interposición del recurso y reclamación del expediente. El plazo para interponer el recurso contencioso-administrativo será de ________ contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.","o":["Tres meses.","Dos meses.","Seis meses.","Nueve meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos meses</mark></span><span class=\"ref-norma\">Art. 46.1 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: *Explicación:* El artículo 46.1 de la LJCA establece que el plazo general para la interposición del recurso contra actos expresos y disposiciones generales es de dos meses."},{"i":"13-89","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Procedimientos especiales. Cuando la lesión del derecho fundamental tuviera su origen en la inactividad administrativa, ¿desde qué momento se computará el plazo para interponer el recurso de amparo?","o":["Transcurridos diez días desde que finalice el procedimiento administrativo.","Transcurridos quince días desde que tenga entrada en el registro general del órgano competente el recurso administrativo.","Transcurridos veinte días desde la reclamación.","Transcurridos cinco días desde la resolución."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Transcurridos veinte días desde la reclamación</mark></span><span class=\"ref-norma\">Art. 115.3 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El artículo 115.3 de la LJCA establece que el plazo de diez días para la interposición del recurso se iniciará transcurridos veinte días desde la reclamación de la inactividad administrativa."},{"i":"13-105","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición y reclamación del expediente. El plazo para interponer recurso de lesividad será de _____ a contar desde el día siguiente a la fecha de la declaración de lesividad. Señale la opción correcta.","o":["Diez días.","Veinte días.","Un mes.","Dos meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Dos meses</mark></span><span class=\"ref-norma\">Art. 58.2 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El artículo 58.2 de la LJCA establece el plazo de dos meses para la interposición del recurso de lesividad, a contar desde el día siguiente a la declaración de lesividad."},{"i":"13-143","p":"Jurisdicción Contencioso-Administrativa. Objeto del recurso contencioso- administrativo. En caso de vía de hecho, el interesado podrá formular requerimiento a la Administración actuante, intimando su cesación. ¿En qué plazo, si dicha intimación no fuere atendida desde la presentación del requerimiento, podrá deducir directamente recurso contencioso-administrativo?","o":["Dos meses.","Tres meses.","Cuatro meses.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas</mark></span><span class=\"ref-norma\">Art. 30 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El plazo para interponer el recurso contencioso- administrativo en caso de vía de hecho es de diez días (a contar desde el día siguiente a la terminación del plazo de diez días para que la Administración cese en su actuación o desde el día de la desestimación del requerimiento) (Art. 30 LJCA). Las opciones a), b) y c) son incorrectas."},{"i":"13-147","p":"Jurisdicción Contencioso-Administrativa. El plazo para interponer recurso de lesividad será de ___________ a contar desde el día siguiente a la fecha de la declaración de lesividad.","o":["Dos meses.","Diez días.","Veinte días.","Seis meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos meses</mark></span><span class=\"ref-norma\">Art. 46 · Del Objeto del Recurso Contencioso-Administrativo</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso contencioso-administrativo se contará desde el día siguiente a aquel en que se notifique la resolución expresa del recurso potestativo de reposición o en que éste deba entenderse presuntamente desestimado. El plazo para interponer recurso de lesividad será de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad.\"</span> Fundamento: El plazo para interponer el recurso contencioso- administrativo de lesividad por la Administración es de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad (Art. 46.5 LJCA)."},{"i":"13-159","p":"Contencioso-Administrativa. Si el recurso contencioso-administrativo se dirigiera contra una actuación en vía de hecho y no hubiera requerimiento, el plazo para interponer el recurso será de","o":["Dos meses desde el día en que se inició la actuación administrativa en vía de hecho.","Diez días desde el día en que se inició la actuación administrativa en vía de hecho.","Veinte días desde el día en que se inició la actuación administrativa en vía de hecho.","Seis meses desde el día en que se inició la actuación administrativa en vía de hecho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días desde el día en que se inició la actuación administrativa en vía de hecho</mark></span>Los diez días se cuentan desde que termina el plazo del art. 30 cuando SÍ hubo requerimiento. Según el <span class=\"ref-norma\">art. 46.3 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Si no hubiere requerimiento, el plazo será de veinte días desde el día en que se inició la actuación administrativa en vía de hecho.\"</span> (verificado con el texto del temario)."},{"i":"13-162","p":"Contencioso-Administrativa. El plazo para interponer el recurso contencioso- administrativo, si el acto no fuera expreso, será de","o":["Dos meses.","Diez días.","Veinte días.","Seis meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Seis meses</mark></span><span class=\"ref-norma\">Art. 46.1 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El plazo para interponer el recurso contencioso- administrativo contra la inactividad de la Administración (acto presunto denegatorio por silencio) es de seis meses, según el artículo 46.1 de la LJCA."},{"i":"13-179","p":"Administrativo (ausencia de acto expreso) en el procedimiento, ¿cuál es el plazo para interponer el recurso contencioso-administrativo?","o":["Seis meses, contados para el solicitante y otros posibles interesados a partir del día siguiente a aquél en que, de acuerdo con su normativa específica, se produzca el acto presunto.","De dos meses y un día para el solicitante y otros posibles interesados, ambos se contarán a partir del día siguiente a aquél en que, de acuerdo con su normativa específica, se produzca el acto presunto.","Seis meses para el solicitante y de dos meses para otros posibles interesados, ambos se contarán a partir del día siguiente a aquél en que, de acuerdo con su normativa específica, se produzca el acto presunto.","De dos meses para el solicitante y seis meses para otros posibles interesados, ambos se contarán a partir del día siguiente a aquél en que, de acuerdo con su normativa específica, se produzca el acto presunto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Seis meses, contados para el solicitante y otros posibles interesados a partir del día siguiente a aquél en que, de acuerdo con su normativa específica, se produzca el acto presunto</mark></span>Según el <span class=\"ref-norma\">art. 46.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Si no lo fuera, el plazo será de seis meses y se contará, para el solicitante y otros posibles interesados, a partir del día siguiente a aquél en que, de acuerdo con su normativa específica, se produzca el acto presunto.\"</span> (verificado con el texto del temario)."},{"i":"13-213","p":"Jurisdicción Contencioso-administrativa. Interposición del recurso y reclamación del expediente. En los litigios entre Administraciones, el plazo para interponer recurso contencioso-administrativo será de","o":["Veinte días, salvo que por Ley se establezca otra cosa.","Un mes, salvo que por Ley se establezca otra cosa.","Dos meses, salvo que por Ley se establezca otra cosa.","Seis meses, salvo que por Ley se establezca otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos meses, salvo que por Ley se establezca otra cosa</mark></span><span class=\"ref-norma\">Art. 46.5 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El artículo 46.5 de la LJCA, relativo a los litigios entre Administraciones, establece que el plazo para la interposición del recurso será de dos meses, salvo que por Ley se establezca otra cosa."},{"i":"13-245","p":": Interposición del recurso y reclamación del expediente. El plazo para interponer el recurso contencioso-administrativo no será, si no fuera expreso, de","o":["Dos meses.","Tres meses.","Seis meses.","Un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis meses</mark></span><span class=\"ref-norma\">Art. 46.1 · Del Objeto del Recurso Contencioso-Administrativo</span>. Fundamento: El plazo para interponer recurso contencioso- administrativo contra actos presuntos (no expresos) es de seis meses, contados a partir del día siguiente a aquel en que, de acuerdo con su normativa específica, se produzca el acto presunto. (Art. 46.1 LJCA, en relación con el Art. 29.1 LJCA)."},{"i":"13-252","p":": Interposición del recurso y reclamación del expediente. El plazo para interponer recurso de lesividad será de _____________ a contar desde el día siguiente a la fecha de la declaración de lesividad.","o":["Un mes.","Dos meses.","Tres meses.","Seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos meses</mark></span><span class=\"ref-norma\">Art. 46 · Del Objeto del Recurso Contencioso-Administrativo</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer recurso de lesividad será de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad.\"</span> Fundamento: El plazo para interponer el recurso de lesividad es de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad. (Art. 46.5 LJCA)."},{"i":"13-271","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. Si el recurso contencioso-administrativo se dirigiera contra una actuación de hecho, el plazo para interponer el recurso será de:","o":["Dos meses.","Diez días.","Cinco meses.","Seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días.</mark></span><span class=\"ref-norma\">Art. 46.3 · Del Objeto del Recurso Contencioso-Administrativo</span>. De conformidad con el artículo 46.3 LJCA."},{"i":"13-287","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recursos y reclamación del expediente. El plazo para interponer el recurso contencioso-administrativo será de ___________ contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.","o":["Tres meses.","Dos meses.","Seis meses.","Nueve meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos meses.</mark></span><span class=\"ref-norma\">Art. 46.1 · Del Objeto del Recurso Contencioso-Administrativo</span>. De conformidad con el artículo 46.1 LJCA."},{"i":"13-290","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Objeto del recurso contencioso-administrativo. Actividad administrativa impugnable. Señale la incorrecta.","o":["El acto de impugnación directo de una disposición general o la desestimación del recurso que frente a ella se hubiera interpuesto impide la impugnación de los actos que resulten de su aplicación.","Además de la impugnación directa de las disposiciones de carácter general, también es admisible la de los actos que se produzcan en aplicación de las mismas, fundada en que tales disposiciones no son conformes a Derecho.","El recurso contencioso-administrativo es admisible en relación con las disposiciones de carácter general y con los actos expresos y presuntos de la Administración pública que pongan fin a la vía administrativa, ya sean definitivos o de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos o intereses legítimos.","Es admisible el recurso contra la inactividad de la Administración y contra sus actuaciones materiales que constituyan vía de hecho, en los términos establecidos en esta Ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El acto de impugnación directo de una disposición general o la desestimación del recurso que frente a ella se hubiera interpuesto impide la impugnación de los actos que resulten de su aplicación.</mark></span><span class=\"ref-norma\">Art. 26.2 · Del Objeto del Recurso Contencioso-Administrativo</span>. De conformidad con el artículo 26.2 LJCA, según el cual la falta de impugnación directa o la desestimación del recurso NO impiden la impugnación de los actos de aplicación."},{"i":"13-318","p":"Ley 29/1998, Reguladora de la Jurisdicción Contencioso-Administrativa. Si el recurso contencioso-administrativo se dirigiera contra una actuación en vía de hecho y no hubiera requerimiento, el plazo para interponer el recurso será de:","o":["Dos meses desde el día en que se inició la actuación administrativa en vía de hecho.","Diez días desde el día en que se inició la actuación administrativa en vía de hecho.","Veinte días desde el día en que se inició la actuación administrativa en vía de hecho.","Seis meses desde el día en que se inició la actuación administrativa en vía de hecho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días desde el día en que se inició la actuación administrativa en vía de hecho.</mark></span><span class=\"ref-norma\">Art. 46.3 · Del Objeto del Recurso Contencioso-Administrativo</span>. De conformidad con el artículo 46.3 LJCA."},{"i":"13-341","p":"Interposición del recurso y reclamación del expediente. El plazo para interponer el recurso contencioso-administrativo no será, si no fuera expreso, de:","o":["Dos meses.","Tres meses.","Seis meses.","Un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis meses.</mark></span><span class=\"ref-norma\">Art. 46.1 · Del Objeto del Recurso Contencioso-Administrativo</span>. De conformidad con el artículo 46.1 LJCA."},{"i":"13-348","p":"Interposición del recurso y reclamación del expediente. El plazo para interponer recurso de lesividad será de _____________ a contar desde el día siguiente a la fecha de la declaración de lesividad.","o":["Un mes.","Dos meses.","Tres meses.","Seis meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos meses.</mark></span><span class=\"ref-norma\">Art. 46 · Del Objeto del Recurso Contencioso-Administrativo</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer recurso de lesividad será de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad.\"</span> De conformidad con el artículo 46.5 LJCA."}]},{"a":"Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia","q":[{"i":"13-10","p":"Ley 29/98, de 13 de julio, reguladora de la jurisdicción contencioso administrativa. Del orden jurisdiccional contencioso-administrativo. Órganos y competencia. ¿Qué órgano conocerá de todas las resoluciones que se dicten en materia de extranjería por la Administración periférica del Estado o por los órganos competentes de las Comunidades Autónomas?","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Juzgados de lo Contencioso-Administrativo.</mark></span><span class=\"ref-norma\">Art. 8 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: TÍTULO I. Capítulo II. Órganos y competencias. Artículo 8 LJCA: los Juzgados de lo Contencioso-Administrativo conocen, en primera o única instancia, de las resoluciones dictadas en materia de extranjería por la Administración periférica del Estado o por los órganos competentes de las Comunidades Autónomas, en los términos previstos en dicho precepto."},{"i":"13-14","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Órganos y competencias. ¿Quién conocerá, en primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político?","o":["Los Juzgados de lo Contencioso-Administrativo.","Los Juzgados Centrales de lo Contencioso-Administrativo.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-Administrativo del Tribunal Supremo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Juzgados Centrales de lo Contencioso-Administrativo.</mark></span><span class=\"ref-norma\">Art. 9 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: TÍTULO I. Capítulo II. Órganos y competencias. Artículo 9 LJCA atribuye a los Juzgados Centrales de lo Contencioso- Administrativo el conocimiento, en primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político."},{"i":"13-15","p":"Ley 29/98, Reguladora de la Jurisdicción Contencioso-Administrativa. Ámbito. Se entenderá a estos efectos por Administraciones públicas: Señale la incorrecta.","o":["La Administración General del Estado.","Las Administraciones de las Comunidades Autónomas.","Las Entidades que integran la Administración Electoral.","Las Entidades de Derecho Público que sean dependientes o estén vinculadas al Estado, las Comunidades Autónomas o las Entidades Locales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Administración Electoral no figura entre las Administraciones públicas del art. 1.2; su actuación se menciona aparte, en el art. 1.3.c).</mark></span><span class=\"ref-norma\">Art. 1.2 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: TÍTULO I. Capítulo I. Ámbito. Artículo 1.2 LJCA enumera como Administraciones públicas: la Administración General del Estado; las Administraciones de las Comunidades Autónomas; las Entidades que integran la Administración local; y las Entidades de Derecho público dependientes o vinculadas al Estado, las Comunidades Autónomas o las Entidades locales. La actuación de la Administración electoral se regula de forma separada en el artículo 1.3.c)."},{"i":"13-16","p":"Ley 29/98, de 13 de julio, Reguladora de la Jurisdicción Contencioso- Administrativa. Órganos y competencia. El Orden Jurisdiccional Contencioso- Administrativo se halla integrado por los siguientes órganos:","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo del Tribunal Supremo.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 6 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: TÍTULO I. Capítulo II. Órganos y competencias. Artículo 6 LJCA: el orden jurisdiccional contencioso-administrativo se halla integrado por los Juzgados de lo Contencioso-administrativo, los Juzgados Centrales de lo Contencioso-administrativo, las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia, la Sala de lo Contencioso- administrativo de la Audiencia Nacional y la Sala de lo Contencioso-administrativo del Tribunal Supremo."},{"i":"13-30","p":"Reguladora de la Jurisdicción Contencioso-Administrativa. En los litigios entre Administraciones públicas","o":["No cabrá interponer recurso en vía administrativa.","Cabrá interponer recurso en vía administrativa.","Cabrá interponer recurso en vía administrativa, por el procedimiento abreviado.","Cabrá interponer recurso en vía administrativa, por el procedimiento ordinario."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No cabrá interponer recurso en vía administrativa</mark></span><span class=\"ref-norma\">Art. 44.1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: De acuerdo con el artículo 44.1 de la LJCA, en los litigios entre Administraciones públicas no cabrá interponer recurso en vía administrativa. No obstante, se establece un trámite de requerimiento previo antes de la interposición del recurso contencioso-administrativo."},{"i":"13-32","p":"De este orden jurisdiccional apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma, previa audiencia de las partes y del Ministerio Fiscal por plazo común de","o":["Diez días.","Cinco días.","Ocho días.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 2.2 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El artículo 2.2 de la LJCA establece que los órganos jurisdiccionales apreciarán de oficio la falta de jurisdicción, previa audiencia de las partes y del Ministerio Fiscal por plazo común de diez días."},{"i":"13-34","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con los actos y disposiciones de: Señale la respuesta correcta.","o":["El Consejo General del Poder Judicial.","El Consejo de Ministros.","Los Juzgados y Tribunales.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial</mark></span><span class=\"ref-norma\">Art. 2.3.b) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El Art. 2.3.b) de la LJCA establece que los Juzgados y Tribunales conocerán de los actos y disposiciones del Consejo General del Poder Judicial y la actividad administrativa de los órganos de gobierno de los Juzgados y Tribunales. Los actos del Consejo de Ministros son competencia de la Sala de lo Contencioso-Administrativo del Tribunal Supremo (Art. 12.1.a LJCA)."},{"i":"13-35","p":"Ley reguladora de la jurisdicción contencioso-administrativa. El orden jurisdiccional contencioso-administrativo se halla integrado por los siguientes órganos: Señale la respuesta incorrecta.","o":["Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Salas de lo Contencioso-administrativo de las Audiencias Provinciales.","Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Juzgados Centrales de lo Contencioso-administrativo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Salas de lo Contencioso-administrativo de las Audiencias Provinciales</mark></span><span class=\"ref-norma\">Art. 6 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El Art. 6 de la LJCA enumera los órganos de este orden jurisdiccional, entre los que no se encuentran las Salas de lo Contencioso-administrativo de las Audiencias Provinciales."},{"i":"13-37","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia de los recursos que se deduzcan de los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto las sanciones administrativas que consistan en cese de actividades o privación de ejercicio de derechos que no excedan de seis meses?","o":["La Sala de lo Contencioso-administrativo del Tribunal Supremo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados de lo Contencioso-administrativo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo</mark></span><span class=\"ref-norma\">Art. 8.4 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El Art. 8.4 de la LJCA atribuye a los Juzgados de lo Contencioso-administrativo el conocimiento de los recursos contra actos de la Administración Autonómica (salvo Consejo de Gobierno) en materia de sanciones que consistan en multa no superior a 30.000 € y de las que consistan en privación de derechos que no excedan de seis meses, así como el cese de actividades."},{"i":"13-38","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia, de la autorización o ratificación judicial de las medidas adoptadas con arreglo a la legislación sanitaria que las autoridades sanitarias consideren urgentes y necesarias para la salud pública e impliquen limitación o restricción de derechos fundamentales cuando dichas medidas estén plasmadas en actos administrativos singulares que afecten únicamente a uno o varios particulares concretos e identificados de manera individualizada?","o":["Los Juzgados Centrales de lo Contencioso-administrativo.","Los Juzgados de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo</mark></span><span class=\"ref-norma\">Art. 8.6 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El Art. 8.6 de la LJCA establece la competencia de los Juzgados de lo Contencioso-administrativo para conocer de la autorización o ratificación judicial de las medidas sanitarias que impliquen limitación de derechos fundamentales y afecten a particulares individualizados."},{"i":"13-41","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia, de los recursos en relación con los convenios entre Administraciones públicas no atribuidos a los Tribunales Superiores de Justicia?","o":["La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Los Juzgados Centrales de lo Contencioso-administrativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Art. 11.1.e) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El Art. 11.1.e) de la LJCA atribuye a la Sala de lo Contencioso-administrativo de la Audiencia Nacional el conocimiento en única instancia de los recursos relativos a convenios entre Administraciones públicas no atribuidos a los Tribunales Superiores de Justicia."},{"i":"13-42","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia, de los recursos contra los actos del Banco de España, de la Comisión Nacional del Mercado de Valores y del FROB adoptados conforme a lo previsto en la Ley 11/2015, de 18 de junio, de recuperación y resolución de entidades de crédito y empresas de servicios de inversión?","o":["La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Ninguna es correcta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ninguna es correcta</mark></span>Los conoce la Sala de la Audiencia Nacional, que no figura entre las opciones. Según el <span class=\"ref-norma\">art. 11.1.g) de la Ley 29/1998 (LJCA)</span>: <span class=\"ref-concepto\">\"De los recursos contra los actos del Banco de España, de la Comisión Nacional del Mercado de Valores y del FROB adoptados conforme a lo previsto en la Ley 11/2015\"</span> (verificado con el texto oficial)."},{"i":"13-53","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con los actos y disposiciones en materia de personal, administración y gestión patrimonial sujetos al derecho público adoptados por los órganos competentes de: Señale la respuesta incorrecta.","o":["El Senado.","El Tribunal Constitucional.","El Defensor del Pueblo.","El Consejo de Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo de Estado</mark></span><span class=\"ref-norma\">Art. 1.2.c) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: La Ley de la Jurisdicción Contencioso- Administrativa (Art. 1.2.c) excluye de la revisión de la JCA los actos en materia de personal, administración y gestión patrimonial del Congreso de los Diputados, del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo. El Consejo de Estado no figura en esa lista, por lo que sus actos en dichas materias *sí* son susceptibles de recurso contencioso-administrativo. Por lo tanto, es el órgano que no encaja en la lista de exclusiones."},{"i":"13-111","p":"Contencioso-Administrativa. Órganos y competencia. El orden jurisdiccional contencioso-administrativo se halla integrado por los siguientes órganos: Señale la incorrecta.","o":["Juzgados de lo Contencioso-Administrativo.","Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia.","Salas de lo Contencioso-Administrativo de la Audiencia Nacional.","Juzgados de lo Contencioso-Administrativo del Tribunal Supremo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Juzgados de lo Contencioso-Administrativo del Tribunal Supremo</mark></span><span class=\"ref-norma\">Art. 6 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: Los órganos jurisdiccionales del orden contencioso-administrativo son (Art. 6 LJCA): Juzgados (ordinarios y Centrales), las Salas de los Tribunales Superiores de Justicia, la Sala de la Audiencia Nacional y la Sala del Tribunal Supremo. No existen los \"Juzgados de lo Contencioso-Administrativo del Tribunal Supremo\"."},{"i":"13-115","p":"Contencioso-administrativa. Del orden jurisdiccional contencioso- administrativo. Órganos y competencia. Conocerán los Juzgados de lo Contencioso- Administrativo: (marque la opción incorrect","o":[". a) De las autorizaciones para la entrada o la remontada en domicilios y restantes lugares cuyo acceso requiera el consentimiento de su titular, siempre que ello proceda para la ejecución forzosa de actos de la Administración Pública.","De las autorizaciones para la entrada e inspección de domicilios, locales, terrenos y medios de transporte que haya sido acordada por la Comisión Nacional de la Competencia.","De las sanciones administrativas que consistan en multas superiores a 60.000 euros y en cese de actividades o privación de ejercicio de derechos que no excedan de seis meses.","De los recursos que se deduzcan frente a los actos de las entidades locales de base o las entidades y corporaciones dependientes o vinculadas a las mismas, incluidas las impugnaciones de cualquier clase de instrumentos de planeamiento urbanístico."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De las sanciones administrativas que consistan en multas superiores a 60.000 euros y en cese de actividades o privación de ejercicio de derechos que no excedan de seis meses</mark></span>Los Juzgados conocen de multas NO SUPERIORES a 60.000 euros; decir «superiores» es lo incorrecto. Según el <span class=\"ref-norma\">art. 8.2.b) de la Ley 29/1998 (LJCA)</span>: <span class=\"ref-concepto\">\"sanciones administrativas que consistan en multas no superiores a 60.000 euros y en ceses de actividades o privación de ejercicio de derechos que no excedan de seis meses\"</span> (verificado con el texto oficial)."},{"i":"13-117","p":"De la Jurisdicción Contencioso-Administrativa, los Juzgados y Tribunales del orden contencioso-administrativo conocerán también de las pretensiones que se deduzcan en relación con","o":["Los actos y disposiciones en materia de personal, administración y gestión patrimonial sujetos al derecho público adoptados por los órganos competentes del Congreso de los Diputados, del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo, así como de las Asambleas Legislativas de las Comunidades Autónomas y de las Instituciones autonómicas análogas al Tribunal de Cuentas y Defensor del Pueblo.","Los actos y disposiciones del Consejo General del Poder Judicial y la actividad administrativa de los órganos de gobierno de los Juzgados y Tribunales, en los términos de la Ley Orgánica del Poder Judicial.","La actuación de la Administración electoral en los términos previstos en la Ley Orgánica del Régimen Electoral General.","Todos son correctos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctos</mark></span><span class=\"ref-norma\">Art. 2 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El Art. 2.e, 2.f y 2.g de la LJCA atribuye expresamente a la Jurisdicción Contencioso-Administrativa el conocimiento de la actividad administrativa de los órganos constitucionales (a), la actividad administrativa del Consejo General del Poder Judicial (b) y la Administración electoral (c). Por lo tanto, todas son correctas."},{"i":"13-118","p":"Contencioso-administrativa. Del orden jurisdiccional contencioso- administrativo. Órganos y competencia. ¿Qué órgano conocerá en primera o única instancia de los recursos contencioso-administrativos que se interpongan contra las disposiciones generales y contra los actos emanados de los organismos públicos con personalidad jurídica propia y entidades pertenecientes al sector público estatal con competencia en todo el territorio nacional sin perjuicio de lo dispuesto en el párrafo l) del apartado 1 del artículo 10?","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Juzgados Centrales de lo Contencioso-Administrativo</mark></span><span class=\"ref-norma\">Art. 9.1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El Art. 9.1.c de la LJCA atribuye expresamente a los Juzgados Centrales de lo Contencioso-Administrativo el conocimiento en única o primera instancia de los recursos contra los actos y disposiciones de los organismos públicos estatales con competencia en todo el territorio nacional."},{"i":"13-123","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. No corresponden al orden jurisdiccional contencioso-administrativo: Señale la INCORRECTA.","o":["Los recursos directos o indirectos que se interpongan contra las Normas Forales Fiscales de las Juntas Generales de los Territorios Históricos de Álava, Guipúzcoa y Vizcaya.","El recurso contencioso-disciplinario militar.","Los actos y disposiciones del Consejo General del Poder Judicial y la actividad administrativa de los órganos de gobierno de los Juzgados y Tribunales.","Los conflictos de jurisdicción entre los Juzgados y Tribunales y la Administración pública."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los actos y disposiciones del Consejo General del Poder Judicial y la actividad administrativa de los órganos de gobierno de los Juzgados y Tribunales</mark></span>Estos actos SÍ corresponden al orden contencioso-administrativo, por eso es la opción incorrecta en una pregunta sobre lo que NO le corresponde. Según el <span class=\"ref-norma\">art. 1.3.b) de la Ley 29/1998 (LJCA)</span>: <span class=\"ref-concepto\">\"Los actos y disposiciones del Consejo General del Poder Judicial y la actividad administrativa de los órganos de gobierno de los Juzgados y Tribunales\"</span> (verificado con el texto oficial)."},{"i":"13-141","p":"Jurisdicción Contencioso-Administrativa. Sala de lo Contencioso-Administrativo del Tribunal Supremo. Conocerá de los actos y disposiciones en materia de personal, administración y gestión patrimonial adoptados por los órganos competentes de: señale la INCORRECTA.","o":["El Defensor del Pueblo.","El Consejo General del Poder Judicial.","El Tribunal de Cuentas.","El Tribunal Constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial</mark></span><span class=\"ref-norma\">Art. 1.3.a) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: Órganos y competencias. El artículo 1.3.a) de la LJCA (en relación con el art. 12.1.a) atribuye a la Sala de lo Contencioso-Administrativo del Tribunal Supremo el conocimiento, en materia de personal, administración y gestión patrimonial, de los actos y disposiciones de los órganos competentes del Congreso de los Diputados, del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo. El Consejo General del Poder Judicial no figura en ese listado: sus actos y la actividad administrativa de los órganos de gobierno de Juzgados y Tribunales se rigen por un apartado distinto, el artículo 1.3.b) de la LJCA."},{"i":"13-142","p":"Jurisdicción Contencioso-Administrativa. El orden jurisdiccional contencioso- administrativo se halla integrado por los siguientes órganos: señale la INCORRECTA.","o":["Sala de lo Contencioso-administrativo del Tribunal Constitucional.","Sala de lo Contencioso-administrativo del Tribunal Supremo.","Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Salas de lo Contencioso-administrativo de los Tribunales Supremos de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sala de lo Contencioso-administrativo del Tribunal Constitucional</mark></span><span class=\"ref-norma\">Art. 1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: Los órganos de la Jurisdicción Contencioso-Administrativa son: Juzgados de lo Contencioso-Administrativo, Juzgados Centrales de lo Contencioso-Administrativo, Salas de la Audiencia Nacional, Salas de los Tribunales Superiores de Justicia y la Sala del Tribunal Supremo (Art. 1 y 6 LJCA). El Tribunal Constitucional no forma parte de este orden jurisdiccional."},{"i":"13-194","p":"Del Orden Contencioso-Administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas","o":["Sujeta a Derecho Administrativo.","En cualquier caso.","Solo cuando lo establezca la Constitución.","Siempre que ésta se encuentre sujeta a Derecho Contencioso-Administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sujeta a Derecho Administrativo</mark></span><span class=\"ref-norma\">Art. 1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El artículo 1 de la LJCA establece que los Juzgados y Tribunales del orden Contencioso-Administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta a Derecho Administrativo."},{"i":"13-202","p":"Jurisdicción Contencioso-administrativa. Órganos y competencia. ¿Qué órgano conocerá en única instancia de los recursos en relación con los convenios entre Administraciones públicas no atribuidos a los Tribunales Superiores de Justicia?","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Sala de lo Contencioso-Administrativo del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sala de lo Contencioso-Administrativo de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Art. 11.1.j) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: El artículo 11.1.j) de la LJCA atribuye a las Salas de lo Contencioso-Administrativo de la Audiencia Nacional el conocimiento en única instancia de \"Los recursos que se deduzcan en relación con los convenios entre Administraciones públicas no atribuidos a los Tribunales Superiores de Justicia\"."},{"i":"13-216","p":"Contencioso-administrativa. Órganos y competencias. ¿Quién conocerá de las resoluciones que se dicten en materia de extranjería por la Administración periférica del Estado?","o":["Juzgados de los Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Salas del Tribunal Supremo.","Salas de la Audiencia Nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Juzgados de los Contencioso-Administrativo</mark></span>Son los Juzgados de lo Contencioso-administrativo, no los Centrales. Según el <span class=\"ref-norma\">art. 8.4 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Conocerán, igualmente, de todas las resoluciones que se dicten en materia de extranjería por la Administración periférica del Estado o por los órganos competentes de las Comunidades Autónomas.\"</span> (verificado con el texto del temario)."},{"i":"13-218","p":"Jurisdicción Contencioso-administrativo. Ámbito. Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de","o":["Las Administraciones públicas sujetas al Derecho Administrativo.","Las disposiciones generales de rango inferior a la Ley.","Los Decretos legislativos que exceden los límites de la delegación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Fundamento: El ámbito de la jurisdicción contencioso- administrativa abarca las actuaciones de las Administraciones públicas sujetas al Derecho Administrativo, las disposiciones generales de rango inferior a la Ley, y el control de los decretos legislativos que exceden los límites de la delegación, entre otros."},{"i":"13-231","p":"Jurisdicción Contencioso-administrativa. Órganos y Competencias. Quién conocerá de las autorizaciones para la entrada e inspección de domicilios, locales, terrenos y medios de transporte que haya sido acordada por la Comisión Nacional de la Competencia?","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Salas del Tribunal Supremo.","Salas de la Audiencia Nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Juzgados de lo Contencioso-Administrativo</mark></span>Según el <span class=\"ref-norma\">art. 8.6 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Además, los Juzgados de lo Contencioso-administrativo conocerán de las autorizaciones para la entrada e inspección de domicilios, locales, terrenos y medios de transporte que haya sido acordada por la Comisión Nacional de los Mercados y la Competencia...\"</span> (verificado con el texto del temario)."},{"i":"13-236","p":"Jurisdicción Contencioso-administrativa. Órganos y Competencias. La competencia de los Juzgados y Salas de lo Contencioso-administrativo no será prorrogable y deberá ser apreciada por los mismos, incluso de oficio, previa audiencia de","o":["Las partes, únicamente.","Las partes, el Ministerio Fiscal y a todo aquel que pudiera verse afectado por la resolución que se adopte.","El Ministerio Fiscal.","Las partes y el Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las partes y el Ministerio Fiscal</mark></span> Fundamento: La competencia en la jurisdicción contencioso-administrativa es improrrogable, y su apreciación de oficio debe hacerse previa audiencia de las partes y del Ministerio Fiscal."},{"i":"13-241","p":": ¿Qué órgano conocerá de las resoluciones dictadas por el Tribunal Administrativo Central de Recursos Contractuales?","o":["Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Art. 11.1.f) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. Fundamento: La Sala de lo Contencioso-administrativo de la Audiencia Nacional conocerá en única instancia de los recursos contencioso-administrativos contra las resoluciones del Tribunal Administrativo Central de Recursos Contractuales. (Art. 11.1.f) LJCA)."},{"i":"13-274","p":"Ley reguladora de la Jurisdicción Contencioso-administrativa. Los Juzgados y Tribunales del orden contencioso-administrativo conocerán:","o":["De las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho administrativo.","De las pretensiones que se deduzcan en relación con las disposiciones generales de rango inferior a la ley.","De las pretensiones que se deduzcan en relación con los Decretos legislativos cuando excedan los límites de la delegación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span> dispone: <span class=\"ref-concepto\">\"Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho Administrativo, con las disposiciones generales de rango inferior a la Ley y con los Decretos legislativos cuando excedan los límites de la delegación.\"</span> De conformidad con el artículo 1.1 LJCA."},{"i":"13-281","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. En los litigios entre Administraciones públicas:","o":["No cabrá interponer recurso en vía administrativa.","Cabrá interponer recurso en vía administrativa.","Cabrá interponer recurso en vía administrativa, por el procedimiento abreviado.","Cabrá interponer recurso en vía administrativa, por el procedimiento ordinario."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No cabrá interponer recurso en vía administrativa.</mark></span><span class=\"ref-norma\">Art. 44.1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. De conformidad con el artículo 44.1 LJCA."},{"i":"13-285","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con los actos y disposiciones en materia de personal, administración y gestión patrimonial sujetos al derecho público adoptados por los órganos competentes de: Señale la respuesta incorrecta.","o":["El Senado.","El Tribunal Constitucional.","El Defensor del Pueblo.","El Consejo de Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo de Estado.</mark></span><span class=\"ref-norma\">Art. 1.3.a) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. De conformidad con el artículo 1.3.a) LJCA, que no incluye al Consejo de Estado en esa lista."},{"i":"13-312","p":"Según establece la Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa, los Juzgados y Tribunales del orden contencioso-administrativo conocerán también de las pretensiones que se deduzcan en relación con:","o":["Los actos y disposiciones en materia de personal, administración y gestión patrimonial sujetos al derecho público adoptados por los órganos competentes del Congreso de los Diputados, del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo, así como de las Asambleas Legislativas de las Comunidades Autónomas y de las Instituciones autonómicas análogas al Tribunal de Cuentas y Defensor del Pueblo.","Los actos y disposiciones del Consejo General del Poder Judicial y la actividad administrativa de los órganos de gobierno de los Juzgados y Tribunales, en los términos de la Ley Orgánica del Poder Judicial.","La actuación de la Administración electoral en los términos previstos en la Ley Orgánica del Régimen Electoral General.","Todos son correctos"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctos.</mark></span><span class=\"ref-norma\">Art. 1.3.a) · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. De conformidad con el artículo 1.3.a), b) y c) LJCA."},{"i":"13-330","p":"Los Juzgados y Tribunales del Orden Contencioso-Administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas:","o":["Sujeta a Derecho Administrativo.","En cualquier caso.","Solo cuando lo establezca la Constitución.","Siempre que ésta se encuentre sujeta a Derecho Contencioso-Administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sujeta a Derecho Administrativo.</mark></span><span class=\"ref-norma\">Art. 1.1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span>. De conformidad con el artículo 1.1 LJCA."},{"i":"13-331","p":"Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con:","o":["La actuación de las Administraciones públicas.","Las disposiciones generales.","Los Decretos legislativos cuando excedan los límites de la delegación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 1 · Del Orden Jurisdiccional Contencioso-Administrativo: Órganos y Competencia</span> dispone: <span class=\"ref-concepto\">\"Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho Administrativo, con las disposiciones generales de rango inferior a la Ley y con los Decretos legislativos cuando excedan los límites de la delegación.\"</span> De conformidad con el artículo 1.1 LJCA."},{"i":"13-ia-6","p":"Ley 29/1998, art. 1.3.c). Además de la actuación de las Administraciones públicas, ¿de qué pretensiones conocen también los Juzgados y Tribunales del orden contencioso-administrativo?","o":["Del recurso contencioso-disciplinario militar.","De los conflictos de jurisdicción entre los Juzgados y Tribunales y la Administración pública.","De las cuestiones expresamente atribuidas al orden jurisdiccional social.","De la actuación de la Administración electoral, en los términos previstos en la Ley Orgánica del Régimen Electoral General."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De la actuación de la Administración electoral, en los términos previstos en la Ley Orgánica del Régimen Electoral General</mark></span>El <span class=\"ref-norma\">art. 1.3.c) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Conocerán también de las pretensiones que se deduzcan en relación con: [...] c) La actuación de la Administración electoral, en los términos previstos en la Ley Orgánica del Régimen Electoral General.\"</span>. Por qué fallan las otras: el recurso contencioso-disciplinario militar, los conflictos de jurisdicción y las cuestiones del orden social figuran entre las materias que NO corresponden a este orden (art. 3.a, 3.b y 3.c). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-42","p":"Ley 29/1998, art. 9.3. ¿Qué procedimiento conocen igualmente los Juzgados Centrales de lo Contencioso-Administrativo?","o":["El de autorización de entrada en domicilios para la ejecución forzosa de actos de la Administración pública.","El de protección del Derecho de Reunión, en única instancia.","El de ratificación de medidas sanitarias que afecten a derechos fundamentales.","El previsto en el art. 12 bis de la Ley Orgánica 6/2002, de Partidos Políticos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El previsto en el art. 12 bis de la Ley Orgánica 6/2002, de Partidos Políticos</mark></span>El <span class=\"ref-norma\">art. 9.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Igualmente conocerán los Juzgados Centrales de lo Contencioso Administrativo del procedimiento previsto en el artículo 12 bis de la Ley Orgánica 6/2002, de 27 de junio, de Partidos Políticos.\"</span>. Por qué fallan las otras: la prohibición de reuniones va a los TSJ (art. 10.1.h) y las entradas en domicilios y las medidas sanitarias, a los Juzgados de lo Contencioso-administrativo (art. 8.6). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-44","p":"Ley 29/1998, art. 11.5. ¿Quién conoce de la solicitud de autorización al amparo del art. 122 ter cuando sea formulada por la Agencia Española de Protección de Datos?","o":["La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional</mark></span>El <span class=\"ref-norma\">art. 11.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La Sala de lo Contencioso-administrativo de la Audiencia Nacional conocerá: [...] 5. Conocerá de la solicitud de autorización al amparo del artículo 122 ter, cuando sea formulada por la Agencia Española de Protección de Datos.\"</span>. Por qué fallan las otras: si la formula la autoridad autonómica corresponde al TSJ (art. 10.7) y si la formula el CGPJ, al Tribunal Supremo (art. 12.4). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-51","p":"Ley 29/1998, art. 8.1. Los Juzgados de lo Contencioso-administrativo conocen de los recursos frente a actos de las entidades locales. ¿Qué queda excluido de su competencia?","o":["Las cuestiones de personal de las entidades locales.","Las impugnaciones de cualquier clase de instrumentos de planeamiento urbanístico.","Las sanciones administrativas impuestas por los Ayuntamientos.","Las reclamaciones por responsabilidad patrimonial de las entidades locales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las impugnaciones de cualquier clase de instrumentos de planeamiento urbanístico</mark></span>El <span class=\"ref-norma\">art. 8.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"conocerán, en única o primera instancia según lo dispuesto en esta ley, de los recursos que se deduzcan frente a los actos de las entidades locales o de las entidades y corporaciones dependientes o vinculadas a las mismas, excluidas las impugnaciones de cualquier clase de instrumentos de planeamiento urbanístico\"</span>. Por qué fallan las otras: solo se excluye el planeamiento urbanístico; personal, sanciones y responsabilidad patrimonial local sí entran. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-53","p":"Ley 29/1998, art. 8.2.b). Los Juzgados conocen de las sanciones de la Administración autonómica que consistan en ceses de actividades o privación de ejercicio de derechos que no excedan de:","o":["Seis meses.","Tres meses.","Un año.","Dos meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Seis meses</mark></span>El <span class=\"ref-norma\">art. 8.2.b) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Las sanciones administrativas que consistan en multas no superiores a 60.000 euros y en ceses de actividades o privación de ejercicio de derechos que no excedan de seis meses\"</span>. Por qué fallan las otras: el límite temporal es de seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-61","p":"Ley 29/1998, art. 1.3.a). Respecto de los actos del Congreso, el Senado, el Tribunal Constitucional, el Tribunal de Cuentas y el Defensor del Pueblo, ¿de cuáles conocen los Juzgados y Tribunales del orden contencioso-administrativo?","o":["De cualquier acto o disposición, incluidos los de naturaleza legislativa.","Únicamente de los actos en materia de personal.","De los actos de administración y gestión patrimonial, pero no de los de personal.","De los actos y disposiciones en materia de personal, administración y gestión patrimonial sujetos al derecho público."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De los actos y disposiciones en materia de personal, administración y gestión patrimonial sujetos al derecho público</mark></span>El <span class=\"ref-norma\">art. 1.3.a) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Los actos y disposiciones en materia de personal, administración y gestión patrimonial sujetos al derecho público adoptados por los órganos competentes del Congreso de los Diputados, del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo\"</span>. Por qué fallan las otras: abarca las tres materias (personal, administración y gestión patrimonial) y solo si están sujetas al derecho público. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-63","p":"Ley 29/1998, art. 8.6. ¿Quién autoriza la entrada en domicilios y otros lugares constitucionalmente protegidos acordada por la Administración Tributaria en el marco de una actuación de aplicación de los tributos, aún con carácter previo a su inicio formal, cuando el titular se oponga o exista riesgo de oposición?","o":["Los Juzgados de lo Contencioso-administrativo.","Los Juzgados de Instrucción.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo Contencioso-administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo</mark></span>El <span class=\"ref-norma\">art. 8.6 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Los Juzgados de lo Contencioso-administrativo conocerán también de las autorizaciones para la entrada en domicilios y otros lugares constitucionalmente protegidos, que haya sido acordada por la Administración Tributaria en el marco de una actuación o procedimiento de aplicación de los tributos aún con carácter previo a su inicio formal cuando, requiriendo dicho acceso el consentimiento de su titular, este se oponga a ello o exista riesgo de tal oposición\"</span>. Por qué fallan las otras: la autorización la concede el Juzgado de lo Contencioso-administrativo, no el de Instrucción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-65","p":"Ley 29/1998, art. 11.1.h). ¿Quién conoce en única instancia de los recursos interpuestos por la Comisión Nacional de los Mercados y de la Competencia en defensa de la unidad de mercado?","o":["La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional</mark></span>El <span class=\"ref-norma\">art. 11.1.h) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"De los recursos interpuestos por la Comisión Nacional de los Mercados y de la Competencia en defensa de la unidad de mercado\"</span>. Por qué fallan las otras: estos recursos de la CNMC corresponden a la Sala de la Audiencia Nacional (art. 11.1.h). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-70","p":"Ley 29/1998, art. 9.1.d). ¿Quién conoce, en primera o única instancia, de los recursos contra las resoluciones dictadas por los Ministros y Secretarios de Estado en materia de responsabilidad patrimonial cuando lo reclamado no exceda de 30.050 euros?","o":["Los Juzgados Centrales de lo Contencioso-administrativo.","Los Juzgados de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Juzgados Centrales de lo Contencioso-administrativo</mark></span>El <span class=\"ref-norma\">art. 9.1.d) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En primera o única instancia, de los recursos contra las resoluciones dictadas por los Ministros y Secretarios de Estado en materia de responsabilidad patrimonial cuando lo reclamado no exceda de 30.050 euros\"</span>. Por qué fallan las otras: si lo reclamado supera esa cuantía, la competencia pasa a la Sala de la Audiencia Nacional (art. 11.1.a). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-71","p":"Ley 29/1998, art. 9.2. ¿Quién autoriza la ejecución de los actos adoptados por la Sección Segunda de la Comisión de Propiedad Intelectual para que se interrumpa la prestación de servicios de la sociedad de la información o se retiren contenidos que vulneren la propiedad intelectual?","o":["Los Juzgados Centrales de lo Contencioso-administrativo.","Los Juzgados de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Juzgados Centrales de lo Contencioso-administrativo</mark></span>El <span class=\"ref-norma\">art. 9.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Corresponderá a los Juzgados Centrales de lo Contencioso-Administrativo, la autorización a que se refiere el artículo 8.2 de la Ley 34/2002 así como autorizar la ejecución de los actos adoptados por la Sección Segunda de la Comisión de Propiedad Intelectual\"</span>. Por qué fallan las otras: la autorización es competencia de los Juzgados Centrales (art. 9.2), tramitada según el art. 122 bis. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-76","p":"Ley 29/1998, art. 11.1.a). ¿Quién conoce en única instancia de los recursos contra los actos de cualesquiera órganos centrales del Ministerio de Defensa referidos a ascensos, orden y antigüedad en el escalafón y destinos?","o":["Los Juzgados Centrales de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional</mark></span>El <span class=\"ref-norma\">art. 11.1.a) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Asimismo, conocerá de los recursos contra los actos de cualesquiera órganos centrales del Ministerio de Defensa referidos a ascensos, orden y antigüedad en el escalafón y destinos\"</span>. Por qué fallan las otras: es competencia de la Sala de la Audiencia Nacional (art. 11.1.a), no de los Juzgados Centrales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-86","p":"Ley 29/1998, art. 8.3. Los Juzgados conocen de los actos de la Administración periférica del Estado, salvo los de cuantía superior a 60.000 euros o cuando se dicten en ejercicio de sus competencias sobre determinadas materias. Señale la materia que NO figura entre esas excepciones:","o":["Dominio público.","Contratación administrativa.","Obras públicas del Estado.","Expropiación forzosa y propiedades especiales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Contratación administrativa</mark></span>El <span class=\"ref-norma\">art. 8.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Se exceptúan los actos de cuantía superior a 60.000 euros dictados por la Administración periférica del Estado y los organismos públicos estatales cuya competencia no se extienda a todo el territorio nacional, o cuando se dicten en ejercicio de sus competencias sobre dominio público, obras públicas del Estado, expropiación forzosa y propiedades especiales\"</span>. Por qué fallan las otras: las excepciones son dominio público, obras públicas del Estado, expropiación forzosa y propiedades especiales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-101","p":"Ley 29/1998, art. 2.e). La responsabilidad patrimonial de las Administraciones públicas no puede ser demandada por este motivo ante los órdenes jurisdiccionales:","o":["Civil o penal.","Penal o social.","Social o militar.","Civil o social."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Civil o social</mark></span>El <span class=\"ref-norma\">art. 2.e) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La responsabilidad patrimonial de las Administraciones públicas, cualquiera que sea la naturaleza de la actividad o el tipo de relación de que derive, no pudiendo ser demandadas aquellas por este motivo ante los órdenes jurisdiccionales civil o social, aun cuando en la producción del daño concurran con particulares o cuenten con un seguro de responsabilidad\"</span>. Por qué fallan las otras: la prohibición se refiere a los órdenes civil y social, también si concurren particulares o hay seguro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-102","p":"Ley 29/1998, art. 8.5. ¿Quién conoce de las impugnaciones contra actos de las Juntas Electorales de Zona?","o":["Los Juzgados de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo</mark></span>El <span class=\"ref-norma\">art. 8.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Corresponde conocer a los Juzgados de las impugnaciones contra actos de las Juntas Electorales de Zona y de las formuladas en materia de proclamación de candidaturas y candidatos efectuada por cualquiera de las Juntas Electorales\"</span>. Por qué fallan las otras: las Juntas Provinciales van al TSJ (art. 10.1.f) y la Junta Electoral Central al Supremo (art. 12.3.a). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-109","p":"Ley 29/1998, art. 2.d). Respecto de los actos de los concesionarios de servicios públicos, ¿qué actos conoce el orden contencioso-administrativo?","o":["Todos los actos de los concesionarios, sin excepción.","Los actos administrativos de control o fiscalización dictados por la Administración concedente respecto de los dictados por los concesionarios que impliquen el ejercicio de potestades administrativas, y los de los propios concesionarios cuando puedan ser recurridos directamente de conformidad con la legislación sectorial.","Únicamente los actos de los concesionarios de servicios públicos locales.","Solo los actos de la Administración concedente sobre contratación, no los de los concesionarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los actos administrativos de control o fiscalización dictados por la Administración concedente respecto de los dictados por los concesionarios que impliquen el ejercicio de potestades administrativas, y los de los propios concesionarios cuando puedan ser recurridos directamente de conformidad con la legislación sectorial</mark></span>El <span class=\"ref-norma\">art. 2.d) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Los actos administrativos de control o fiscalización dictados por la Administración concedente, respecto de los dictados por los concesionarios de los servicios públicos que impliquen el ejercicio de potestades administrativas conferidas a los mismos, así como los actos de los propios concesionarios cuando puedan ser recurridos directamente ante este orden jurisdiccional de conformidad con la legislación sectorial correspondiente\"</span>. Por qué fallan las otras: solo los que impliquen potestades administrativas o sean recurribles directamente según la legislación sectorial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-114","p":"Ley 29/1998, art. 11.1.b). ¿Quién conoce en única instancia de los recursos contra los actos de los Ministros y Secretarios de Estado cuando rectifiquen, en vía de recurso o en procedimiento de fiscalización o de tutela, los dictados por órganos o entes distintos con competencia en todo el territorio nacional?","o":["Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo del Tribunal Supremo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional</mark></span>El <span class=\"ref-norma\">art. 11.1.b) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"De los recursos contra los actos de los Ministros y Secretarios de Estado cuando rectifiquen en vía de recurso o en procedimiento de fiscalización o de tutela los dictados por órganos o entes distintos con competencia en todo el territorio nacional\"</span>. Por qué fallan las otras: la competencia es de la Audiencia Nacional cuando el Ministro o Secretario de Estado rectifica actos de órganos o entes de competencia nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"}]},{"a":"De los Recursos","q":[{"i":"13-13","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Recursos de Queja. Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes recursos de queja:","o":["Las Salas de lo contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo contencioso-administrativo.","La Sala de lo contencioso-administrativo de la Audiencia Nacional.","La Sala de lo contencioso-administrativo del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia.</mark></span><span class=\"ref-norma\">Art. 10.2 · De los Recursos</span>. Fundamento: TÍTULO I. Capítulo II. Órganos y competencias. Artículo 10.2 LJCA: las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso- administrativo, y de los correspondientes recursos de queja."},{"i":"13-26","p":"Corresponde, con arreglo a lo establecido en esta Ley, el conocimiento de los recursos de revisión contra las sentencias firmes de los Juzgados de lo Contencioso- administrativo","o":["Salas de lo contencioso-administrativo de los Tribunales Superiores de Justicia.","Sala de lo contencioso-administrativo de la Audiencia Nacional.","Sala de lo contencioso-administrativo del Tribunal Supremo.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Salas de lo contencioso-administrativo de los Tribunales Superiores de Justicia</mark></span><span class=\"ref-norma\">Art. 102.3 · De los Recursos</span>. Fundamento: El artículo 102.3 de la LJCA establece que la revisión de las sentencias firmes de los Juzgados de lo Contencioso-administrativo (JCA) corresponde a la Sala de lo Contencioso-administrativo del Tribunal Superior de Justicia competente."},{"i":"13-138","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Competencias de las salas de lo contencioso administrativo de los tribunales superiores de justicia. Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes","o":["Recursos de apelación.","Recursos de queja.","Recursos de reposición.","B y C son correctos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Recursos de queja</mark></span><span class=\"ref-norma\">Art. 10.1.f) · De los Recursos</span>. Fundamento: El artículo 10.1.f) de la LJCA establece que las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia conocerán de las apelaciones y de los correspondientes recursos de queja."},{"i":"13-167","p":"Contencioso-Administrativa. La Sala de lo Contencioso-Administrativo de la Audiencia Nacional conocerá de: Señale la INCORRECTA.","o":["De recursos de revisión contra sentencias firmes dictadas por los Juzgados Centrales de lo Contencioso-Administrativo.","En segunda instancia, de las apelaciones contra autos y sentencias dictados por los Juzgados Centrales de lo Contencioso-Administrativo.","De las cuestiones de competencia que se puedan plantear entre los Juzgados Centrales de lo Contencioso-Administrativo.","De la solicitud de autorización, al amparo del artículo 127 ter de la Ley 7/1998, cuando sea formulada por la Agencia Española de Protección de Datos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De la solicitud de autorización, al amparo del artículo 127 ter de la Ley 7/1998, cuando sea formulada por la Agencia Española de Protección de Datos</mark></span>La D es la incorrecta: la autorización es del art. 122 ter de la Ley 29/1998, no del «art. 127 ter de la Ley 7/1998». Según el <span class=\"ref-norma\">arts. 11.2 y 11.5 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Conocerá, en segunda instancia, de las apelaciones contra autos y sentencias dictados por los Juzgados Centrales de lo Contencioso-administrativo y de los correspondientes recursos de queja. [...] Conocerá de la solicitud de autorización al amparo del artículo 122 ter, cuando sea formulada por la Agencia Española de Protección de Datos.\"</span> (verificado con el texto del temario)."},{"i":"13-171","p":"Contencioso-Administrativa. ¿Quién conocerá de los recursos de revisión contra sentencias firmes dictadas por los Juzgados Centrales de lo Contencioso- administrativo?","o":["La Sala de lo Contencioso-Administrativo del Tribunal Superior de Justicia.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","La Sección del Tribunal Constitucional.","Todos son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-Administrativo de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Art. 11.2 · De los Recursos</span>. Fundamento: El artículo 11.2 de la LJCA atribuye el conocimiento de los recursos de revisión contra sentencias firmes dictadas por los Juzgados Centrales de lo Contencioso-Administrativo a la Sala de lo Contencioso- Administrativo de la Audiencia Nacional."},{"i":"13-193","p":"Contencioso-administrativo. Órganos y competencia. ¿Qué órgano conocerá en segunda instancia, de las apelaciones contra autos y sentencias dictados por los Juzgados Centrales de lo Contencioso-administrativo y de los correspondientes recursos de queja?","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Todos son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sala de lo Contencioso-Administrativo de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Art. 10.1 · De los Recursos</span>. Fundamento: El artículo 10.1 de la LJCA atribuye a la Sala de lo Contencioso-Administrativo de la Audiencia Nacional el conocimiento, en segunda instancia, de las apelaciones contra autos y sentencias dictados por los Juzgados Centrales de lo Contencioso-administrativo, así como de los correspondientes recursos de queja."},{"i":"13-249","p":": Competencia territorial de los Juzgados y Tribunales. Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes","o":["Recursos de alzada.","Recursos de queja.","Recursos de reposición.","Recursos de súplica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Recursos de queja</mark></span><span class=\"ref-norma\">Art. 10 · De los Recursos</span> dispone: <span class=\"ref-concepto\">\"n) Cualesquiera otras actuaciones administrativas no atribuidas expresamente a la competencia de otros órganos de este orden jurisdiccional. Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes recursos de queja.\"</span> Fundamento: Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia conocen de las apelaciones y de los correspondientes recursos de queja. (Art. 10.2 LJCA)."},{"i":"13-254","p":"Jurisdicción Contencioso-administrativa. Las Salas de lo Contencioso- Administrativo de los Tribunales Superiores de Justicia conocerán, ______ de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes recursos de queja.","o":["En única instancia.","En primera instancia.","En segunda instancia.","Todos son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En segunda instancia</mark></span>Fundamento: Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocen en segunda instancia de las apelaciones contra sentencias y autos de los Juzgados de lo Contencioso-administrativo, y de los recursos de queja."},{"i":"13-278","p":"Jurisdicción Contencioso-administrativa. Le corresponde, con arreglo a lo establecido en esta Ley, el conocimiento de los recursos de revisión contra las sentencias firmes de los Juzgados de lo Contencioso-administrativo:","o":["Salas de lo contencioso-administrativo de los Tribunales Superiores de Justicia.","Sala de lo contencioso-administrativo de la Audiencia Nacional.","Sala de lo contencioso-administrativo del Tribunal Supremo.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Salas de lo contencioso-administrativo de los Tribunales Superiores de Justicia.</mark></span><span class=\"ref-norma\">Art. 10.3 · De los Recursos</span>. De conformidad con el artículo 10.3 LJCA."},{"i":"13-316","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa. Competencias de las salas de lo contencioso administrativo de los tribunales superiores de justicia. Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes:","o":["Recursos de apelación.","Recursos de queja.","Recursos de reposición.","B y C son correctos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Recursos de queja.</mark></span><span class=\"ref-norma\">Art. 10.2 · De los Recursos</span>. De conformidad con el artículo 10.2 LJCA."},{"i":"13-329","p":"Del orden jurisdiccional contencioso-administrativo. Órganos y competencia. ¿Qué órgano conocerá en segunda instancia, de las apelaciones contra autos y sentencias dictados por los Juzgados Centrales de lo Contencioso-administrativo y de los correspondientes recursos de queja?","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Todos son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sala de lo Contencioso-Administrativo de la Audiencia Nacional.</mark></span><span class=\"ref-norma\">Art. 11.2 · De los Recursos</span>. De conformidad con el artículo 11.2 LJCA."},{"i":"13-345","p":"Competencia territorial de los Juzgados y Tribunales. Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes:","o":["Recursos de alzada.","Recursos de queja.","Recursos de reposición.","Recursos de súplica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Recursos de queja.</mark></span><span class=\"ref-norma\">Art. 10 · De los Recursos</span> dispone: <span class=\"ref-concepto\">\"n) Cualesquiera otras actuaciones administrativas no atribuidas expresamente a la competencia de otros órganos de este orden jurisdiccional. Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados por los Juzgados de lo Contencioso-administrativo, y de los correspondientes recursos de queja.\"</span> De conformidad con el artículo 10.2 LJCA."}]},{"a":"Del Procedimiento en Primera o Única Instancia","q":[{"i":"13-17","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. El plazo para interponer el recurso contencioso-administrativo, será:","o":["De seis meses contados desde el día siguiente al de la publicación o disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.","De seis meses contados desde la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.","De dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.","De dos meses contados desde el de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos meses, contados desde el día siguiente al de la publicación o notificación.</mark></span><span class=\"ref-norma\">Art. 46.1 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: TÍTULO IV. Capítulo I. Sección 1ª. Diligencias preliminares. Artículo 46.1 LJCA: “El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.”"},{"i":"13-24","p":"De la Jurisdicción Contencioso-Administrativa. La sentencia declarará la inadmisibilidad del recurso o de alguna de las pretensiones en los casos siguientes","o":["Que se hubiera interpuesto por persona incapaz, no debidamente representada o no legitimada.","Que recayera sobre cosa juzgada o existiera litispendencia.","Que el Juzgado o Tribunal Contencioso-Administrativo carezca de jurisdicción.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 69 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: Las causas de inadmisibilidad de un recurso contencioso-administrativo se encuentran recogidas en el artículo 69 de la LJCA. Las causas mencionadas en las opciones a), b) y c) (falta de jurisdicción/competencia, falta de capacidad/representación/legitimación, y cosa juzgada/litispendencia) son motivos expresos de inadmisibilidad."},{"i":"13-25","p":"De la Jurisdicción Contencioso-Administrativa. La sentencia declarará la inadmisibilidad del recurso o de alguna de las pretensiones en los casos siguientes: Señale la incorrecta.","o":["Que el Juzgado o Tribunal Contencioso-Administrativo carezca de jurisdicción.","Que se hubiera interpuesto por persona incapaz, no debidamente representada o no legitimada.","Cuando el acto estuviera en cualquier infracción del ordenamiento jurídico.","Que recayera sobre cosa juzgada o existiera litispendencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando el acto estuviera en cualquier infracción del ordenamiento jurídico</mark></span><span class=\"ref-norma\">Art. 69 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: Las opciones a), b) y d) son causas de inadmisibilidad del recurso, según el artículo 69 de la LJCA. La opción c), que el acto esté en cualquier infracción del ordenamiento jurídico (la mera ilegalidad), es un motivo de anulación o nulidad del acto administrativo, es decir, afecta al fondo del asunto, no a su inadmisibilidad procesal."},{"i":"13-47","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recurso y reclamación del expediente. En los litigios entre Administraciones, el plazo para interponer recurso contencioso-administrativo será de dos meses, salvo que por Ley se establezca otra cosa. Cuando hubiere precedido el requerimiento regulado en esta ley, el plazo se contará","o":["Desde el día siguiente a aquel en que se reciba la comunicación del acuerdo expreso o se entienda presuntamente rechazado.","Desde el día siguiente al transcurso del plazo de un mes sin que la Administración atendiera la reclamación o hubiera llegado a un acuerdo con los interesados.","Desde el día siguiente al de la desestimación del plazo para atender el requerimiento.","Desde el día que se inició la actuación administrativa en vía de hecho."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Desde el día siguiente a aquel en que se reciba la comunicación del acuerdo expreso o se entienda presuntamente rechazado</mark></span>Según el <span class=\"ref-norma\">art. 46.6 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Cuando hubiera precedido el requerimiento regulado en los tres primeros apartados del artículo 44, el plazo se contará desde el día siguiente a aquel en que se reciba la comunicación del acuerdo expreso o se entienda presuntamente rechazado.\"</span> (verificado con el texto del temario)."},{"i":"13-48","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recurso y reclamación del expediente. En el recurso dirigido contra una disposición general deberá procederse a la publicación del anuncio de interposición. Tras finalizar esta actuación, el Secretario judicial dará traslado de la demanda para que sea contestada por: Señale la opción correcta.","o":["A los Primeros que se personaron y luego por los demás demandados que se hubieran personado.","Los demandados que se hubieren personado en primer lugar y luego a la Administración.","La Administración o a quien hubiere presentado alegaciones.","A los demandados que se hubieran personado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A los demandados que se hubieran personado</mark></span><span class=\"ref-norma\">Art. 49.3 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: El Art. 49.3 de la LJCA establece que, una vez finalizada la publicación del anuncio de interposición contra una disposición general, el Letrado de la Administración de Justicia dará traslado de la demanda a los demandados que se hubieran personado, para que la contesten."},{"i":"13-50","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recurso y reclamación del expediente. A contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido, el expediente deberá ser remitido en el plazo improrrogable de","o":["Veinte días.","Diez días.","Quince días.","Treinta días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Veinte días</mark></span><span class=\"ref-norma\">Art. 48 · Del Procedimiento en Primera o Única Instancia</span> dispone: <span class=\"ref-concepto\">\"El expediente deberá ser remitido en el plazo improrrogable de veinte días, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido. La entrada se pondrá en conocimiento del órgano jurisdiccional.\"</span> Fundamento: El Art. 48.3 de la LJCA establece que el expediente administrativo deberá ser remitido en el plazo improrrogable de veinte días, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido."},{"i":"13-61","p":"Ley reguladora de la jurisdicción contencioso-administrativa. La sentencia declarará la inadmisibilidad del recurso o de alguna de las pretensiones en los casos siguientes: Señale la incorrecta.","o":["Que el Juzgado o Tribunal Contencioso-administrativo carezca de jurisdicción.","Que se hubiere interpuesto por persona incapaz, no debidamente representada o no legitimada.","Que se recurra por quejas o reclamaciones no admitidas en vía administrativa por la entidad competente.","Que recaiga sobre cosa juzgada o exista litispendencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Que se recurra por quejas o reclamaciones no admitidas en vía administrativa por la entidad competente</mark></span><span class=\"ref-norma\">Art. 69 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: El artículo 69 de la LJCA recoge las causas de inadmisibilidad del recurso. Las opciones (a), (b) y (d) son causas de inadmisibilidad. La opción (c) no está prevista como causa de inadmisibilidad. Lo impugnable son actos y disposiciones, no simples quejas o reclamaciones."},{"i":"13-64","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia de los recursos que se deduzcan en relación con la prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, de 15 de julio, reguladora del Derecho de Reunión?","o":["La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo Contencioso-administrativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia</mark></span><span class=\"ref-norma\">Art. 122.2 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: El artículo 122.2 de la LJCA, dentro del procedimiento para la protección del derecho de reunión, establece que el órgano competente es la Sala de lo Contencioso-Administrativo del Tribunal Superior de Justicia (TSJ) de la Comunidad Autónoma."},{"i":"13-86","p":"Contencioso-administrativa. La sentencia pronunciará alguno de los fallos siguientes","o":["Inadmisibilidad del recurso contencioso-administrativo.","Estimación o desestimación del recurso contencioso-administrativo.","A) y B) son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A) y B) son correctas</mark></span><span class=\"ref-norma\">Art. 68.1 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: *Explicación:* El artículo 68.1 de la LJCA establece que la sentencia se pronunciará sobre la inadmisibilidad del recurso, o sobre la estimación o desestimación de las pretensiones."},{"i":"13-97","p":"Ley reguladora de la jurisdicción contencioso-administrativa. El procedimiento especial de amparo judicial de las libertades y derechos, evacuado el trámite de alegaciones o transcurrido el plazo para efectuarlas, el órgano jurisdiccional decidirá en el siguiente día sobre el recibimiento a prueba. El período probatorio no será en ningún caso superior a _____ comunes para su proposición y práctica.","o":["Quince días.","Diez días.","Veinte días.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días</mark></span><span class=\"ref-norma\">Art. 115.6 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: De acuerdo con el artículo 115.6 de la LJCA (Procedimiento especial de protección de derechos fundamentales), el período de prueba no será superior a veinte días comunes."},{"i":"13-99","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recurso y reclamación del expediente. El expediente deberá ser remitido en un plazo improrrogable, a contar","o":["Desde que la comunicación judicial tenga entrada en el registro general del órgano requerido.","Desde el día siguiente al que la comunicación judicial tenga entrada en el registro general del órgano requerido.","Desde los dos días hábiles siguientes en que la comunicación judicial tenga entrada en el registro general del órgano requerido.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Desde que la comunicación judicial tenga entrada en el registro general del órgano requerido.</mark></span><span class=\"ref-norma\">Art. 48.3 · Del Procedimiento en Primera o Única Instancia</span>. El artículo 48.3 de la LJCA dispone que el expediente deberá remitirse \"en el plazo improrrogable de veinte días, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido\"."},{"i":"13-130","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Formalizada la demanda, el Secretario Judicial dará traslado de la misma al Ministerio Fiscal y a las partes demandadas para que, a la vista del expediente, presenten sus alegaciones en el plazo común e improrrogable de veinte días y acompañen los documentos que estimen oportunos.","o":["A diez días.","Diez días.","Veinte días.","Ocho días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ocho días</mark></span>Según el <span class=\"ref-norma\">art. 119 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...al Ministerio Fiscal y a las partes demandadas para que presenten sus alegaciones en el plazo común e improrrogable de ocho días y acompañen los documentos que estimen oportunos.\"</span> (verificado con el texto del temario)."},{"i":"13-149","p":"Jurisdicción Contencioso-Administrativa. En el caso de prohibición o de propuesta de modificación de reuniones previstas en la Ley Orgánica Reguladora del Derecho de Reunión que no sean aceptadas por los promotores, éstos podrán interponer recurso contencioso-administrativo ante el Tribunal competente. El recurso se interpondría dentro de las _________ siguientes a la notificación de la prohibición o modificación","o":["24 horas.","48 horas.","72 horas.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">48 horas</mark></span><span class=\"ref-norma\">Art. 122.1 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: El recurso contencioso-administrativo contra la prohibición o modificación de reuniones se interpondrá dentro de las cuarenta y ocho horas siguientes a la notificación de la prohibición o modificación (Art. 122.1 LJCA)."},{"i":"13-198","p":"Contencioso-Administrativa. En relación con la sentencia dictada en el procedimiento para la protección de los derechos fundamentales de la persona, señale la CORRECTA.","o":["La sentencia estimará el recurso cuando la disposición, la actuación o el acto incurran en cualquier infracción del ordenamiento jurídico, excepto la desviación de poder, y como consecuencia de la misma vulneren un derecho de los susceptibles de amparo.","El período probatorio no será en ningún caso superior a veinte días comunes para su proposición y práctica.","Contra las sentencias de los Juzgados de lo Contencioso-Administrativo procederá siempre la casación en un solo efecto.","Contra las sentencias de los Juzgados de lo Contencioso-Administrativo procederá siempre la casación en dos efectos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El período probatorio no será en ningún caso superior a veinte días comunes para su proposición y práctica</mark></span>A: incluye «incluso la desviación de poder» (art. 121.2); C y D: contra las sentencias de los Juzgados procede siempre la APELACIÓN en un solo efecto (art. 121.3), no la casación. Según el <span class=\"ref-norma\">art. 120 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El período probatorio no será en ningún caso superior a veinte días comunes para su proposición y práctica.\"</span> (verificado con el texto del temario)."},{"i":"13-206","p":"Jurisdicción Contencioso-administrativa. Procedimientos especiales. En el caso de prohibición o de propuesta de modificación de reuniones previstas en la Ley Orgánica reguladora del Derecho de Reunión, el recurso se interpondrá dentro de: señale la CORRECTA.","o":["Las veinticuatro horas siguientes a la notificación de la prohibición o modificación.","Las cuarenta y ocho horas siguientes a la notificación de la prohibición o modificación.","Las setenta y dos horas siguientes a la notificación de la prohibición o modificación.","Las noventa y seis horas siguientes a la notificación de la prohibición o modificación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las cuarenta y ocho horas siguientes a la notificación de la prohibición o modificación</mark></span><span class=\"ref-norma\">Art. 122.1 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: El artículo 122.1 de la LJCA establece que el recurso contencioso-administrativo contra la prohibición o la propuesta de modificación de reuniones y manifestaciones se interpondrá dentro de las cuarenta y ocho horas siguientes a la notificación de la prohibición o modificación."},{"i":"13-215","p":"Jurisdicción Contencioso-administrativa. Sentencia. La sentencia declarará la inadmisibilidad del recurso o de alguna de las pretensiones en los casos siguientes: señale la opción CORRECTA.","o":["Que el Juzgado o Tribunal Contencioso-administrativo carezca de jurisdicción.","Que se hubiera interpuesto por persona incapaz, no debidamente representada o no legitimada.","Que versen por objeto disposiciones, actos o actuaciones no susceptibles de impugnación.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span><span class=\"ref-norma\">Art. 69 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: El artículo 69 de la LJCA establece los casos en los que el órgano jurisdiccional declarará la inadmisibilidad. Las tres opciones, a), b) y c), son motivos de inadmisibilidad de conformidad con los apartados a), b) y c) de dicho artículo."},{"i":"13-232","p":"Jurisdicción Contencioso-administrativa. Interposición de recurso y reclamación del expediente. Con el escrito de interposición no se acompañan los documentos necesarios, se requerirá al interesado para la subsanación en el plazo de ___________ para que el recurrente pueda llevarla a efecto y, si no lo hiciere, el Juez o Tribunal se pronunciará sobre el archivo de las actuaciones.","o":["Quince días.","Diez días.","Cinco días.","Un mes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span>Fundamento: Si con el escrito de interposición no se acompañan los documentos necesarios, se requerirá la subsanación en un plazo de diez días."},{"i":"13-233","p":"Jurisdicción Contencioso-administrativa. Interposición de recurso y reclamación del expediente. Las multas impuestas a una Administración por la negativa a remitir un expediente reclamado, si no fueran satisfechas voluntariamente, se harán efectivas","o":["Por compensación sobre las personas.","Por ejecución subsidiaria.","Por vía judicial de apremio.","Por vía administrativa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por vía judicial de apremio</mark></span>Según el <span class=\"ref-norma\">art. 48.9 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Si no se hubieran satisfecho voluntariamente, las multas firmes se harán efectivas por vía judicial de apremio.\"</span> (verificado con el texto del temario)."},{"i":"13-237","p":": Interposición de recurso y reclamación del expediente. Se excluirán del expediente, mediante resolución motivada, los documentos clasificados como _____________ haciendo constar así en el índice de documentos y en el lugar del expediente donde se encontrarán los documentos excluidos.","o":["Secreto oficial.","Confidenciales.","Reservados.","Restringidos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Secreto oficial.</mark></span><span class=\"ref-norma\">Art. 48.6 · Del Procedimiento en Primera o Única Instancia</span>. El artículo 48.6 de la LJCA dispone que se excluirán del expediente, mediante resolución motivada, los documentos clasificados como \"secreto oficial\"."},{"i":"13-266","p":"Jurisdicción Contencioso-administrativa. Procedimiento para la protección de los derechos fundamentales de la persona. En el caso de prohibición de reuniones previstas en la Ley Orgánica Reguladora del Derecho de Reunión, los promotores podrán interponer recurso contencioso-administrativo","o":["Dentro de las veinticuatro horas siguientes a la notificación de la prohibición.","Dentro de las cuarenta y ocho horas siguientes a la notificación de la prohibición.","Dentro de las setenta y dos horas siguientes a la notificación de la prohibición.","Dentro de los diez días siguientes a la notificación de la prohibición."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dentro de las cuarenta y ocho horas siguientes a la notificación de la prohibición</mark></span><span class=\"ref-norma\">Art. 122.1 · Del Procedimiento en Primera o Única Instancia</span>. Fundamento: En el procedimiento especial (art. 122.1 LJCA) contra la prohibición de reuniones, el recurso debe interponerse dentro de las cuarenta y ocho horas siguientes a la notificación."},{"i":"13-276","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. La sentencia declarará la inadmisibilidad del recurso o de alguna de las pretensiones en los casos siguientes:","o":["Que se hubiera interpuesto por persona incapaz, no debidamente representada o no legitimada.","Que recayera sobre cosa juzgada o existiera litispendencia.","Que el Juzgado o Tribunal Contencioso-Administrativo carezca de jurisdicción.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 69 · Del Procedimiento en Primera o Única Instancia</span>. De conformidad con el artículo 69 LJCA."},{"i":"13-277","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. La sentencia declarará la inadmisibilidad del recurso o de alguna de las pretensiones en los casos siguientes: Señale la incorrecta.","o":["Que el Juzgado o Tribunal Contencioso-Administrativo carezca de jurisdicción.","Que se hubiera interpuesto por persona incapaz, no debidamente representada o no legitimada.","Cuando el acto estuviera en cualquier infracción del ordenamiento jurídico.","Que recayera sobre cosa juzgada o existiera litispendencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando el acto estuviera en cualquier infracción del ordenamiento jurídico.</mark></span><span class=\"ref-norma\">Art. 69 · Del Procedimiento en Primera o Única Instancia</span>. De conformidad con el artículo 69 LJCA, ya que la infracción del ordenamiento jurídico es causa de estimación (art. 70.2 LJCA), no de inadmisibilidad."},{"i":"13-292","p":"Ley reguladora de la jurisdicción contencioso-administrativa. La sentencia declarará la inadmisibilidad del recurso o de alguna de las pretensiones en los casos siguientes: Señale la incorrecta.","o":["Que el Juzgado o Tribunal Contencioso-administrativo carezca de jurisdicción.","Que se hubiere interpuesto por persona incapaz, no debidamente representada o no legitimada.","Que se recurra por quejas o reclamaciones no admitidas en vía administrativa por la entidad competente.","Que recaiga sobre cosa juzgada o exista litispendencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Que se recurra por quejas o reclamaciones no admitidas en vía administrativa por la entidad competente.</mark></span><span class=\"ref-norma\">Art. 69 · Del Procedimiento en Primera o Única Instancia</span>. De conformidad con el artículo 69 LJCA."},{"i":"13-295","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Qué órgano conocerá, en única instancia de los recursos que se deduzcan en relación con la prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, de 15 de julio, reguladora del Derecho de Reunión?","o":["La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo Contencioso-administrativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.</mark></span><span class=\"ref-norma\">Art. 10.1.h) · Del Procedimiento en Primera o Única Instancia</span>. De conformidad con el artículo 10.1.h) LJCA."},{"i":"13-304","p":"Ley reguladora de la jurisdicción contencioso-administrativa. El procedimiento especial de amparo judicial de las libertades y derechos, evacuado el trámite de alegaciones o transcurrido el plazo para efectuarlas, el órgano jurisdiccional decidirá en el siguiente día sobre el recibimiento a prueba. El período probatorio no será en ningún caso superior a _____ comunes para su proposición y práctica.","o":["Quince días.","Diez días.","Veinte días.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días.</mark></span><span class=\"ref-norma\">Art. 120 · Del Procedimiento en Primera o Única Instancia</span> dispone: <span class=\"ref-concepto\">\"Evacuado el trámite de alegaciones o transcurrido el plazo para efectuarlas, el órgano jurisdiccional decidirá en el siguiente día sobre el recibimiento a prueba, con arreglo a las normas generales establecidas en la presente Ley, y sin perjuicio de lo dispuesto en el artículo 57. El período probatorio no será en ningún caso superior a veinte días comunes para su proposición y práctica.\"</span> De conformidad con el artículo 120 LJCA."},{"i":"13-305","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recurso y reclamación del expediente. El expediente deberá ser remitido en un plazo improrrogable, a contar:","o":["Desde que la comunicación judicial tenga entrada en el registro general del órgano requerido.","Desde el día siguiente al que la comunicación judicial tenga entrada en el registro general del órgano requerido.","Desde los dos días hábiles siguientes en que la comunicación judicial tenga entrada en el registro general del órgano requerido.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Desde que la comunicación judicial tenga entrada en el registro general del órgano requerido.</mark></span><span class=\"ref-norma\">Art. 48.3 · Del Procedimiento en Primera o Única Instancia</span>. De conformidad con el artículo 48.3 LJCA."},{"i":"13-334","p":"Interposición de recurso y reclamación del expediente. Se excluirán del expediente, mediante resolución motivada, los documentos clasificados como _____________ haciendo constar así en el índice de documentos y en el lugar del expediente donde se encontrarán los documentos excluidos.","o":["Secretos u oficiales.","Confidenciales.","Reservados.","Restringidos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Secretos u oficiales.</mark></span><span class=\"ref-norma\">Art. 48.6 · Del Procedimiento en Primera o Única Instancia</span>. De conformidad con el artículo 48.6 LJCA, que se refiere a los documentos clasificados como secreto oficial."},{"i":"13-ia-35","p":"Ley 29/1998, art. 46.4. Si se hubiera interpuesto el recurso potestativo de reposición, el plazo para interponer el recurso contencioso-administrativo se contará:","o":["Desde el día en que se interpuso el recurso de reposición, sin esperar a su resolución expresa o presunta.","Desde el día siguiente a aquel en que se notifique la resolución expresa del recurso de reposición o en que éste deba entenderse presuntamente desestimado.","Desde el día siguiente a la notificación del acto originario, sin que la reposición interrumpa el plazo.","Desde el día siguiente a la firmeza de la resolución en vía administrativa, con un máximo de un año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Desde el día siguiente a aquel en que se notifique la resolución expresa del recurso de reposición o en que éste deba entenderse presuntamente desestimado</mark></span>El <span class=\"ref-norma\">art. 46.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso contencioso-administrativo se contará desde el día siguiente a aquel en que se notifique la resolución expresa del recurso potestativo de reposición o en que éste deba entenderse presuntamente desestimado.\"</span>. Por qué fallan las otras: la reposición interpone el plazo contencioso hasta su resolución expresa o presunta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-48","p":"Ley 29/1998, art. 48.10. Impuestas las tres primeras multas coercitivas sin lograr que se remita el expediente completo, ¿qué hará el Juez o Tribunal?","o":["Pondrá los hechos en conocimiento del Ministerio Fiscal, sin perjuicio de seguir imponiendo nuevas multas.","Archivará las actuaciones y declarará caducado el procedimiento por falta de remisión del expediente.","Dará por conclusa la fase de expediente y dictará sentencia sin él, con apercibimiento al letrado.","Remitirá los hechos al Consejo General del Poder Judicial y cesará de imponer nuevas multas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Pondrá los hechos en conocimiento del Ministerio Fiscal, sin perjuicio de seguir imponiendo nuevas multas</mark></span>El <span class=\"ref-norma\">art. 48.10 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Impuestas las tres primeras multas coercitivas sin lograr que se remita el expediente completo, el Juez o Tribunal pondrá los hechos en conocimiento del Ministerio Fiscal, sin perjuicio de seguir imponiendo nuevas multas.\"</span>. Por qué fallan las otras: las multas continúan; el aviso al Fiscal no las sustituye. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-50","p":"Ley 29/1998, art. 47.1. Cumplido lo dispuesto en el art. 45.3, ¿cuándo acordará el letrado de la Administración de Justicia, si lo solicita el recurrente, que se anuncie la interposición del recurso?","o":["En el plazo de tres días.","En el siguiente día hábil.","En el plazo de cinco días.","En el plazo de diez días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el siguiente día hábil</mark></span>El <span class=\"ref-norma\">art. 47.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Una vez cumplido lo dispuesto en el artículo 45.3, el letrado de la Administración de Justicia en el siguiente día hábil acordará, si lo solicita el recurrente, que se anuncie la interposición del recurso y remitirá el oficio electrónicamente para su publicación por el órgano competente... El letrado de la Administración de Justicia podrá también acordar de oficio la publicación, si lo estima conveniente.\"</span>. Por qué fallan las otras: la publicación también puede acordarse de oficio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-52","p":"Ley 29/1998, art. 48.8. Contra los autos en los que se acuerde la imposición de multas coercitivas por no remitir el expediente administrativo podrá interponerse:","o":["Recurso de reposición en los términos previstos en el art. 79.","Recurso de apelación en un solo efecto.","Recurso de queja ante el tribunal superior.","Recurso de casación ante el Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Recurso de reposición en los términos previstos en el art. 79</mark></span>El <span class=\"ref-norma\">art. 48.8 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Contra los autos en los que se acuerde la imposición de multas a las que se refiere el apartado anterior podrá interponerse recurso de reposición en los términos previstos en el artículo 79\"</span>. Por qué fallan las otras: el recurso es el de reposición. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-55","p":"Ley 29/1998, art. 48.6. ¿Qué documentos se excluirán del expediente administrativo, mediante resolución motivada, haciéndolo constar en el índice de documentos?","o":["Los documentos que contengan datos personales de terceros.","Los documentos elaborados por los servicios jurídicos de la Administración.","Los documentos clasificados como secreto oficial.","Los documentos de carácter reservado o confidencial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los documentos clasificados como secreto oficial</mark></span>El <span class=\"ref-norma\">art. 48.6 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Se excluirán del expediente, mediante resolución motivada, los documentos clasificados como secreto oficial, haciéndolo constar así en el índice de documentos y en el lugar del expediente donde se encontraran los documentos excluidos\"</span>. Por qué fallan las otras: solo se excluyen los clasificados como secreto oficial, no los meramente reservados o confidenciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-56","p":"Ley 29/1998, art. 45.1. El recurso contencioso-administrativo se iniciará, con carácter general, por un escrito reducido a:","o":["Exponer los hechos y fundamentos de derecho y concretar las pretensiones del recurrente.","Citar la disposición, acto, inactividad o actuación constitutiva de vía de hecho que se impugne y solicitar que se tenga por interpuesto el recurso.","Acompañar el expediente administrativo y las pruebas que se propongan.","Solicitar la suspensión cautelar del acto impugnado y fijar la cuantía."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Citar la disposición, acto, inactividad o actuación constitutiva de vía de hecho que se impugne y solicitar que se tenga por interpuesto el recurso</mark></span>El <span class=\"ref-norma\">art. 45.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El recurso contencioso-administrativo se iniciará por un escrito reducido a citar la disposición, acto, inactividad o actuación constitutiva de vía de hecho que se impugne y a solicitar que se tenga por interpuesto el recurso, salvo cuando esta Ley disponga otra cosa\"</span>. Por qué fallan las otras: el escrito de interposición es breve; la demanda con fundamentos viene después (salvo art. 45.4 y 45.5). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-66","p":"Ley 29/1998, art. 48.4. Al remitir el expediente administrativo al órgano jurisdiccional, ¿qué deberá identificar la Administración?","o":["Al órgano responsable del cumplimiento de la resolución judicial.","A la autoridad que dictó el acto impugnado.","Al funcionario encargado de la instrucción del procedimiento.","Al letrado de la Administración de Justicia que lo reclamó."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al órgano responsable del cumplimiento de la resolución judicial</mark></span>El <span class=\"ref-norma\">art. 48.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El expediente se enviará completo, en soporte electrónico, foliado, autentificado y acompañado de un índice, asimismo autentificado, de los documentos que contenga. Al remitir el expediente, la Administración deberá identificar al órgano responsable del cumplimiento de la resolución judicial\"</span>. Por qué fallan las otras: junto al expediente completo, foliado y autentificado, se identifica al órgano responsable del cumplimiento del fallo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-67","p":"Ley 29/1998, art. 48.11. ¿Cómo remitirá la Administración el expediente administrativo al órgano jurisdiccional?","o":["En papel, foliado y autentificado, por correo certificado.","Electrónicamente, pero solo a petición expresa del órgano jurisdiccional.","En soporte electrónico físico entregado en el registro del órgano jurisdiccional.","Electrónicamente, utilizando los sistemas de interoperabilidad aplicables, de modo que quede automáticamente integrado en los sistemas de gestión procesal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Electrónicamente, utilizando los sistemas de interoperabilidad aplicables, de modo que quede automáticamente integrado en los sistemas de gestión procesal</mark></span>El <span class=\"ref-norma\">art. 48.11 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La Administración remitirá el expediente electrónicamente, utilizando, a tal efecto, los sistemas de interoperabilidad que resulten aplicables, al objeto de que el expediente administrativo en soporte electrónico así remitido quede automáticamente integrado en los sistemas de gestión procesal correspondientes\"</span>. Por qué fallan las otras: el envío es electrónico por sistemas de interoperabilidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-72","p":"Ley 29/1998, art. 47.2. Si el recurso se inicia mediante demanda (art. 45.5) y se dirige contra una disposición general, el anuncio de interposición concederá un plazo para la personación de quienes tengan interés legítimo en sostener la conformidad a Derecho de la disposición de:","o":["Diez días.","Quince días.","Cinco días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Quince días</mark></span>El <span class=\"ref-norma\">art. 47.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"deberá procederse a la publicación del anuncio de interposición de aquél, en el que se concederán quince días para la personación de quienes tengan interés legítimo en sostener la conformidad a Derecho de la disposición, acto o conducta impugnados\"</span>. Por qué fallan las otras: el plazo de personación es de quince días; luego se da traslado de la demanda. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-93","p":"Ley 29/1998, art. 48.7. Si el expediente administrativo no se envía en el término de diez días tras la reiteración de la reclamación, el juez o tribunal impondrá una multa coercitiva a la autoridad o empleado responsable. ¿De qué cuantía y cada cuánto se reitera?","o":["De ciento cincuenta a mil quinientos euros, reiterada cada veinte días.","De trescientos a mil doscientos euros, reiterada cada diez días.","De seiscientos a tres mil euros, reiterada cada mes.","De trescientos a mil doscientos euros, reiterada cada veinte días hasta el cumplimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De trescientos a mil doscientos euros, reiterada cada veinte días hasta el cumplimiento</mark></span>El <span class=\"ref-norma\">art. 48.7 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"el juez, la jueza o el tribunal impondrán una multa coercitiva de trescientos a mil doscientos euros a la autoridad o empleado responsable. La multa será reiterada cada veinte días, hasta el cumplimiento de lo requerido\"</span>. Por qué fallan las otras: 150 a 1.500 euros es la multa por incumplir el fallo (art. 112.a), no la del art. 48.7. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-106","p":"Ley 29/1998, art. 45.2.a). Al escrito de interposición del recurso se acompañará el documento que acredite la representación del compareciente, salvo si:","o":["Se hubiera presentado en la vía administrativa previa.","Figurase unido a las actuaciones de otro recurso pendiente ante el mismo Juzgado o Tribunal.","El compareciente sea funcionario público.","El recurso se dirija contra una disposición general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Figurase unido a las actuaciones de otro recurso pendiente ante el mismo Juzgado o Tribunal</mark></span>El <span class=\"ref-norma\">art. 45.2.a) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El documento que acredite la representación del compareciente, salvo si figurase unido a las actuaciones de otro recurso pendiente ante el mismo Juzgado o Tribunal, en cuyo caso podrá solicitarse que se expida certificación para su unión a los autos\"</span>. Por qué fallan las otras: la excepción es que ya conste en otro recurso pendiente ante el mismo órgano; entonces se pide certificación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-120","p":"Ley 29/1998, art. 45.2.c). Al escrito de interposición se acompañará la copia o traslado del acto expreso que se recurra, o indicación del expediente en que haya recaído el acto o el periódico oficial en que la disposición se haya publicado. Si el objeto del recurso fuera la inactividad o una vía de hecho, ¿qué se mencionará?","o":["La fecha del requerimiento previo y el sentido del silencio administrativo.","El nombre del funcionario responsable de la inactividad.","El órgano o dependencia al que se atribuya una u otra y, en su caso, el expediente en que tuvieran origen, o cualesquiera otros datos que identifiquen suficientemente el objeto del recurso.","La cuantía del perjuicio causado y la resolución que lo valore."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El órgano o dependencia al que se atribuya una u otra y, en su caso, el expediente en que tuvieran origen, o cualesquiera otros datos que identifiquen suficientemente el objeto del recurso</mark></span>El <span class=\"ref-norma\">art. 45.2.c) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si el objeto del recurso fuera la inactividad de la Administración o una vía de hecho, se mencionará el órgano o dependencia al que se atribuya una u otra, en su caso, el expediente en que tuvieran origen, o cualesquiera otros datos que sirvan para identificar suficientemente el objeto del recurso\"</span>. Por qué fallan las otras: basta identificar el órgano o dependencia y el expediente u otros datos suficientes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-121","p":"Ley 29/1998, art. 45.4. El recurso de lesividad se iniciará:","o":["Por escrito de interposición reducido a citar el acto impugnado.","Por demanda formulada con arreglo al art. 56.1, a la que se acompañarán en todo caso la declaración de lesividad y el expediente administrativo.","Por requerimiento previo al órgano que dictó el acto.","Por solicitud ante el letrado de la Administración de Justicia sin más documentos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por demanda formulada con arreglo al art. 56.1, a la que se acompañarán en todo caso la declaración de lesividad y el expediente administrativo</mark></span>El <span class=\"ref-norma\">art. 45.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El recurso de lesividad se iniciará por demanda formulada con arreglo al artículo 56.1, que fijará con precisión la persona o personas demandadas y su sede o domicilio si constara. A esta demanda se acompañarán en todo caso la declaración de lesividad, el expediente administrativo y, si procede, los documentos de las letras a) y d) del apartado 2 de este artículo\"</span>. Por qué fallan las otras: el recurso de lesividad empieza directamente por demanda, con la declaración de lesividad y el expediente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-122","p":"Ley 29/1998, art. 45.5. El recurso dirigido contra una disposición general, acto, inactividad o vía de hecho en que no existan terceros interesados podrá iniciarse también:","o":["Mediante requerimiento previo a la Administración demandada.","Mediante demanda, en que se concretará la disposición, acto o conducta impugnados y se razonará su disconformidad a Derecho.","Mediante escrito de interposición, sin que sea posible la demanda.","Mediante declaración de lesividad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Mediante demanda, en que se concretará la disposición, acto o conducta impugnados y se razonará su disconformidad a Derecho</mark></span>El <span class=\"ref-norma\">art. 45.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El recurso dirigido contra una disposición general, acto, inactividad o vía de hecho en que no existan terceros interesados podrá iniciarse también mediante demanda en que se concretará la disposición, acto o conducta impugnados y se razonará su disconformidad a Derecho\"</span>. Por qué fallan las otras: si no hay terceros interesados puede iniciarse directamente por demanda. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-123","p":"Ley 29/1998, art. 46.2. En los supuestos del art. 29 (inactividad y falta de ejecución de actos firmes), los dos meses para interponer el recurso se contarán:","o":["Desde la fecha de la reclamación del interesado.","Desde que la Administración notifique que no va a cumplir.","Desde el día en que se inició la inactividad.","A partir del día siguiente al vencimiento de los plazos señalados en dicho artículo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A partir del día siguiente al vencimiento de los plazos señalados en dicho artículo</mark></span>El <span class=\"ref-norma\">art. 46.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En los supuestos previstos en el artículo 29, los dos meses se contarán a partir del día siguiente al vencimiento de los plazos señalados en dicho artículo\"</span>. Por qué fallan las otras: se cuentan desde el día siguiente al vencimiento de los plazos del art. 29 (tres meses o un mes). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-124","p":"Ley 29/1998, art. 48.1. El expediente administrativo se reclamará:","o":["Siempre al órgano de mayor rango de la Administración demandada.","Al Ministerio Fiscal, que lo recabará de la Administración.","Al órgano autor de la disposición o acto impugnado o a aquél al que se impute la inactividad o vía de hecho.","Al órgano que resolvió el recurso administrativo previo, en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al órgano autor de la disposición o acto impugnado o a aquél al que se impute la inactividad o vía de hecho</mark></span>El <span class=\"ref-norma\">art. 48.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El expediente se reclamará al órgano autor de la disposición o acto impugnado o a aquél al que se impute la inactividad o vía de hecho\"</span>. Por qué fallan las otras: se reclama al órgano autor o al que se impute la inactividad o la vía de hecho. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"}]},{"a":"General / Jurisdicción Contencioso-Administrativa","q":[{"i":"13-22","p":"Contencioso-administrativa. Los Juzgados y Tribunales del orden contencioso- administrativo conocerán","o":["De las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho administrativo.","De las pretensiones que se deduzcan en relación con las disposiciones generales de rango inferior a la ley.","De las pretensiones que se deduzcan en relación con los Decretos legislativos cuando excedan los límites de la delegación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 1 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho Administrativo, con las disposiciones generales de rango inferior a la Ley y con los Decretos legislativos cuando excedan los límites de la delegación.\"</span> Fundamento: Los Juzgados y Tribunales de la jurisdicción Contencioso-administrativa conocen, en general, de las pretensiones relativas a la actuación de la Administración sujeta al Derecho Administrativo (Art. 1.1 LJCA), lo que incluye el control de legalidad de disposiciones de rango inferior a la ley y de los Decretos legislativos que excedan los límites de la delegación (Art. 25 y ss. LJCA). Por lo tanto, todas las opciones son correctas."},{"i":"13-23","p":"De utilidad pública o de interés social para expropiar los derechos o intereses legítimos reconocidos frente a la Administración en una sentencia firme","o":["El peligro cierto de alteración grave del libre ejercicio de los derechos y libertades de los ciudadanos.","El temor fundado de guerra o el quebranto de la integridad del territorio nacional.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span><span class=\"ref-norma\">Art. 105.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 105.2 de la LJCA establece que la declaración de utilidad pública o interés social, a efectos de una expropiación, solo podrá acordarse si concurre el peligro cierto de alteración grave del libre ejercicio de los derechos y libertades (a), o el temor fundado de guerra o el quebranto de la integridad del territorio nacional (b). Por lo tanto, ambas son causas legales."},{"i":"13-31","p":"Contencioso-administrativo es admisible en relación con las disposiciones de carácter general. Señale la incorrecta.","o":["Si estos últimos deciden directamente el fondo del asunto.","Si estos últimos deciden indirectamente el fondo del asunto.","Si estos últimos producen indefensión o perjuicio irreparable a derechos o intereses legítimos.","Si estos últimos determinan la posibilidad de continuar el procedimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Si estos últimos determinan la posibilidad de continuar el procedimiento</mark></span>La D es la incorrecta: el texto dice «imposibilidad» de continuar el procedimiento, no «posibilidad». Según el <span class=\"ref-norma\">art. 25.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...ya sean definitivos o de trámite, si estos últimos deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos o intereses legítimos.\"</span> (verificado con el texto del temario)."},{"i":"13-36","p":"Ley reguladora de la jurisdicción contencioso-administrativa. La competencia de los Juzgados y Salas de lo Contencioso-administrativo deberá ser apreciada por los mismos, incluso de oficio, previa audiencia de las partes y del Ministerio Fiscal por plazo común de","o":["Quince días.","Diez días.","Cinco días.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 5.3 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: Tanto la falta de jurisdicción (Art. 5.3 LJCA) como la falta de competencia (Art. 6.2 LJCA) se apreciarán de oficio previa audiencia de las partes y del Ministerio Fiscal por plazo común de diez días."},{"i":"13-39","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Los Juzgados Centrales de lo Contencioso-administrativo conocerán de los recursos que se deduzcan frente a los actos administrativos que tengan por objeto: Señale la INCORRECTA.","o":["En primera o única instancia, de los recursos contra las resoluciones dictadas por los Ministros y Secretarios de Estado en materia de responsabilidad patrimonial cuando lo reclamado no exceda de 30.000 euros.","En primera instancia, de las resoluciones que acuerden el internamiento de los extranjeros de asilo político.","En primera o única instancia, de las resoluciones en materia de personal cuando se trate de actos dictados por Ministros y Secretarios de Estado.","En única o primera instancia, de las resoluciones que, en vía de fiscalización, sean dictadas por el Comité Español de Disciplina Deportiva en materia de disciplina deportiva."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En primera instancia, de las resoluciones que acuerden el internamiento de los extranjeros de asilo político</mark></span><span class=\"ref-norma\">Art. 9.1.h) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El Art. 9.1.h) de la LJCA atribuye a los Juzgados Centrales el conocimiento de las resoluciones que acuerden el internamiento de extranjeros a efectos de devolución o expulsión, no para las de \"asilo político\". Las resoluciones sobre asilo político son competencia de la Sala de lo Contencioso-administrativo de la Audiencia Nacional o del Tribunal Superior de Justicia de Madrid (Art. 11.1.c)."},{"i":"13-54","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición, de recursos y reclamación del expediente. Cuando el recurso contra la disposición se hubiere iniciado por demanda, el Tribunal podrá recabar de oficio o a petición del actor el expediente de elaboración. Recibido el expediente, el Secretario judicial lo pondrá de manifiesto a las partes por ___________ para que formulen alegaciones.","o":["Cinco días.","Diez días.","Seis días.","Nueve días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cinco días.</mark></span><span class=\"ref-norma\">Art. 48 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Cuando el recurso contra la disposición se hubiere iniciado por demanda, el tribunal podrá recabar de oficio o a petición del actor el expediente de elaboración, que se remitirá en soporte electrónico. Recibido el expediente, el letrado o letrada de la Administración de Justicia lo entregará a las partes por cinco días para que formulen alegaciones.\"</span> El artículo 48.5 de la LJCA dispone que, cuando el recurso contra la disposición se hubiere iniciado por demanda, el tribunal podrá recabar el expediente de elaboración, que se entregará a las partes \"por cinco días\" para que formulen alegaciones."},{"i":"13-66","p":"Ley reguladora del orden jurisdiccional contencioso-administrativo. El orden Jurisdiccional contencioso-administrativo conocerá de las cuestiones que se susciten en relación con la protección jurisdiccional de los derechos fundamentales, los elementos reglados y la determinación de las indemnizaciones que fueran procedentes, todo ello en relación con","o":["Los actos de la administración electoral.","Los actos del Congreso de los Diputados o del Senado o las Asambleas Legislativas de las Comunidades Autónomas.","Los actos del Gobierno o de los Consejos de Gobierno de las Comunidades Autónomas.","Los actos del Consejo General de los órganos de justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los actos del Gobierno o de los Consejos de Gobierno de las Comunidades Autónomas</mark></span><span class=\"ref-norma\">Art. 1.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El recurso contencioso-administrativo se dirige, de forma principal y general, contra la actividad de la Administración Pública (Art. 1.1 y 25.1 LJCA). Los actos del Gobierno central o autonómico son el objeto más frecuente y central de este control jurisdiccional. La opción (b) es en gran medida excluida de la JCA (salvo actos de personal y gestión patrimonial, Art. 1.2.c), por lo que la opción (c) es la más adecuada para describir el ámbito general de conocimiento de la JCA en las materias mencionadas."},{"i":"13-67","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Sentencia. Las sentencias firmes que anulen una disposición general tendrán efectos generales desde","o":["El día siguiente a la publicación de la sentencia por parte del Consejo General del Poder Judicial.","El día en que sea publicado su fallo y preceptos anulados en el mismo periódico oficial en que lo hubiera sido la disposición anulada.","El día siguiente de la publicación del fallo y los preceptos anulados en el mismo periódico oficial en que lo hubiera sido la disposición anulada.","El día en que se notifique el fallo y los preceptos anulados a las partes en el proceso judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El día en que sea publicado su fallo y preceptos anulados en el mismo periódico oficial en que lo hubiera s...</mark></span><span class=\"ref-norma\">Art. 72.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 72.2 de la LJCA establece que la anulación de una disposición tendrá efectos generales \"desde el día en que se publique su fallo y preceptos anulados en el mismo diario oficial en que lo hubiera sido la disposición anulada\"."},{"i":"13-69","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Para aplicar las reglas de distribución de competencia contenidas en esta ley, se tendrán en cuenta los siguientes criterios","o":["La competencia atribuida a los Juzgados y Tribunales para el conocimiento de recursos contra actos administrativos no incluye de forma automática la relativa a la inactividad y a las actuaciones constitutivas de vía de hecho.","Salvo disposición expresa en contrario, la distribución de competencia por razón de territorio prevalece sobre la atribuida en razón del órgano administrativo autor del acto.","Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comp...</mark></span><span class=\"ref-norma\">Art. 7 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: Los criterios de distribución de competencia se encuentran en el artículo 7 de la LJCA: \\(a) es incorrecta. El Art. 7.1 establece que la competencia *incluye de forma automática* la relativa a inactividad y vía de hecho. \\(b) es incorrecta. El Art. 7.2 establece lo contrario: la competencia atribuida en razón del órgano prevalece sobre la atribuida por razón del territorio. \\(c) es correcta. El Art. 7.3 establece que la referencia a las Administraciones (Estado, CCAA, etc.) comprende a sus Entidades y Corporaciones dependientes o vinculadas."},{"i":"13-77","p":"Contencioso-administrativa. ¿Qué órgano conocerá, de las autorizaciones para la entrada e inspección de domicilios, locales, terrenos y medios de transporte que haya sido acordada por la Comisión Nacional de los Mercados y la Competencia, cuando, requiriendo dicho acceso o inspección el consentimiento de su titular, este se oponga a ello o exista riesgo de tal oposición?","o":["Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Juzgados de lo Contencioso-administrativo</mark></span>Según el <span class=\"ref-norma\">art. 8.6 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Además, los Juzgados de lo Contencioso-administrativo conocerán de las autorizaciones para la entrada e inspección de domicilios, locales, terrenos y medios de transporte que haya sido acordada por la Comisión Nacional de los Mercados y la Competencia...\"</span> (verificado con el texto del temario)."},{"i":"13-78","p":"Contencioso-administrativa. ¿Qué órgano conocerá de los recursos que se deduzcan frente a los actos administrativos que tengan por objeto en primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político?","o":["Los Juzgados de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Juzgados Centrales de lo Contencioso-administrativo</mark></span>Lo conocen los Juzgados Centrales, no la Audiencia Nacional. Según el <span class=\"ref-norma\">art. 9.1.e) de la Ley 29/1998 (LJCA)</span>: <span class=\"ref-concepto\">\"En primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político\"</span> (verificado con el texto oficial)."},{"i":"13-81","p":"Contencioso-administrativa. El Secretario judicial mandará oír a las partes por plazo común de ________, previa comprobación de lo alegado, si el Juez o Tribunal dictará auto en el que declarará terminado el procedimiento y ordenará el archivo del recurso y la devolución del expediente administrativo, si el reconocimiento no infringiera manifiestamente el ordenamiento jurídico.","o":["Seis días.","Quince días.","Diez días.","Cinco días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco días</mark></span>Según el <span class=\"ref-norma\">art. 76.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El letrado o letrada de la Administración de Justicia mandará oír a las partes por plazo común de cinco días y, previa comprobación de lo alegado, el juez, la jueza o el tribunal dictarán auto en el que declarará terminado el procedimiento...\"</span> (verificado con el texto del temario)."},{"i":"13-83","p":"Contencioso-administrativa. ¿Qué órgano conocerá de competencia entre los Juzgados de lo Contencioso-administrativo con sede en la Comunidad Autónoma?","o":["Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Los Juzgados Centrales de lo Contencioso-administrativo.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia</mark></span><span class=\"ref-norma\">Art. 6.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: *Explicación:* El artículo 6.2 de la LJCA atribuye a la Sala de lo Contencioso- administrativo del Tribunal Superior de Justicia la resolución de los conflictos de competencia que se planteen entre los Juzgados de lo Contencioso-administrativo de su Comunidad Autónoma."},{"i":"13-85","p":"Contencioso-administrativa. Cuando se hubiera desistido del recurso porque la Administración demandada hubiera reconocido totalmente en vía administrativa las pretensiones del demandante, y después la Administración dictase un nuevo acto total o parcialmente revocatorio del anterior el actor podrá pedir que continúe el procedimiento en el estado en que se encontrase, entendiéndose el acto revocatorio. Si el Juez o Tribunal lo estimase conveniente, concederá a las partes un plazo común de ________ para que formulen por escrito alegaciones complementarias sobre la revocación.","o":["Diez días.","Quince días.","Cinco días.","Treinta días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días</mark></span><span class=\"ref-norma\">Art. 36.3 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: *Explicación:* El artículo 36.3 de la LJCA establece que el Juez o Tribunal concederá a las partes un plazo común de diez días para formular alegaciones complementarias en caso de revocación parcial del acto."},{"i":"13-87","p":"Contencioso-administrativa. En relación con los plazos establecidos para la imposición del recurso contencioso-administrativo: Señale la opción incorrecta.","o":["En los litigios entre Administraciones Públicas, la interposición de un recurso contencioso- administrativo sin requerimiento previo se deberá realizar en el plazo de dos meses salvo que la ley disponga otra cosa.","La interposición de un recurso contencioso-administrativo contra un acto expreso se deberá realizar en el plazo de dos meses contados a partir del día siguiente al de la notificación o publicación del acto que ponga fin a la vía administrativa.","La interposición de un recurso contencioso-administrativo contra la inactividad de la Administración, mediando reclamación previa, tendrá un plazo de un mes desde el siguiente al transcurso del plazo de 3 meses sin que la Administración hubiere dado la resolución o no hubiera llegado a un acuerdo con los interesados.","La interposición de un recurso contencioso-administrativo contra un acto presunto (silencio administrativo) que ordene hacer o dar, se deberá realizar en el plazo de seis meses contados desde el día siguiente a aquel en que se produzca el acto, o bien en cualquier momento posterior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La interposición de un recurso contencioso-administrativo contra la inactividad de la Administración, media...</mark></span><span class=\"ref-norma\">Art. 29.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: *Explicación:* La opción c) es incorrecta. En los casos de inactividad (Art. 29.1 LJCA), tras los tres meses de plazo para reclamar, si la Administración no cumple, el interesado puede interponer recurso contencioso-administrativo en cualquier momento a partir de ese momento (Art. 46.2). La mención de un plazo de \"un mes\" no es correcta."},{"i":"13-90","p":"Ley reguladora de la jurisdicción contencioso-administrativa. La decisión que se adopte por el orden contencioso-administrativo en relación a una cuestión prejudicial o incidental de otro orden. Señale la respuesta correcta.","o":["No produce efectos fuera del proceso en que se dicte y no vinculará al orden jurisdiccional correspondiente.","No producirá efectos fuera del proceso en que se dicte pero vinculará al orden jurisdiccional correspondiente.","Producirá efectos fuera del proceso en que se dicte pero no vinculará al orden jurisdiccional correspondiente.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No produce efectos fuera del proceso en que se dicte y no vinculará al orden jurisdiccional correspondiente</mark></span><span class=\"ref-norma\">Art. 4.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: Conforme al artículo 4.2 de la LJCA, la decisión adoptada por el orden contencioso-administrativo sobre una cuestión prejudicial no administrativa solo tiene efectos *ad cencum* (dentro del proceso), es decir, no produce efectos fuera del proceso ni vincula a otro orden jurisdiccional."},{"i":"13-92","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Sin perjuicio de la excepción que establece esta ley, ¿qué órgano conocerá, en primera o única instancia, de los recursos contencioso-administrativos que se interpongan contra las disposiciones generales y contra los actos emanados de los organismos públicos con personalidad jurídica propia y entidades pertenecientes al sector público estatal con competencia en todo el territorio nacional?","o":["Los Juzgados Centrales de lo Contencioso-administrativo.","Los Juzgados de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Juzgados Centrales de lo Contencioso-administrativo</mark></span>Según el <span class=\"ref-norma\">art. 9.1.c) de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Los Juzgados Centrales de lo Contencioso-administrativo conocerán [...] c) En primera o única instancia de los recursos contencioso-administrativos que se interpongan contra las disposiciones generales y contra los actos emanados de los organismos públicos con personalidad jurídica propia y entidades pertenecientes al sector público estatal con competencia en todo el territorio nacional...\"</span> (verificado con el texto del temario)."},{"i":"13-93","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Los Juzgados de lo Contencioso-administrativo conocerán, en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto: Señale la opción correcta.","o":["Cuestiones de personal.","Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera.","Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de personal laboral de la Administración.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funci...</mark></span><span class=\"ref-norma\">Art. 8 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Conocerán, asimismo, en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto: a) Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera.\"</span> Fundamento: Los Juzgados de lo Contencioso-administrativo son competentes para las cuestiones de personal (Art. 8.4.c LJCA), a excepción de las que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera, de las que conoce el Tribunal Superior de Justicia (Art. 10.1.m LJCA). La opción (b) describe correctamente esta competencia."},{"i":"13-94","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Representación y defensa de las partes. En sus actuaciones ante órganos colegiados","o":["Las partes deberán conferir su representación a un Procurador y ser asistidas por un Abogado.","Las partes podrán conferir su representación a un Procurador y podrán conferir la asistencia a un Abogado.","Las partes podrán conferir su representación a un Procurador y serán asistidas por un Abogado.","Las partes deberán conferir su representación a un Procurador y podrán ser asistidas por un Abogado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las partes deberán conferir su representación a un Procurador y ser asistidas por un Abogado</mark></span><span class=\"ref-norma\">Art. 23.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 23.2 de la LJCA establece que en las actuaciones ante órganos colegiados (Salas), las partes deberán conferir su representación a Procurador y serán asistidas, en todo caso, por Abogado (es obligatorio). Ante órganos unipersonales (Juzgados), la representación por Procurador es potestativa."},{"i":"13-98","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Procedimientos especiales. Admitida a trámite la solicitud a que se refiere la disposición adicional quinta de la Ley Orgánica de Protección de Datos Personales y Garantía de los Derechos Digitales, el Tribunal competente lo notificará a la autoridad de protección de datos a fin de que dé traslado a quienes intervinieron en el procedimiento tramitado ante la misma para que se personen en el plazo de: Señale la opción correcta.","o":["Quince días.","Diez días.","Tres días.","Treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tres días</mark></span>Los diez días son el plazo de alegaciones (apdo. 5) y para decidir (apdo. 7). Según el <span class=\"ref-norma\">art. 122 ter.4 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...a fin de que dé traslado a quienes interviniesen en el procedimiento tramitado ante la misma para que se personen en el plazo de tres días.\"</span> (verificado con el texto del temario)."},{"i":"13-100","p":"Ley reguladora de la jurisdicción contencioso-administrativa. ¿Quién o quiénes están legitimados en los litigios sobre acoso sexual y acoso discriminatorio?","o":["La persona acosada y la Autoridad Independiente para la Igualdad de Trato y la No Discriminación.","Únicamente la persona acosada.","La persona acosada y las asociaciones y organizaciones legalmente constituidas que tengan entre sus fines la defensa y promoción de los derechos de las mujeres.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Únicamente la persona acosada</mark></span><span class=\"ref-norma\">Art. 19.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: La Ley 15/2022, de 12 de julio, de igualdad de trato y no discriminación, modificó el artículo 19.1.i de la LJCA para establecer que la persona acosada será la única legitimada en los litigios sobre acoso sexual y acoso discriminatorio."},{"i":"13-102","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Indique cuál de las siguientes competencias no corresponde a la Sala de lo Contencioso-administrativo de la Audiencia Nacional","o":["En única instancia de los recursos en relación con los convenios entre Administraciones públicas no atribuidos a los Tribunales Superiores de Justicia.","En única instancia de los recursos contra los actos dictados por la Comisión de Vigilancia de Actividades de Financiación del Terrorismo.","En única instancia de los recursos contra los actos del Banco de España, de la Comisión Nacional del Mercado de Valores y del FROB adoptados conforme a lo previsto en la Ley 11/2015, de 18 de junio, de recuperación y resolución de entidades de crédito y empresas de servicios de inversión.","En única instancia de los recursos que se deduzcan en relación con los actos y disposiciones del Consejo General del Poder Judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En única instancia de los recursos que se deduzcan en relación con los actos y disposiciones del Consejo General del Poder Judicial</mark></span>Esa competencia es del Tribunal Supremo, no de la Audiencia Nacional. Según el <span class=\"ref-norma\">arts. 11.1 y 12.1.b) de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá en única instancia de los recursos que se deduzcan en relación con: [...] b) Los actos y disposiciones del Consejo General del Poder Judicial y del Fiscal General del Estado.\"</span> (verificado con el texto del temario)."},{"i":"13-103","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Acordada la prosecución del procedimiento especial de amparo judicial de las libertades y derechos, el Secretario judicial pondrá de manifiesto el recurrente el expediente y demás actuaciones para que en el plazo improrrogable de _____ pueda formalizar la demanda y acompañar los documentos.","o":["Ocho días.","Diez días.","Cinco días.","Quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ocho días</mark></span><span class=\"ref-norma\">Art. 115.5 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 115.5 de la LJCA (Procedimiento especial de protección de derechos fundamentales) establece el plazo improrrogable de ocho días para formalizar la demanda."},{"i":"13-104","p":"Ley reguladora de la jurisdicción contencioso-administrativa. En el procedimiento especial de amparo judicial de las libertades y derechos, conclusas las actuaciones, el órgano jurisdiccional dictará sentencia en el plazo de","o":["Veinte días.","Diez días.","Cinco días.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cinco días.</mark></span><span class=\"ref-norma\">Art. 121.1 · Jurisdicción Contencioso-Administrativa</span>. El artículo 121.1 de la LJCA dispone que, concluidas las actuaciones, el órgano jurisdiccional dictará sentencia \"en el plazo de cinco días\"."},{"i":"13-106","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Sentencia. La sentencia que declare la inadmisibilidad o desestimación del recurso contencioso- administrativo producirá efectos: Señale la opción correcta.","o":["Solo entre las partes.","Entre las partes y sobre todo aquel que pudiera verse afectado por el contenido de la sentencia.","Entre las partes, el Ministerio Fiscal y sobre todo aquel que pudiera verse afectado por el contenido de la sentencia.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Solo entre las partes</mark></span><span class=\"ref-norma\">Art. 72.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 72.1 de la LJCA establece que la sentencia firme produce efectos solo entre las partes. La excepción (efectos *erga omnes*) se aplica únicamente a las sentencias que anulen una disposición general o un acto administrativo que afecte a una pluralidad indeterminada de personas, no a las sentencias de inadmisibilidad o desestimación."},{"i":"13-108","p":"Contencioso-Administrativa. Las pretensiones que se deduzcan en relación con las disposiciones generales conocerán los Juzgados y Tribunales del orden contencioso-administrativo","o":["Cuando sean de rango superior a la ley.","Cuando sean de rango inferior a la ley.","Cuando sean de igual rango a la ley.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando sean de rango inferior a la ley</mark></span>Según el <span class=\"ref-norma\">art. 1.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho Administrativo, con las disposiciones generales de rango inferior a la Ley y con los Decretos legislativos cuando excedan los límites de la delegación.\"</span> (verificado con el texto del temario)."},{"i":"13-109","p":"Contencioso-Administrativa. Los Juzgados y Tribunales del orden contencioso- administrativo conocerán de las pretensiones que se deduzcan, entre otros, en relación con","o":["Con los Decretos legislativos cuando excedan los límites de la delegación.","Con los Decretos-leyes.","Con Leyes (Disposiciones que contienen el reglamento jurídico).","Con los Decretos-leyes cuando excedan los límites de la delegación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con los Decretos legislativos cuando excedan los límites de la delegación</mark></span><span class=\"ref-norma\">Art. 1 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho Administrativo, con las disposiciones generales de rango inferior a la Ley y con los Decretos legislativos cuando excedan los límites de la delegación.\"</span> Fundamento: Con carácter general, el control de las normas con rango de ley (Decretos Legislativos, Decretos-leyes o Leyes) corresponde al Tribunal Constitucional. Sin embargo, el Art. 1.2 de la LJCA, en concordancia con el Art. 82.6 de la CE, establece que el orden contencioso-administrativo sí puede controlar los Decretos Legislativos cuando excedan los límites de la delegación."},{"i":"13-113","p":"Contencioso-Administrativa. Son causas de utilidad pública o de interés social para expropiar los derechos o intereses legítimos reconocidos frente a la Administración en una sentencia firme","o":["El peligro cierto de alteración del libre ejercicio de los derechos y libertades de los ciudadanos.","El temor de guerra.","El quebranto de la integridad del territorio nacional.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 105.3 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El Art. 105.3 de la LJCA recoge estas tres situaciones (literalmente la ley agrupa b y c) como causas que justifican la expropiación forzosa de derechos o intereses reconocidos en una sentencia firme."},{"i":"13-114","p":"Contencioso-Administrativa. El recurrente podrá desistir del recurso","o":["En cualquier momento posterior a la sentencia.","En cualquier momento anterior a la sentencia.","Una vez admitido el recurso no podrá desistir.","Una vez dictada la sentencia y antes de que se ejecute."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En cualquier momento anterior a la sentencia</mark></span><span class=\"ref-norma\">Art. 76.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El Art. 76.1 de la LJCA establece que el demandante podrá desistir del recurso en cualquier momento antes de la sentencia."},{"i":"13-116","p":"Contencioso-Administrativa. El Orden Jurisdiccional Contencioso-Administrativo conocerá de las cuestiones que se susciten en relación con","o":["Los actos y disposiciones de las Corporaciones de Derecho público, adoptados en el ejercicio de funciones públicas.","Los actos y disposiciones de las Corporaciones de Derecho público y privado, adoptados en el ejercicio de funciones públicas.","Los actos y disposiciones de las Corporaciones de Derecho público, adoptados en el ejercicio de funciones privadas.","Los actos y disposiciones de las Corporaciones de Derecho público o privado, adoptados en el ejercicio de funciones públicas o privadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los actos y disposiciones de las Corporaciones de Derecho público, adoptados en el ejercicio de funciones p...</mark></span><span class=\"ref-norma\">Art. 1.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: La Jurisdicción Contencioso-Administrativa controla la actuación de la Administración y las Corporaciones de Derecho Público (ej. Colegios Profesionales) solo cuando ejercen funciones públicas (Art. 1.1 LJCA)."},{"i":"13-119","p":"Contencioso-Administrativa, para aplicar las reglas de distribución de competencia contenidas en la misma, se tendrá en cuenta los siguientes criterios","o":["Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.","La competencia atribuida a los Juzgados y Tribunales para el conocimiento de recursos contra actos administrativos incluye la relativa a la inactividad y a las actuaciones constitutivas de vía de hecho.","Salvo disposición expresa en contrario, la atribución de competencia por razón de la materia prevalece sobre la establecida en razón del órgano administrativo autor del acto.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 4 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: Los criterios (a) y (b) son correctos y se recogen en el Art. 4.a y 4.b de la LJCA. La afirmación (c) es incorrecta en su redacción, ya que el Art. 4.c establece que la competencia atribuida en razón del órgano prevalece sobre la establecida por razón de la materia (es decir, lo contrario de lo que se indica en la opción). No obstante, dado que (d) es una opción de respuesta y las opciones (a) y (b) son verdaderas, se asume que existe un error en la redacción de la opción (c) y que el test pretende que todas sean consideradas como correctas."},{"i":"13-122","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. No pueden interponer recurso contencioso-administrativo contra la actividad de una Administración pública","o":["Los órganos de la misma y los miembros de sus órganos colegiados, salvo que una Ley lo autorice expresamente.","Los particulares cuando obren por delegación o como meros agentes o mandatarios de ella.","Las Entidades de Derecho Público que sean dependientes o estén vinculadas al Estado, las Comunidades Autónomas o las Entidades locales, respecto de la actividad de la Administración de la que dependan. Se exceptúan aquellos a los que por Ley se haya dotado de un estatuto específico de autonomía respecto de otra Administración.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 20 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 20 de la LJCA enumera los sujetos que no pueden interponer recurso contencioso-administrativo, y las tres opciones (a, b, c) coinciden con los supuestos de exclusión establecidos en dicho artículo."},{"i":"13-124","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Respecto de la jurisdicción contenciosa administrativa. Señale la correcta.","o":["La Jurisdicción Contencioso-administrativa es imprescriptible.","Los órganos de este orden jurisdiccional apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma, previa audiencia de las partes y del Ministerio Fiscal por plazo común de 10 días.","A y B son correctas.","Todos son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los órganos de este orden jurisdiccional apreciarán de oficio la falta de jurisdicción y resolverán sobre l...</mark></span><span class=\"ref-norma\">Art. 5.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: La Jurisdicción Contencioso-Administrativa es improrrogable (no imprescriptible). El artículo 5.2 de la LJCA establece que los órganos apreciarán la falta de jurisdicción de oficio, previa audiencia de las partes y del Ministerio Fiscal por plazo común de diez días."},{"i":"13-125","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. De los recursos que se deduzcan en relación con las disposiciones generales y los actos de los Ministros y de los Secretarios de Estado en general conocerán","o":["Los Juzgados de lo Contencioso-administrativo.","Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Art. 11.1.a) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 11.1.a) de la LJCA atribuye a la Sala de lo Contencioso-administrativo de la Audiencia Nacional el conocimiento en única instancia de los recursos en relación con las disposiciones generales y los actos de los Ministros y de los Secretarios de Estado en general."},{"i":"13-126","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Los recursos confirmatorios de actos consentidos por no haber sido recurridos en tiempo y forma","o":["Se admiten.","Son inadmisibles.","Su admisible o impugnación es directa.","La admisible en la impugnación no es directa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Son inadmisibles</mark></span><span class=\"ref-norma\">Art. 28 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 28 de la LJCA establece que no es admisible el recurso contencioso-administrativo respecto de los actos que sean reproducción de otros anteriores definitivos y firmes, ni de los confirmatorios de actos consentidos por no haber sido recurridos en tiempo y forma."},{"i":"13-129","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá de: señale la incorrecta.","o":["Los recursos de revisión contra sentencias firmes dictadas por las Salas de lo Contencioso- administrativo de los Tribunales Superiores de Justicia.","Los recursos que se deduzcan en relación con los actos y disposiciones de la Junta Electoral Central.","Los recursos que se deduzcan en relación con los actos y disposiciones del Consejo General del Poder Judicial.","Los recursos que se deduzcan en relación con los actos del Banco de España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los recursos que se deduzcan en relación con los actos del Banco de España</mark></span><span class=\"ref-norma\">Art. 12 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 12 de la LJCA no incluye en la lista de competencias de la Sala de lo Contencioso-Administrativo del Tribunal Supremo los recursos relativos a los actos del Banco de España en general. Estos suelen ser competencia de la Audiencia Nacional o los Juzgados Centrales. Las opciones (b) y (c) son competencias exclusivas del Tribunal Supremo (Art. 12.1.d y 12.1.c, respectivamente)."},{"i":"13-131","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Corresponde a las Salas de los Contencioso-administrativo de la Audiencia Nacional los recursos contra los actos de cualesquier órganos centrales del Ministerio de Defensa referidos a: Señale la INCORRECTA.","o":["Ascensos.","Retribuciones.","Orden y antigüedad en el escalafonamiento.","Destinos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Retribuciones</mark></span><span class=\"ref-norma\">Art. 11.1.a) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 11.1.a) de la LJCA especifica que la Audiencia Nacional conocerá de los recursos contra actos del Ministerio de Defensa referidos a ascensos, orden y antigüedad en el escalafonamiento y destinos. Las retribuciones no se incluyen en esta lista de competencias exclusivas."},{"i":"13-132","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. ¿Quién conocerá de los recursos contra los actos dictados por la Comisión de Vigilancia de Actividades de Financiación del Terrorismo?","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala del Tribunal Supremo.","Sala de lo contencioso-administrativo de la Audiencia Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Sala de lo contencioso-administrativo de la Audiencia Nacional</mark></span><span class=\"ref-norma\">Art. 11.1.e) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 11.1.e) de la LJCA atribuye a la Sala de lo Contencioso-administrativo de la Audiencia Nacional el conocimiento de los recursos contra los actos dictados por la Comisión de Vigilancia de Actividades de Financiación del Terrorismo."},{"i":"13-133","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Para aplicar las reglas de distribución de competencia se aplicarán los siguientes criterios","o":["Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.","La competencia atribuida a los Juzgados y Tribunales para el conocimiento de recursos contra actos administrativos incluye la relativa a la inactividad y a las actuaciones constitutivas de vía de hecho.","Salvo disposición expresa en contrario, la atribución de competencia por razón de la materia prevalece sobre la efectuada en razón del órgano administrativo autor del acto.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 8 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 8 de la LJCA establece las reglas para la determinación de la competencia, y las opciones (a, b, c) son correctas al coincidir con lo dispuesto en los apartados 1, 2 y 4 de dicho artículo."},{"i":"13-136","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Cuando la Administración no ejecute actos firmes podrán los afectados solicitar su ejecución, y si esta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo.","o":["En el plazo de un mes.","En el plazo de dos meses.","En el plazo de tres meses.","En el plazo de seis meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo de un mes</mark></span><span class=\"ref-norma\">Art. 29 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Cuando la Administración no ejecute sus actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de un mes desde tal petición, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará por el procedimiento abreviado regulado en el artículo 78.\"</span> Fundamento: El artículo 29.2 de la LJCA establece que si la Administración no ejecuta sus actos firmes en el plazo de un mes desde que se solicitó su ejecución, los interesados podrán interponer recurso contencioso-administrativo."},{"i":"13-137","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. ¿Qué organismo conocerá de recursos de casación y revisión contra las resoluciones dictadas por el Tribunal de Cuentas, con arreglo a lo establecido en su Ley de Funcionamiento?","o":["Sala del Tribunal Superior de Justicia.","Sala de la Audiencia Nacional.","Sala del Tribunal Constitucional.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas</mark></span><span class=\"ref-norma\">Art. 12.1.a) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 12.1.a) de la LJCA establece que el organismo competente es la Sala de lo Contencioso-Administrativo del Tribunal Supremo, que no figura en las opciones (a, b, c)."},{"i":"13-140","p":"Jurisdicción Contencioso-Administrativa. Reclamación a la Administración del cumplimiento de una obligación. Si la Administración no hubiera dado cumplimiento a lo solicitado o no hubiese llegado a un acuerdo con los interesados, éstos pueden deducir recurso contencioso-administrativo contra la inactividad de la Administración","o":["En el plazo de un mes desde la fecha de la reclamación.","En el plazo de dos meses desde la fecha de la reclamación.","En el plazo de seis meses desde la fecha de la reclamación.","En el plazo de tres meses desde la fecha de la reclamación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En el plazo de tres meses desde la fecha de la reclamación</mark></span>Según el <span class=\"ref-norma\">art. 29.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Si en el plazo de tres meses desde la fecha de la reclamación, la Administración no hubiera dado cumplimiento a lo solicitado o no hubiera llegado a un acuerdo con los interesados, éstos pueden deducir recurso contencioso-administrativo contra la inactividad de la Administración.\"</span> (verificado con el texto del temario)."},{"i":"13-146","p":"Jurisdicción Contencioso-Administrativa. Interposición del recurso y reclamación del expediente. El expediente deberá ser remitido en el plazo improrrogable de ________, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido. La entrada se pondrá en conocimiento del órgano jurisdiccional.","o":["Diez días.","Quince días.","Veinte días.","Veinticinco días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días</mark></span><span class=\"ref-norma\">Art. 48 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"El expediente deberá ser remitido en el plazo improrrogable de veinte días, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido. La entrada se pondrá en conocimiento del órgano jurisdiccional.\"</span> Fundamento: El expediente administrativo deberá ser remitido al órgano jurisdiccional en el plazo improrrogable de veinte días (Art. 48.3 LJCA)."},{"i":"13-150","p":"Jurisdicción Contencioso-Administrativa. En los litigios sobre acoso sexual y acoso discriminatorio, estarán legitimados: señale la CORRECTA.","o":["Únicamente la persona acosada.","Únicamente el Ministerio Fiscal.","Los organismos públicos con competencia en la materia.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Únicamente la persona acosada</mark></span><span class=\"ref-norma\">Art. 19.1.i) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: Según el Art. 19.1.i) de la LJCA, modificado por la Ley 15/2022, la persona acosada será la única legitimada en los litigios sobre acoso sexual y acoso discriminatorio."},{"i":"13-151","p":"Jurisdicción Contencioso-Administrativa. Los actos y disposiciones de los órganos de gobierno de las asambleas legislativas de las Comunidades Autónomas en materia de personal, administración y gestión patrimonial corresponderán a","o":["Los Juzgados de lo Contencioso-administrativo.","Los Juzgados Centrales de lo Contencioso-administrativo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia</mark></span><span class=\"ref-norma\">Art. 10.1.c) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: Corresponde a las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocer en única instancia de los actos y disposiciones de los órganos de gobierno de las asambleas legislativas de las Comunidades Autónomas en materia de personal, administración y gestión patrimonial (Art. 10.1.c) LJCA)."},{"i":"13-153","p":"Jurisdicción Contencioso-Administrativa. Están legitimados ante el orden jurisdiccional contencioso-administrativo: señale la INCORRECTA.","o":["Las personas físicas o jurídicas que ostenten un derecho o interés legítimo.","Las corporaciones, asociaciones, sindicatos y grupos y entidades a que se refiere el artículo 18 que resulten afectados o estén legalmente habilitados para la defensa de los derechos e intereses legítimos colectivos.","Las entidades locales territoriales, cuando ostenten un derecho o interés legítimo, para impugnar los actos y disposiciones de la Administración de las Comunidades Autónomas y de los Organismos públicos vinculados a éstas, así como los de los Entes locales.","La Administración de las Comunidades Autónomas, para impugnar los actos y disposiciones que afecten al ejercicio de su autonomía, emanados de la Administración del Estado y de cualquier otra Administración u Organismo público, así como los de las Entidades locales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las entidades locales territoriales, cuando ostenten un derecho o interés legítimo, para impugnar los actos...</mark></span><span class=\"ref-norma\">Art. 19.1.e) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El Art. 19.1.e) LJCA legitima a las entidades locales territoriales para impugnar actos que afecten al ejercicio de su autonomía, emanados de la Administración del Estado, la de las Comunidades Autónomas y *cualquier otra Administración u Organismo público*. La opción (c) resulta INCORRECTA al especificar que pueden impugnar actos de los \"Entes locales\", cuando el precepto legal se refiere en general a la Administración del Estado y de las CCAA y sus organismos, y no a los actos de otras entidades locales que no sean de ámbito superior."},{"i":"13-155","p":"Jurisdicción Contencioso-Administrativa. Corresponde a la Sala de lo Contencioso-Administrativo de la Audiencia Nacional conocer de los recursos contra","o":["Las disposiciones y actos de los Ministros y Secretarios de Estado en materia de personal, cuando procedan en única o ulterior instancia.","Los actos de la Administración General del Estado que no estén atribuidos a otra instancia.","Las resoluciones en materia de extranjería y asilo no atribuidas a los Juzgados Centrales de lo Contencioso-Administrativo.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 11.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: La Sala de lo Contencioso-Administrativo de la Audiencia Nacional es competente para conocer de los recursos citados en las opciones a), b) y c) (Art. 11.1.a, b, y c) LJCA)."},{"i":"13-156","p":"Jurisdicción Contencioso-Administrativa. ¿Quién conocerá de los recursos contra actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno?","o":["La Sala de lo Contencioso-administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo del Tribunal Supremo</mark></span><span class=\"ref-norma\">Art. 12 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá en única instancia de los recursos que se deduzcan en relación con: a) Los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno.\"</span> Fundamento: Corresponde a la Sala de lo Contencioso-Administrativo del Tribunal Supremo conocer de los recursos contra actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno (Art. 12.1.a) LJCA)."},{"i":"13-157","p":"Jurisdicción Contencioso-Administrativa. Corresponde a la Sala de lo Contencioso-administrativo de la Audiencia Nacional","o":["En primera o única instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas.","En primera instancia, de las resoluciones que acuerdan la inadmisión de las peticiones de asilo político.","Las resoluciones dictadas por el Tribunal Económico-administrativo Central en materia de tributos cedidos.","Las resoluciones dictadas por el Tribunal Administrativo Central de Recursos Contractuales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las resoluciones dictadas por el Tribunal Administrativo Central de Recursos Contractuales</mark></span><span class=\"ref-norma\">Art. 11.1.f) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: La Sala de lo Contencioso-Administrativo de la Audiencia Nacional es competente para conocer de los recursos interpuestos contra las resoluciones del Tribunal Administrativo Central de Recursos Contractuales (TACRC) (Art. 11.1.f) LJCA). Las opciones a), b) y c) son competencia, respectivamente, de los TSJ, los Juzgados Centrales de lo CA (inadmisión de asilo) y la Audiencia Nacional (resoluciones del TEAC Central en general, sin la limitación a tributos cedidos que haría la opción imprecisa)."},{"i":"13-164","p":"Contencioso-Administrativa. La declaración de incompetencia adoptará la forma de","o":["Decreto.","Sentencia.","Providencia.","Auto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Auto</mark></span><span class=\"ref-norma\">Art. 37 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: Las resoluciones sobre la incompetencia del órgano judicial se adoptan en forma de Auto, de acuerdo con el artículo 37 de la LJCA."},{"i":"13-165","p":"Contencioso-Administrativa. Están legitimados ante el orden jurisdiccional contencioso-administrativo, _____________ en ejercicio de la acción popular, en los casos expresamente previstos por las leyes.","o":["Cualquier ciudadano.","El Ministerio Fiscal.","Las Entidades de Derecho Público.","Las Entidades locales territoriales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cualquier ciudadano</mark></span><span class=\"ref-norma\">Art. 19.1.g) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 19.1.g) de la LJCA establece que estará legitimado cualquier ciudadano en ejercicio de la acción popular, en los casos previstos por las leyes."},{"i":"13-166","p":"Contencioso-Administrativa. Podrán, no obstante, comparecer por sí mismos los funcionarios públicos en defensa de sus derechos estatutarios, cuando se refieran a cuestiones","o":["Actuaciones ante órganos colegiados.","Actuaciones ante órganos unipersonales.","De personal que no impliquen separación de empleados públicos inamovibles.","De personal que no impliquen separación de empleados públicos movibles."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De personal que no impliquen separación de empleados públicos inamovibles</mark></span><span class=\"ref-norma\">Art. 23.3 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 23.3 de la LJCA permite a los funcionarios públicos comparecer por sí mismos en defensa de sus derechos estatutarios, cuando se refieran a cuestiones de personal que no impliquen separación de empleados públicos inamovibles."},{"i":"13-168","p":"Jurisdicción Contencioso-administrativa. Respecto al expediente","o":["El expediente original o copiado, se enviará completo, foliado y, en su caso, autentificado, acompañado de un índice, asimismo autentificado y sellado de los documentos que contenga.","El expediente original, sin posibilidad de copia, se enviará completo, foliado y, en su caso, autentificado, acompañado de un índice, asimismo autentificado y sellado de los documentos que contenga.","El expediente original o copiado, se enviará completo, foliado y, en su caso, autentificado, acompañado de un índice, asimismo autentificado, de los documentos que contenga.","El expediente se enviará completo, en soporte electrónico, foliado, autentificado y acompañado de un índice, asimismo autentificado, de los documentos que contenga."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El expediente se enviará completo, en soporte electrónico, foliado, autentificado y acompañado de un índice, asimismo autentificado, de los documentos que contenga</mark></span>Según el <span class=\"ref-norma\">art. 48.4 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El expediente se enviará completo, en soporte electrónico, foliado, autentificado y acompañado de un índice, asimismo autentificado, de los documentos que contenga.\"</span> (verificado con el texto del temario)."},{"i":"13-169","p":"Contencioso-Administrativa. Si la Administración realizare alguna actividad que contraviniera los pronunciamientos del fallo de la sentencia, el Juez o Tribunal, a instancia de los interesados, procederá","o":["A reponer la situación al estado exigido por el fallo.","A conformar los daños y perjuicios que establezcan el incumplimiento.","A iniciar la ejecución forzosa.","A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A reponer la situación al estado exigido por el fallo</mark></span><span class=\"ref-norma\">Art. 109.1 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 109.1 de la LJCA establece que si la Administración realizare alguna actividad que contraviniera los pronunciamientos del fallo, el Juez o Tribunal, a instancia de los interesados, repondrá la situación al estado exigido por el fallo."},{"i":"13-170","p":"Contencioso-Administrativa. Singularmente, acreditada su responsabilidad, previo apercibimiento del Secretario Judicial notificado personalmente para formulación de alegaciones, el Juez o la Sala podrán","o":["Imponer multas coercitivas de cien a mil quinientos euros a los afectados, funcionarios o agentes que incumplan los requerimientos del Juez o de la Sala.","Deducir el oportuno testimonio de particulares para exigir la responsabilidad penal a que pudiera corresponder.","Imponer una pena privada de libertad de 1 a 5 años.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Deducir el oportuno testimonio de particulares para exigir la responsabilidad penal a que pudiera corresponder</mark></span><span class=\"ref-norma\">Art. 112.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 112.2 de la LJCA permite al Juez o Sala, acreditada la responsabilidad de autoridades, funcionarios o agentes, deducir el oportuno testimonio de particulares para exigir la responsabilidad penal a que hubiera lugar. Las multas coercitivas del art. 112.1 son de 150 a 1.500 euros y se imponen a la Administración."},{"i":"13-174","p":"Contencioso-Administrativa. No corresponde, entre otros, al orden jurisdiccional contencioso-administrativo","o":["Las cuestiones expresamente atribuidas a los órdenes jurisdiccionales civil, penal y social, aunque estén relacionadas con la actividad de la Administración pública.","El recurso contencioso-disciplinario militar.","Los recursos directos que se interpongan contra las normas forales de las Juntas Generales de los Territorios Históricos de Álava, Guipúzcoa y Vizcaya, que corresponderán, en exclusiva, al Tribunal Constitucional.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 3.1.b) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 3.1.b), d) y e) de la LJCA establece las exclusiones del ámbito contencioso-administrativo. a) Correcto (art. 3.1.b)). b) Correcto (art. 3.1.d)). c) Correcto (art. 3.1.e)). Por lo tanto, todas son correctas como exclusiones."},{"i":"13-178","p":"Contencioso-Administrativo conocerán en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto las reclamaciones por responsabilidad patrimonial cuya cuantía","o":["No excedan de 30.050 €.","No excedan de 60.000 €.","Excedan de 60.000 €.","Excedan de 30.050 €."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No excedan de 30.050 €</mark></span><span class=\"ref-norma\">Art. 8.2.c) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 8.2.c) de la LJCA establece que los Juzgados de lo Contencioso-administrativo conocerán de las reclamaciones por responsabilidad patrimonial cuya cuantía no exceda de 30.050 euros (o su equivalente en pesetas, 5.000.000, en el texto original, con la posterior conversión)."},{"i":"13-180","p":"Lo Contencioso-Administrativo conocerán de los recursos que se deduzcan frente a los actos administrativos que tengan por objeto; señale la INCORRECTA.","o":["En única o primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político.","En primera o única instancia, de los recursos contra las resoluciones dictadas por los Ministros y Secretarios de Estado en materia de responsabilidad patrimonial cuando la reclamación no exceda de 30.050 euros.","En primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político.","En única o primera instancia, de las resoluciones que, en vía de fiscalización, sean dictadas por el Comité Español de Disciplina Deportiva en materia de disciplina deportiva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En única o primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político</mark></span>Es solo «en primera instancia»; decir «única o primera» es lo incorrecto. Según el <span class=\"ref-norma\">art. 9.1.e) de la Ley 29/1998 (LJCA)</span>: <span class=\"ref-concepto\">\"En primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político\"</span> (verificado con el texto oficial)."},{"i":"13-182","p":"Contencioso-Administrativo conocerán en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto","o":["Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera.","Las sanciones administrativas que consistan en multas no superiores a 30.050 euros y en ceses de actividades o privación de ejercicio de derechos que no excedan de seis meses.","Las reclamaciones por responsabilidad patrimonial cuya cuantía no exceda de 60.000 euros.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funci...</mark></span><span class=\"ref-norma\">Art. 8 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Conocerán, asimismo, en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto: a) Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera.\"</span> Fundamento: De acuerdo con el artículo 8.2 de la LJCA, los Juzgados de lo Contencioso-Administrativo conocen de los recursos frente a actos de las CCAA (salvo Consejo de Gobierno) en estos casos. La opción \\'a\\' es correcta, mientras que \\'b\\' y \\'c\\' tienen cuantías o plazos incorrectos (30.050€ y 6 meses; y 30.050€ respectivamente)."},{"i":"13-183","p":"________________ conocerán de los recursos que se deduzcan frente a los actos administrativos que tengan por objeto, en primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político.","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Juzgados Centrales de lo Contencioso-Administrativo</mark></span><span class=\"ref-norma\">Art. 9.1.d) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 9.1.d) de la LJCA atribuye a los Juzgados Centrales de lo Contencioso-Administrativo el conocimiento, en única o primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político."},{"i":"13-187","p":"Única o primera instancia del recurso contencioso-administrativo que se interponga contra los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno?","o":["La Sala de lo Contencioso-Administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Todos son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-Administrativo del Tribunal Supremo</mark></span><span class=\"ref-norma\">Art. 12 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá en única instancia de los recursos que se deduzcan en relación con: a) Los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno.\"</span> Fundamento: El artículo 12.1.a) de la LJCA atribuye a la Sala de lo Contencioso-Administrativo del Tribunal Supremo el conocimiento, en única instancia, de los recursos contra los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno."},{"i":"13-189","p":"Acoso sexual y acoso por razón de sexo estarán legitimados ante el orden jurisdiccional contencioso-administrativo","o":["La persona acosada será la única legitimada.","Ministerio Fiscal.","La persona acosada y siempre con su autorización, los organismos públicos con competencia en la materia.","A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La persona acosada será la única legitimada</mark></span>Según el <span class=\"ref-norma\">art. 19.1.i) de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"La persona acosada será la única legitimada en los litigios sobre acoso sexual y acoso discriminatorio.\"</span> (verificado con el texto del temario)."},{"i":"13-190","p":"En materia tributaria, de personal al servicio de la Administración pública y de unidad de mercado, los efectos de una sentencia firme que hubiera reconocido una situación jurídica individualizada a favor de una o varias personas podrán extenderse a otras, en ejecución de la sentencia, cuando concurran las siguientes circunstancias: señale la CORRECTA.","o":["Que los interesados se encuentren en idéntica situación jurídica que los favorecidos por el fallo.","Que el Juez o Tribunal sentenciador fuera también competente, por razón del territorio, para conocer de sus pretensiones de reconocimiento de dicha situación individualizada.","Que soliciten la extensión de los efectos de la sentencia en el plazo de un año desde la última notificación de ésta a quienes fueron parte en el proceso.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Las tres circunstancias son literales, luego «Todas son correctas». Según el <span class=\"ref-norma\">art. 110.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...a) Que los interesados se encuentren en idéntica situación jurídica que los favorecidos por el fallo. b) Que el juez o tribunal sentenciador fuera también competente, por razón del territorio... c) Que soliciten la extensión de los efectos de la sentencia en el plazo de un año desde la última notificación de ésta...\"</span> (verificado con el texto del temario)."},{"i":"13-191","p":"Contencioso-Administrativo. ¿Qué órgano conocerá de los recursos que se deduzcan en relación con los actos y disposiciones de la Junta Electoral Central?","o":["La Sala de lo Contencioso-Administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Juzgados Centrales de lo Contencioso-Administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-Administrativo del Tribunal Supremo</mark></span><span class=\"ref-norma\">Art. 12 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá en única instancia de los recursos que se deduzcan en relación con: a) Los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno.\"</span> Fundamento: El artículo 12.1.d) de la LJCA atribuye a la Sala de lo Contencioso-Administrativo del Tribunal Supremo el conocimiento, en única instancia, de los recursos contra los actos y disposiciones de la Junta Electoral Central."},{"i":"13-192","p":"Incompetencia adoptará la forma de","o":["Providencia y deberá efectuarse antes de la sentencia.","Auto y deberá efectuarse antes de la sentencia.","Providencia y deberá efectuarse junto con la sentencia.","Auto y deberá efectuarse antes de la vista de las partes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Auto y deberá efectuarse antes de la sentencia</mark></span><span class=\"ref-norma\">Art. 5.3 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 5.3 de la LJCA establece que la declaración de incompetencia adoptará la forma de auto y deberá efectuarse antes de la sentencia."},{"i":"13-196","p":"Del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con","o":["La actuación de las Administraciones públicas.","Las disposiciones generales.","Los Decretos legislativos cuando excedan los límites de la delegación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 1 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Los Juzgados y Tribunales del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho Administrativo, con las disposiciones generales de rango inferior a la Ley y con los Decretos legislativos cuando excedan los límites de la delegación.\"</span> Fundamento: El ámbito de la jurisdicción contencioso- administrativa abarca la actuación de las Administraciones Públicas (art. 1), las disposiciones generales (art. 1, art. 25 y ss.), y los Decretos legislativos cuando excedan los límites de la delegación (art. 1, art. 26). Por lo tanto, todas son correctas. Este vídeo [[El Procedimiento Contencioso Administrativo 【RESUMEN, Ley 29/1998】]{.underline}](https://www.youtube.com/watch?v=cY3EkdJcnyI) proporciona un resumen de la Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa, que es el tema de las preguntas del test."},{"i":"13-200","p":"Contencioso-Administrativa. La declaración de incompetencia. Si la competencia pudiera corresponder a un Tribunal superior en grado","o":["Se acompañará una exposición razonada, instándole a lo que resuelva éste.","De manera tácita se entenderá que es el Tribunal superior quien continuará.","Se le entregará lo actuado y el Tribunal inferior resolverá.","Todos son incorrectos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se acompañará una exposición razonada, instándole a lo que resuelva éste</mark></span><span class=\"ref-norma\">Art. 8.3 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 8.3 de la LJCA establece que \"Cuando la incompetencia pudiera corresponder a un Tribunal superior en grado, el Juez o Tribunal se abstendrá de conocer remitiendo las actuaciones a aquél, quien decidirá por medio de auto, y si estima su competencia, lo comunicará al que planteó la cuestión para que le envíe el expediente administrativo.\" La opción \\'a\\' refleja correctamente la intención de remitir y solicitar una resolución."},{"i":"13-205","p":"Jurisdicción Contencioso-administrativa. Se entenderá a estos efectos por Administraciones públicas: señale la INCORRECTA.","o":["Entidades de derecho privado dependientes o no del Estado, de las Comunidades Autónomas o Entidades Locales.","Las Entidades que integran la Administración local.","Las Administraciones de las Comunidades Autónomas.","La Administración General del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Entidades de derecho privado dependientes o no del Estado, de las Comunidades Autónomas o Entidades Locales</mark></span><span class=\"ref-norma\">Art. 1.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 1.2 de la LJCA establece que a los efectos de esta Ley, se entenderá por Administraciones públicas (entre otras) las de los apartados b, c y d. Las entidades de derecho privado que estén vinculadas o dependientes de las Administraciones Públicas y actúen en el ejercicio de potestades administrativas son sujetos a la jurisdicción contencioso-administrativa, pero no se consideran \"Administraciones públicas\" *per se* en el sentido estricto del ámbito de la LJCA."},{"i":"13-214","p":"Contencioso-Administrativa. Las sentencias firmes que anulen una disposición general","o":["No afectará por sí mismas a la eficacia de las sentencias o actos administrativos firmes que lo hayan aplicado antes de que la anulación alcanzara efectos generales, salvo en el caso de que la anulación del precepto supusiera la exclusión o la limitación de las sanciones aún no ejecutadas completamente.","Podrán afectar por sí mismas a la eficacia de las sentencias o actos administrativos firmes que lo hayan aplicado antes de que la anulación alcanzara efectos generales.","Afectarán por sí mismas a la eficacia de las sentencias o actos administrativos firmes que lo hayan aplicado antes de que la anulación alcanzara efectos generales.","Todos son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No afectará por sí mismas a la eficacia de las sentencias o actos administrativos firmes que lo hayan aplic...</mark></span><span class=\"ref-norma\">Art. 72.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El artículo 72.2 de la LJCA establece que las sentencias firmes que anulen una disposición general no afectarán por sí mismas a la eficacia de las sentencias o actos administrativos firmes que lo hayan aplicado antes de que la anulación alcanzara efectos generales, salvo excepciones."},{"i":"13-217","p":"Jurisdicción Contencioso-administrativa. Interposición del recurso y reclamación del expediente. Examinado el recurso, si el Secretario judicial estima que no concurren los exigidos por esta Ley para la validez de la comparecencia, requerirá inmediatamente la subsanación de los mismos, señalando un plazo de","o":["Tres días para que el recurrente pueda llevarla a efecto.","Cinco días para que el recurrente pueda llevarla a efecto.","Siete días para que el recurrente pueda llevarla a efecto.","Diez días para que el recurrente pueda llevarla a efecto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Diez días para que el recurrente pueda llevarla a efecto</mark></span>Fundamento: La ley establece un plazo de diez días para la subsanación de los requisitos de validez de la comparecencia."},{"i":"13-221","p":"Jurisdicción Contencioso-administrativa. Sentencia. Cuando se publicarán las sentencias firmes que anulen un acto administrativo?","o":["Cuando afecten a una pluralidad determinada de personas.","Cuando afecten a una pluralidad indeterminada de personas.","Cuando no sea posible efectuar la notificación a una de las partes.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando afecten a una pluralidad indeterminada de personas</mark></span>Fundamento: La Ley establece que se publicarán las sentencias firmes que anulen un acto administrativo cuando afecten a una pluralidad indeterminada de personas (similar a cuando se anula una disposición general)."},{"i":"13-234","p":"Jurisdicción Contencioso-administrativa. Se entenderá a estos efectos por Administraciones públicas: señale la INCORRECTA.","o":["La Administración General del Estado.","Las Administraciones de las Comunidades Autónomas.","Las Entidades que integran la Administración regional.","Las Entidades de Derecho público que estén vinculadas al Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Entidades que integran la Administración regional</mark></span>Fundamento: La Ley 29/1998 no utiliza el concepto \"Administración regional\" o \"Entidades que integran la Administración regional\" para definir el ámbito subjetivo. Se refiere a la Administración General del Estado, las Administraciones de las Comunidades Autónomas y las Entidades que integran la Administración Local, así como las Entidades de Derecho Público vinculadas."},{"i":"13-235","p":"Jurisdicción Contencioso-administrativa. Se entenderá a estos efectos por Administraciones públicas: señale la INCORRECTA.","o":["La Administración General del Estado.","Las Administraciones de las Comunidades Autónomas.","Las Entidades que integran la Administración regional.","Las Entidades de Derecho público que estén vinculadas al Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Entidades que integran la Administración regional</mark></span>Fundamento: Pregunta idéntica a la 18. La Ley no utiliza el concepto \"Administración regional\" o \"Entidades que integran la Administración regional\"."},{"i":"13-239","p":": Los JUZGADOS DE LO CONTENCIOSO-ADMINISTRATIVO conocerán asimismo, en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto las sanciones administrativas que consistan en multas no superiores a _____________ euros o en ceses de actividades o privación de ejercicio de derechos que no excedan de seis meses.","o":["30.000 euros.","60.000 euros.","90.000 euros.","600.000 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">60.000 euros.</mark></span><span class=\"ref-norma\">Art. 8.2.b) · Jurisdicción Contencioso-Administrativa</span>. El artículo 8.2.b) de la LJCA atribuye a los Juzgados de lo Contencioso-administrativo el conocimiento de las sanciones administrativas que consistan en multas no superiores a \"60.000 euros\"."},{"i":"13-242","p":": Están legitimados ante el orden jurisdiccional contencioso-administrativo: señale la INCORRECTA.","o":["Las corporaciones, asociaciones, sindicatos y grupos y entidades a que se refieren la ley que resulten afectados o estén legalmente habilitados para la defensa de los derechos e intereses legítimos colectivos.","La Administración del Estado, cuando ostente un derecho o interés legítimo, para impugnar los actos y disposiciones de la Administración de las Comunidades Autónomas y de los Organismos públicos vinculados a éstas, así como los de las Entidades locales, de conformidad con lo dispuesto en la legislación de régimen local, y los de cualquier otra entidad pública no sometida a su fiscalización.","La Administración de las Comunidades Autónomas, para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de la Administración del Estado y de cualquier otra Administración u Organismo público, así como los de las Entidades locales, de conformidad con lo dispuesto en la legislación de régimen local.","Las personas físicas o jurídicas que ostenten un derecho o interés ilegítimo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las personas físicas o jurídicas que ostenten un derecho o interés ilegítimo</mark></span><span class=\"ref-norma\">Art. 19.1.a) · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El Art. 19.1.a) de la LJCA exige ostentar un derecho o interés legítimo, no ilegítimo, para estar legitimado. Por lo tanto, la opción (d) es la incorrecta."},{"i":"13-244","p":": Ámbito. La Jurisdicción Contencioso-Administrativa se entenderá a estos efectos por Administraciones públicas, entre otros","o":["La Administración General del Estado.","Las Administraciones de las Comunidades Autónomas.","Las Entidades de Derecho público que sean dependientes o estén vinculadas al Estado, las Comunidades Autónomas o las Entidades locales.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 1.2 · Jurisdicción Contencioso-Administrativa</span>. Fundamento: El concepto de Administraciones Públicas en el ámbito de la Jurisdicción Contencioso-administrativa abarca las enumeradas en las opciones a), b) y c) (y otros entes). (Art. 1.2 LJCA)."},{"i":"13-247","p":": Sentencia. La Sentencia _____________ el recurso cuando se ajusten a Derecho la disposición, acto o actuación impugnados.","o":["No admitirá.","Rechazará.","Estimará.","Desestimará."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Desestimará</mark></span><span class=\"ref-norma\">Art. 70 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La sentencia desestimará el recurso cuando se ajusten a Derecho la disposición, acto o actuación impugnados.\"</span> Fundamento: La Sentencia desestimará el recurso cuando la disposición, el acto o la actuación impugnados se ajusten a Derecho. (Art. 70.8 LJCA)."},{"i":"13-250","p":": Procedimiento de amparo judicial de las libertades y derechos en el orden contencioso administrativo. Concluidas las actuaciones, el órgano jurisdiccional dictará sentencia","o":["En el plazo de cinco días.","En el plazo de ocho días.","En el plazo de diez días.","En el plazo de quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo de cinco días.</mark></span><span class=\"ref-norma\">Art. 121.1 · Jurisdicción Contencioso-Administrativa</span>. El artículo 121.1 de la LJCA dispone que, concluidas las actuaciones, el órgano jurisdiccional dictará sentencia \"en el plazo de cinco días\"."},{"i":"13-253","p":"Jurisdicción Contencioso-administrativa. Sentencia. La sentencia pronunciará alguno de los fallos siguientes","o":["Inadmisibilidad del recurso contencioso-administrativo.","Estimación del recurso contencioso-administrativo.","Desestimación del recurso contencioso-administrativo.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Fundamento: La Ley 29/1998 (LJCA) establece que la sentencia puede declarar la inadmisibilidad, la estimación o la desestimación del recurso."},{"i":"13-255","p":"Jurisdicción Contencioso-administrativa. Ejecución de las sentencias. En materia tributaria, de personal al servicio de la Administración pública y de unidad de mercado, los efectos de una sentencia firme que hubiera reconocido una situación jurídica individualizada a favor de una o varias personas podrán extenderse a otras, en ejecución de la sentencia, cuando concurran las siguientes circunstancias","o":["Que los interesados se encuentren en idéntica situación jurídica que los favorecidos por el fallo.","Que el Juez o tribunal sentenciador fuera también competente, por razón del territorio, para conocer de sus pretensiones de reconocimiento de dicha situación individualizada.","Que soliciten la extensión de los efectos de la sentencia en el plazo de un año desde la última notificación de ésta a quienes fueron parte en el proceso. Si se hubiera interpuesto recurso en interés de ley o de revisión, este plazo se contará desde la última notificación de la resolución que ponga fin a éste.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 110.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...a) Que los interesados se encuentren en idéntica situación jurídica que los favorecidos por el fallo. b) Que el juez o tribunal sentenciador fuera también competente, por razón del territorio... c) Que soliciten la extensión de los efectos de la sentencia en el plazo de un año desde la última notificación de ésta...\"</span> (verificado con el texto del temario)."},{"i":"13-256","p":"Jurisdicción Contencioso-administrativa. No corresponde a la Sala de lo Contencioso-administrativo de la Audiencia Nacional","o":["En única instancia de los recursos en relación con los convenios entre Administraciones públicas no atribuidos a los Tribunales Superiores de Justicia.","En única instancia las resoluciones dictadas por el Tribunal Administrativo Central de Recursos Contractuales.","De los recursos de revisión contra sentencias firmes dictadas por los Juzgados Centrales de lo Contencioso-administrativo.","En única instancia de los recursos que se deduzcan en relación con los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En única instancia de los recursos que se deduzcan en relación con los actos y disposiciones del Consejo de...</mark></span>Fundamento: El conocimiento en única instancia de los recursos contra actos y disposiciones del Consejo de Ministros y Comisiones Delegadas del Gobierno corresponde a la Sala de lo Contencioso-Administrativo del Tribunal Supremo, no a la Audiencia Nacional (AN). Las opciones a), b) y c) sí son competencia de la AN."},{"i":"13-258","p":"Jurisdicción Contencioso-administrativa. No corresponde a la Sala de lo Contencioso-administrativo de la Audiencia Nacional","o":["En única instancia de los recursos en relación con los convenios entre Administraciones públicas no atribuidos a los Tribunales Superiores de Justicia.","En única instancia las resoluciones dictadas por el Tribunal Administrativo Central de Recursos Contractuales.","De los recursos de revisión contra sentencias firmes dictadas por los Juzgados Centrales de lo Contencioso-administrativo.","En única instancia de los recursos que se deduzcan en relación con los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En única instancia de los recursos que se deduzcan en relación con los actos y disposiciones del Consejo de...</mark></span>Fundamento: Mismo contenido que la Pregunta 4. La competencia es del Tribunal Supremo."},{"i":"13-259","p":"Jurisdicción Contencioso-administrativa. ¿A quién corresponde en única o primera instancia, de las resoluciones que, en vía de fiscalización, sean dictadas por el Comité Español de Disciplina Deportiva en materia de disciplina deportiva?","o":["A la Sala de lo Contencioso-administrativo de la Audiencia Nacional.","A los Juzgados de lo Contencioso-administrativo.","A las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","A los Juzgados Centrales de lo Contencioso-administrativo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A los Juzgados Centrales de lo Contencioso-administrativo</mark></span>Fundamento: La LJCA atribuye a los Juzgados Centrales de lo Contencioso-administrativo el conocimiento, en única o primera instancia, de las resoluciones dictadas por el Comité Español de Disciplina Deportiva en materia de disciplina deportiva."},{"i":"13-260","p":"Contencioso-administrativa. Del escrito planteando la cuestión incidental el Secretario judicial dará traslado a las partes para que aleguen lo que estimen procedente","o":["En plazo común que no excederá de diez días.","En plazo común que no excederá de quince días.","En plazo común que no excederá de veinte días.","En plazo común que no excederá de treinta días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En plazo común que no excederá de veinte días</mark></span>Los diez días son el plazo del Juez para dictar el auto (art. 109.3). Según el <span class=\"ref-norma\">art. 109.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Del escrito planteando la cuestión incidental el Secretario judicial dará traslado a las partes para que, en plazo común que no excederá de veinte días, aleguen lo que estimen procedente.\"</span> (verificado con el texto del temario)."},{"i":"13-261","p":"Jurisdicción Contencioso-administrativa. Para la defensa de los derechos e intereses de las personas víctimas de discriminación por orientación e identidad sexual, expresión de género o características sexuales, además de las personas afectadas y siempre que cuenten con su autorización expresa, estarán también legitimados: señale la INCORRECTA.","o":["Los partidos políticos.","Las organizaciones empresariales.","Las asociaciones profesionales de personas trabajadoras autónomas.","Las asociaciones de personas consumidoras y productoras."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las asociaciones de personas consumidoras y productoras</mark></span>Fundamento: Según la Ley, además de las personas afectadas (con su autorización expresa), están legitimados: partidos políticos, organizaciones sindicales, organizaciones empresariales y asociaciones profesionales de personas trabajadoras autónomas (opciones a, b, c). La opción d) Las asociaciones de personas consumidoras y productoras es la INCORRECTA."},{"i":"13-273","p":"Ley 29/1998, de 13 de julio, Reguladora de la Jurisdicción Contencioso-Administrativa. Del escrito planteando la cuestión incidental el Secretario Judicial dará traslado a las partes para que, en plazo común que ________ aleguen lo que estimen procedente.","o":["Excederá de diez días.","No excederá de quince días.","No excederá de veinte días.","No excederá de veintidós días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No excederá de veinte días.</mark></span><span class=\"ref-norma\">Art. 109 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Del escrito planteando la cuestión incidental el Secretario judicial dará traslado a las partes para que, en plazo común que no excederá de veinte días, aleguen lo que estimen procedente.\"</span> De conformidad con el artículo 109.2 LJCA."},{"i":"13-275","p":"Jurisdicción Contencioso-administrativa. Son causas de utilidad pública o de interés social para expropiar los derechos o intereses legítimos reconocidos frente a la Administración en una sentencia firme:","o":["El peligro cierto de alteración grave del libre ejercicio de los derechos y libertades de los ciudadanos.","El temor fundado de guerra o el quebranto de la integridad del territorio nacional.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas.</mark></span><span class=\"ref-norma\">Art. 105.3 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 105.3 LJCA."},{"i":"13-282","p":"Jurisdicción Contencioso-administrativa. El recurso contencioso-administrativo es admisible en relación con las disposiciones de carácter general. Señale la incorrecta.","o":["Si estos últimos deciden directamente el fondo del asunto.","Si estos últimos deciden indirectamente el fondo del asunto.","Si estos últimos producen indefensión o perjuicio irreparable a derechos o intereses legítimos.","Si estos últimos determinan la posibilidad de continuar el procedimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Si estos últimos determinan la posibilidad de continuar el procedimiento.</mark></span><span class=\"ref-norma\">Art. 25.1 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 25.1 LJCA, que exige que determinen la IMPOSIBILIDAD (no la posibilidad) de continuar el procedimiento."},{"i":"13-283","p":"Jurisdicción Contencioso-administrativa. Los órganos de este orden jurisdiccional apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma, previa audiencia de las partes y del Ministerio Fiscal por plazo común de:","o":["Diez días.","Cinco días.","Ocho días.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez días.</mark></span><span class=\"ref-norma\">Art. 5 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La Jurisdicción Contencioso-administrativa es improrrogable. 2. Los órganos de este orden jurisdiccional apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma, previa audiencia de las partes y del Ministerio Fiscal por plazo común de diez días.\"</span> De conformidad con el artículo 5.2 LJCA."},{"i":"13-286","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Interposición de recursos y reclamación del expediente. Cuando el recurso contra la disposición se hubiere iniciado por demanda, el Tribunal podrá recabar de oficio o a petición del actor el expediente de elaboración. Recibido el expediente, el Secretario judicial lo pondrá de manifiesto a las partes por ___________ para que formulen alegaciones.","o":["Cinco días.","Diez días.","Seis días.","Nueve días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cinco días.</mark></span><span class=\"ref-norma\">Art. 48 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Cuando el recurso contra la disposición se hubiere iniciado por demanda, el tribunal podrá recabar de oficio o a petición del actor el expediente de elaboración, que se remitirá en soporte electrónico. Recibido el expediente, el letrado o letrada de la Administración de Justicia lo entregará a las partes por cinco días para que formulen alegaciones.\"</span> De conformidad con el artículo 48.5 LJCA."},{"i":"13-297","p":"Ley reguladora del orden jurisdiccional contencioso-administrativo. El orden Jurisdiccional contencioso-administrativo conocerá de las cuestiones que se susciten en relación con la protección jurisdiccional de los derechos fundamentales, los elementos reglados y la determinación de las indemnizaciones que fueran procedentes, todo ello en relación con:","o":["Los actos de la administración electoral.","Los actos del Congreso de los Diputados o del Senado o las Asambleas Legislativas de las Comunidades Autónomas.","Los actos del Gobierno o de los Consejos de Gobierno de las Comunidades Autónomas.","Los actos del Consejo General de los órganos de justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los actos del Gobierno o de los Consejos de Gobierno de las Comunidades Autónomas.</mark></span><span class=\"ref-norma\">Art. 2 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"El orden jurisdiccional contencioso-administrativo conocerá de las cuestiones que se susciten en relación con: a) La protección jurisdiccional de los derechos fundamentales, los elementos reglados y la determinación de las indemnizaciones que fueran procedentes, todo ello en relación con los actos del Gobierno o de los Consejos de Gobierno de las Comunidades Autónomas, cualquiera que fuese la naturaleza de dichos actos.\"</span> De conformidad con el artículo 2.a) LJCA."},{"i":"13-298","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Sentencia. Las sentencias firmes que anulen una disposición general tendrán efectos generales desde:","o":["El día siguiente a la publicación de la sentencia por parte del Consejo General del Poder Judicial.","El día en que sea publicado su fallo y preceptos anulados en el mismo periódico oficial en que lo hubiera sido la disposición anulada.","El día siguiente de la publicación del fallo y los preceptos anulados en el mismo periódico oficial en que lo hubiera sido la disposición anulada.","El día en que se notifique el fallo y los preceptos anulados a las partes en el proceso judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El día en que sea publicado su fallo y preceptos anulados en el mismo periódico oficial en que lo hubiera sido la disposición anulada.</mark></span><span class=\"ref-norma\">Art. 72.2 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 72.2 LJCA."},{"i":"13-300","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Para aplicar las reglas de distribución de competencia contenidas en esta ley, se tendrán en cuenta los siguientes criterios:","o":["La competencia atribuida a los Juzgados y Tribunales para el conocimiento de recursos contra actos administrativos no incluye de forma automática la relativa a la inactividad y a las actuaciones constitutivas de vía de hecho.","Salvo disposición expresa en contrario, la distribución de competencia por razón de territorio prevalece sobre la atribuida en razón del órgano administrativo autor del acto.","Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.</mark></span><span class=\"ref-norma\">Art. 13 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Para aplicar las reglas de distribución de competencia contenidas en los artículos anteriores, se tendrán en cuenta los siguientes criterios: a) Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.\"</span> De conformidad con el artículo 13.a) LJCA."},{"i":"13-302","p":"Ley reguladora de la jurisdicción contencioso-administrativa. El Secretario judicial mandará oír a las partes por plazo común de ________, previa comprobación de lo alegado, si el Juez o Tribunal dictará auto en el que declarará terminado el procedimiento y ordenará el archivo del recurso y la devolución del expediente administrativo, si el reconocimiento no infringiera manifiestamente el ordenamiento jurídico.","o":["Seis días.","Quince días.","Diez días.","Cinco días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco días.</mark></span><span class=\"ref-norma\">Art. 76.2 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 76.2 LJCA."},{"i":"13-303","p":"Ley reguladora de la jurisdicción contencioso-administrativa. En relación con los plazos establecidos para la imposición del recurso contencioso-administrativo: Señale la opción incorrecta.","o":["En los litigios entre Administraciones Públicas, la interposición de un recurso contencioso-administrativo sin requerimiento previo se deberá realizar en el plazo de dos meses salvo que la ley disponga otra cosa.","La interposición de un recurso contencioso-administrativo contra un acto expreso se deberá realizar en el plazo de dos meses contados a partir del día siguiente al de la notificación o publicación del acto que ponga fin a la vía administrativa.","La interposición de un recurso contencioso-administrativo contra la inactividad de la Administración, mediando reclamación previa, tendrá un plazo de un mes desde el siguiente al transcurso del plazo de 3 meses sin que la Administración hubiere dado la resolución o no hubiera llegado a un acuerdo con los interesados.","La interposición de un recurso contencioso-administrativo contra un acto presunto (silencio administrativo) que ordene hacer o dar, se deberá realizar en el plazo de seis meses contados desde el día siguiente a aquel en que se produzca el acto, o bien en cualquier momento posterior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La interposición de un recurso contencioso-administrativo contra la inactividad de la Administración, mediando reclamación previa, tendrá un plazo de un mes desde el siguiente al transcurso del plazo de 3 meses sin que la Administración hubiere dado la resolución o no hubiera llegado a un acuerdo con los interesados.</mark></span><span class=\"ref-norma\">Art. 46.2 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 46.2 LJCA, que fija en ese caso un plazo de dos meses, no de un mes."},{"i":"13-306","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Acordada la prosecución del procedimiento especial de amparo judicial de las libertades y derechos, el Secretario judicial pondrá de manifiesto el recurrente el expediente y demás actuaciones para que en el plazo improrrogable de _____ pueda formalizar la demanda y acompañar los documentos.","o":["Ocho días.","Diez días.","Cinco días.","Quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ocho días.</mark></span><span class=\"ref-norma\">Art. 118 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Acordada la prosecución del procedimiento especial de este capítulo, el Secretario judicial pondrá de manifiesto al recurrente el expediente y demás actuaciones para que en el plazo improrrogable de ocho días pueda formalizar la demanda y acompañar los documentos.\"</span> De conformidad con el artículo 118 LJCA."},{"i":"13-307","p":"Ley reguladora de la jurisdicción contencioso-administrativa. En el procedimiento especial de amparo judicial de las libertades y derechos, conclusas las actuaciones, el órgano jurisdiccional dictará sentencia en el plazo de:","o":["Veinte días.","Diez días.","Cinco días.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cinco días.</mark></span><span class=\"ref-norma\">Art. 121.1 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 121.1 LJCA."},{"i":"13-309","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa. Son causas de utilidad pública o de interés social para expropiar los derechos o intereses legítimos reconocidos frente a la Administración en una sentencia firme:","o":["El peligro cierto de alteración del libre ejercicio de los derechos y libertades de los ciudadanos","El temor de guerra","El quebranto de la integridad del territorio nacional","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 105.3 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 105.3 LJCA."},{"i":"13-310","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa. El recurrente podrá desistir del recurso:","o":["En cualquier momento posterior a la sentencia.","En cualquier momento anterior a la sentencia.","Una vez admitido el recurso no podrá desistir.","Una vez dictada la sentencia y antes de que se ejecute"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En cualquier momento anterior a la sentencia.</mark></span><span class=\"ref-norma\">Art. 74.1 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 74.1 LJCA."},{"i":"13-311","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa. El Orden Jurisdiccional Contencioso-Administrativo conocerá de las cuestiones que se susciten en relación con:","o":["Los actos y disposiciones de las Corporaciones de Derecho público, adoptados en el ejercicio de funciones públicas.","Los actos y disposiciones de las Corporaciones de Derecho público y privado, adoptados en el ejercicio de funciones públicas.","Los actos y disposiciones de las Corporaciones de Derecho público, adoptados en el ejercicio de funciones privadas.","Los actos y disposiciones de las Corporaciones de Derecho público o privado, adoptados en el ejercicio de funciones públicas o privadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los actos y disposiciones de las Corporaciones de Derecho público, adoptados en el ejercicio de funciones públicas.</mark></span><span class=\"ref-norma\">Art. 2.c) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 2.c) LJCA."},{"i":"13-313","p":"Ley 29/98, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa, para aplicar las reglas de distribución de competencia contenidas en la misma, se tendrá en cuenta los siguientes criterios:","o":["Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.","La competencia atribuida a los Juzgados y Tribunales para el conocimiento de recursos contra actos administrativos incluye la relativa a la inactividad y a las actuaciones constitutivas de vía de hecho.","Salvo disposición expresa en contrario, la atribución de competencia por razón de la materia prevalece sobre la establecida en razón del órgano administrativo autor del acto.","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 13 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 13 LJCA."},{"i":"13-314","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa. Para aplicar las reglas de distribución de competencia se aplicarán los siguientes criterios:","o":["Las referencias que se hacen a la Administración del Estado, Comunidades Autónomas y Entidades locales comprenden a las Entidades y Corporaciones dependientes o vinculadas a cada una de ellas.","La competencia atribuida a los Juzgados y Tribunales para el conocimiento de recursos contra actos administrativos incluye la relativa a la inactividad y a las actuaciones constitutivas de vía de hecho.","Salvo disposición expresa en contrario, la atribución de competencia por razón de la materia prevalece sobre la efectuada en razón del órgano administrativo autor del acto.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 13 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 13 LJCA."},{"i":"13-315","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-Administrativa. ¿Qué organismo conocerá de recursos de casación y revisión contra las resoluciones dictadas por el Tribunal de Cuentas, con arreglo a lo establecido en su Ley de Funcionamiento?","o":["Sala del Tribunal Superior de Justicia.","Sala de la Audiencia Nacional.","Sala del Tribunal Constitucional.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas.</mark></span><span class=\"ref-norma\">Art. 12.2.b) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 12.2.b) LJCA, que atribuye esa competencia a la Sala de lo Contencioso-administrativo del Tribunal Supremo, no recogida entre las opciones."},{"i":"13-319","p":"Los Juzgados de lo Contencioso-Administrativo conocerán en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto las reclamaciones por responsabilidad patrimonial cuya cuantía:","o":["No excedan de 30.050 €.","No excedan de 60.000 €.","Excedan de 60.000 €.","Excedan de 30.050 €."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No excedan de 30.050 €.</mark></span><span class=\"ref-norma\">Art. 8.2.c) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 8.2.c) LJCA."},{"i":"13-320","p":"Los Juzgados Centrales de lo Contencioso-Administrativo conocerán de los recursos que se deduzcan frente a los actos administrativos que tengan por objeto; señale la INCORRECTA.","o":["En única o primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político.","En primera o única instancia, de los recursos contra las resoluciones dictadas por los Ministros y Secretarios de Estado en materia de responsabilidad patrimonial cuando la reclamación no exceda de 30.050 euros.","En primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político.","En única o primera instancia, de las resoluciones que, en vía de fiscalización, sean dictadas por el Comité Español de Disciplina Deportiva en materia de disciplina deportiva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En única o primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político.</mark></span><span class=\"ref-norma\">Art. 9.1.e) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 9.1.e) LJCA, que dice literalmente \\\"en primera instancia\\\" (y no \\\"única o primera instancia\\\") para la inadmisión de peticiones de asilo político."},{"i":"13-322","p":"Los Juzgados de lo Contencioso-Administrativo conocerán en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto:","o":["Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera.","Las sanciones administrativas que consistan en multas no superiores a 30.050 euros y en ceses de actividades o privación de ejercicio de derechos que no excedan de seis meses.","Las reclamaciones por responsabilidad patrimonial cuya cuantía no exceda de 60.000 euros.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera.</mark></span><span class=\"ref-norma\">Art. 8 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"Conocerán, asimismo, en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto: a) Cuestiones de personal, salvo que se refieran al nacimiento o extinción de la relación de servicio de funcionarios públicos de carrera.\"</span> De conformidad con el artículo 8.2.a) LJCA."},{"i":"13-323","p":"Los ________________ conocerán de los recursos que se deduzcan frente a los actos administrativos que tengan por objeto, en primera instancia, de las resoluciones que acuerden la inadmisión de las peticiones de asilo político.","o":["Juzgados de lo Contencioso-Administrativo.","Juzgados Centrales de lo Contencioso-Administrativo.","Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Juzgados Centrales de lo Contencioso-Administrativo.</mark></span><span class=\"ref-norma\">Art. 9.1.e) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 9.1.e) LJCA."},{"i":"13-324","p":"Ámbito. Señale la INCORRECTA.","o":["La Jurisdicción Contencioso-administrativa es improrrogable.","Los órganos de este orden jurisdiccional apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma, previa audiencia de las partes y del Ministerio Fiscal por plazo común de diez días.","Si una declaración se solicitara a un órgano que se estimase incompetente, lo declarará así por auto y remitirá las actuaciones a la Sala del Tribunal Superior de Justicia que se estime competente.","Si la parte no demandada se personara ante el órgano en el plazo de un mes desde la publicación de la resolución que declara la falta de jurisdicción, se entenderá haberlo efectuado en la fecha en que se inició el plazo para interponer el recurso contencioso-administrativo, a efectos tomándose esta segunda fecha las indicaciones de la notificación del acto o total de los dos meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si una declaración se solicitara a un órgano que se estimase incompetente, lo declarará así por auto y remitirá las actuaciones a la Sala del Tribunal Superior de Justicia que se estime competente.</mark></span><span class=\"ref-norma\">Art. 5.3 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 5.3 LJCA, que remite al órgano de la jurisdicción que se estime competente, no necesariamente a la Sala del Tribunal Superior de Justicia."},{"i":"13-326","p":"¿Qué órganos conocerán en única o primera instancia del recurso contencioso-administrativo que se interponga contra los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno?","o":["La Sala de lo Contencioso-Administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Todos son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-Administrativo del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 12 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá en única instancia de los recursos que se deduzcan en relación con: a) Los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno.\"</span> De conformidad con el artículo 12.1.a) LJCA."},{"i":"13-327","p":"Procedimiento Contencioso-Administrativo. ¿Qué órgano conocerá de los recursos que se deduzcan en relación con los actos y disposiciones de la Junta Electoral Central?","o":["La Sala de lo Contencioso-Administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","Juzgados Centrales de lo Contencioso-Administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-Administrativo del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 12 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá en única instancia de los recursos que se deduzcan en relación con: a) Los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno.\"</span> De conformidad con el artículo 12.3.a) LJCA."},{"i":"13-328","p":"La declaración de incompetencia adoptará la forma de:","o":["Auto y deberá efectuarse antes de la sentencia.","Providencia y deberá efectuarse antes de la sentencia.","Providencia y deberá efectuarse junto con la sentencia.","Auto y deberá efectuarse antes de la vista de las partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Auto y deberá efectuarse antes de la sentencia.</mark></span><span class=\"ref-norma\">Art. 5.3 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 5.3 LJCA."},{"i":"13-332","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Se entenderá a estos efectos por Administraciones públicas: señale la INCORRECTA.","o":["Entidades de derecho privado dependientes o no del Estado, de las Comunidades Autónomas o Entidades Locales.","Las Entidades que integran la Administración local.","Las Administraciones de las Comunidades Autónomas.","La Administración General del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Entidades de derecho privado dependientes o no del Estado, de las Comunidades Autónomas o Entidades Locales.</mark></span><span class=\"ref-norma\">Art. 1.2 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 1.2 LJCA, que habla de Entidades de Derecho PÚBLICO dependientes o vinculadas, no de Derecho privado."},{"i":"13-336","p":"Los JUZGADOS DE LO CONTENCIOSO-ADMINISTRATIVO conocerán asimismo, en única o primera instancia de los recursos que se deduzcan frente a los actos administrativos de la Administración de las comunidades autónomas, salvo cuando procedan del respectivo Consejo de Gobierno, cuando tengan por objeto las sanciones administrativas que consistan en multas no superiores a _____________ euros o en ceses de actividades o privación de ejercicio de derechos que no excedan de seis meses.","o":["30.000 euros.","60.000 euros.","90.000 euros.","600.000 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">60.000 euros.</mark></span><span class=\"ref-norma\">Art. 8.2.b) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 8.2.b) LJCA."},{"i":"13-338","p":"¿Qué órgano conocerá de las resoluciones dictadas por el Tribunal Administrativo Central de Recursos Contractuales?","o":["Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","Los Juzgados Centrales de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de la Audiencia Nacional.</mark></span><span class=\"ref-norma\">Art. 11.1.f) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 11.1.f) LJCA."},{"i":"13-339","p":"Están legitimados ante el orden jurisdiccional contencioso-administrativo: señale la INCORRECTA.","o":["Las corporaciones, asociaciones, sindicatos y grupos y entidades a que se refieren la ley que resulten afectados o estén legalmente habilitados para la defensa de los derechos e intereses legítimos colectivos.","La Administración del Estado, cuando ostente un derecho o interés legítimo, para impugnar los actos y disposiciones de la Administración de las Comunidades Autónomas y de los Organismos públicos vinculados a éstas, así como los de las Entidades locales, de conformidad con lo dispuesto en la legislación de régimen local, y los de cualquier otra entidad pública no sometida a su fiscalización.","La Administración de las Comunidades Autónomas, para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de la Administración del Estado y de cualquier otra Administración u Organismo público, así como los de las Entidades locales, de conformidad con lo dispuesto en la legislación de régimen local.","Las personas físicas o jurídicas que ostenten un derecho o interés ilegítimo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las personas físicas o jurídicas que ostenten un derecho o interés ilegítimo.</mark></span><span class=\"ref-norma\">Art. 19.1.a) · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 19.1.a) LJCA, que exige ostentar un derecho o interés legítimo, no ilegítimo."},{"i":"13-340","p":"Ámbito. La Jurisdicción Contencioso-Administrativa se entenderá a estos efectos por Administraciones públicas, entre otros:","o":["La Administración General del Estado.","Las Administraciones de las Comunidades Autónomas.","Las Entidades de Derecho público que sean dependientes o estén vinculadas al Estado, las Comunidades Autónomas o las Entidades locales.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 1.2 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 1.2 LJCA."},{"i":"13-343","p":"Sentencia. La Sentencia _____________ el recurso cuando se ajusten a Derecho la disposición, acto o actuación impugnados.","o":["No admitirá.","Rechazará.","Estimará.","Desestimará."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Desestimará.</mark></span><span class=\"ref-norma\">Art. 70 · Jurisdicción Contencioso-Administrativa</span> dispone: <span class=\"ref-concepto\">\"La sentencia desestimará el recurso cuando se ajusten a Derecho la disposición, acto o actuación impugnados.\"</span> De conformidad con el artículo 70.1 LJCA."},{"i":"13-346","p":"Procedimiento de amparo judicial de las libertades y derechos en el orden contencioso administrativo. Concluidas las actuaciones, el órgano jurisdiccional dictará sentencia:","o":["En el plazo de cinco días.","En el plazo de ocho días.","En el plazo de diez días.","En el plazo de quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo de cinco días.</mark></span><span class=\"ref-norma\">Art. 121.1 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 121.1 LJCA."},{"i":"13-349","p":"En los litigios sobre acoso sexual y acoso por razón de sexo estarán legitimados ante el orden jurisdiccional contencioso-administrativo:","o":["La persona acosada será la única legitimada.","Ministerio Fiscal.","La persona acosada y siempre con su autorización, los organismos públicos con competencia en la materia.","A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La persona acosada será la única legitimada.</mark></span><span class=\"ref-norma\">Art. 19.1 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 19.1 LJCA, que establece que la persona acosada será la única legitimada en los litigios sobre acoso sexual y acoso discriminatorio."},{"i":"13-351","p":"Procedimientos especiales. Una vez que se interponga el escrito de interposición del recurso de amparo judicial, ¿en qué plazo efectuará el requerimiento el Secretario Judicial al órgano administrativo correspondiente para que remita el expediente acompañado de los informes y datos que estime procedentes?","o":["En el mismo día de la presentación del recurso.","En los tres días siguientes a la presentación del recurso.","En el mismo día de la presentación del recurso o en el siguiente.","En los cinco días siguientes a la presentación del recurso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el mismo día de la presentación del recurso o en el siguiente.</mark></span><span class=\"ref-norma\">Art. 116.1 · Jurisdicción Contencioso-Administrativa</span>. De conformidad con el artículo 116.1 LJCA."}]},{"a":"De los Procedimientos Especiales","q":[{"i":"13-56","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Actividad administrativa impugnable. Cuestión de ilegalidad. Cuando un Juez o Tribunal de lo Contencioso-administrativo hubiera dictado sentencia firme estimatoria por considerar ilegal el contenido de la disposición general aplicada: ¿Ante quién se deberá plantear la cuestión de ilegalidad?","o":["Ante el Tribunal competente para conocer del recurso directo contra la disposición.","Ante el Tribunal que haya conocido la actuación contraria a la disposición.","Ante el órgano contencioso-administrativo del Tribunal que haya conocido la resolución contraria a la disposición.","Ante el Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ante el Tribunal competente para conocer del recurso directo contra la disposición</mark></span><span class=\"ref-norma\">Art. 123.1 · De los Procedimientos Especiales</span>. Fundamento: El artículo 123.1 de la LJCA establece que la cuestión de ilegalidad debe plantearse ante el Tribunal competente para conocer del recurso directo contra aquélla (la disposición general)."},{"i":"13-84","p":"Contencioso-administrativa. Actividad administrativa impugnable. Un acto fundado en la invalidez de una disposición general (a través del recurso indirecto). ¿Qué hace el Juez o Tribunal competente para conocer de un recurso contra un acto fundado en la invalidez de una disposición general cuando lo es también para conocer del recurso directo contra ésta?","o":["Elevará informe al Tribunal del que dependa, hasta la anulación o la limitación de la competencia.","La sentencia declarará la validez o nulidad de la disposición general.","Elevará informe al Tribunal Constitucional para que adopte la resolución que estime oportuna.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La sentencia declarará la validez o nulidad de la disposición general</mark></span>Según el <span class=\"ref-norma\">art. 27.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Cuando el Juez o Tribunal competente para conocer de un recurso contra un acto fundado en la invalidez de una disposición general lo fuere también para conocer del recurso directo contra ésta, la sentencia declarará la validez o nulidad de la disposición general.\"</span> (verificado con el texto del temario)."},{"i":"13-163","p":"Contencioso-Administrativa. Cuando la Administración no ejecute actos firmes podrán los afectados solicitar su ejecución, y si ésta no se produce en el plazo de convenido, podrán los solicitantes formular recurso contencioso-administrativo, que se tramitará","o":["Por procedimiento ordinario.","Por procedimiento preferente.","Por procedimiento abreviado.","Por procedimiento extraordinario."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por procedimiento abreviado</mark></span><span class=\"ref-norma\">Art. 29.2 · De los Procedimientos Especiales</span>. Fundamento: El recurso contra la inactividad de la Administración en la ejecución de actos firmes (art. 29.2 LJCA), si se presenta, se tramitará por el procedimiento abreviado según el artículo 78.1 de la LJCA."},{"i":"13-203","p":"Jurisdicción contencioso administrativa. Procedimientos especiales. Procedimiento para la protección de los derechos fundamentales de la persona. Cuando la lesión del derecho fundamental tuviera su origen en la inactividad administrativa, o se hubiera interpuesto potestativamente un recurso administrativo, el plazo de diez días será iniciado: Señale la CORRECTA.","o":["Transcurridos diez días desde la reclamación o la presentación del recurso.","Transcurridos veinte días desde la reclamación o la presentación del recurso.","Transcurridos treinta días desde la reclamación o la presentación del recurso.","Todos son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Transcurridos veinte días desde la reclamación o la presentación del recurso</mark></span>Según el <span class=\"ref-norma\">art. 115.1 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...el plazo de diez días se iniciará transcurridos veinte días desde la reclamación, la presentación del recurso o el inicio de la actuación administrativa en vía de hecho, respectivamente.\"</span> (verificado con el texto del temario)."},{"i":"13-210","p":"Jurisdicción contencioso administrativa. Procedimiento para la protección de los derechos fundamentales de la persona. Derecho de Reunión. El Secretario judicial, ________________ y poniendo de manifiesto el expediente si se hubiera recibido, convocará al representante legal de la Administración, al Ministerio Fiscal y a los recurrentes o a la persona que éstos designen como representante a una audiencia en la que el Tribunal, de manera contradictoria, oirá a todos los personados y resolverá sin ulterior recurso.","o":["En el plazo improrrogable de cinco días.","En el plazo improrrogable de cuatro días.","En el plazo improrrogable de seis días.","En el plazo improrrogable de ocho días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el plazo improrrogable de cuatro días</mark></span><span class=\"ref-norma\">Art. 122.2 · De los Procedimientos Especiales</span>. Fundamento: El artículo 122.2 de la LJCA, referente al procedimiento para la protección del derecho de reunión, establece que el Letrado de la Administración de Justicia (anteriormente Secretario judicial) convocará la audiencia en el plazo improrrogable de cuatro días."},{"i":"13-227","p":"Jurisdicción Contencioso-administrativa. Sin necesidad de plantear cuestión de ilegalidad, _________ anulará cualquier disposición general cuando, en cualquier grado, conozca de un recurso contra un acto fundado en la ilegalidad de aquella norma.","o":["La Audiencia Nacional.","El Tribunal Supremo.","El Tribunal Constitucional.","El Tribunal Superior de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Tribunal Supremo</mark></span>Según el <span class=\"ref-norma\">art. 27.3 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"Sin necesidad de plantear cuestión de ilegalidad, el Tribunal Supremo anulará cualquier disposición general cuando, en cualquier grado, conozca de un recurso contra un acto fundado en la ilegalidad de aquella norma.\"</span> (verificado con el texto del temario)."},{"i":"13-229","p":"Jurisdicción Contencioso-administrativa. Procedimiento para la protección de los derechos fundamentales de la persona. El letrado o letrada de la Administración de Justicia, en el plazo improrrogable de ________________ y haciendo entrega del expediente si se hubiera recibido, convocará al representante legal de la Administración, al Ministerio Fiscal y a los recurrentes o a la persona que éstos designen como representante a una audiencia en la que el tribunal oirá a todos los personados y resolverá sin ulterior recurso.","o":["Dos días.","Tres días.","Cuatro días.","Ocho días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuatro días</mark></span>Según el <span class=\"ref-norma\">art. 122.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El letrado o letrada de la Administración de Justicia, en el plazo improrrogable de cuatro días, y haciendo entrega del expediente si se hubiera recibido, convocará al representante legal de la Administración, al Ministerio Fiscal y a los recurrentes o a la persona que éstos designen como representante a una audiencia...\"</span> (verificado con el texto del temario)."},{"i":"13-240","p":": Procedimiento para la protección de los derechos fundamentales de la persona. El período probatorio no será en ningún caso superior a","o":["Siete días comunes para su proposición y práctica.","Diez días comunes para su proposición y práctica.","Veinte días comunes para su proposición y práctica.","Quince días comunes para su proposición y práctica."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días comunes para su proposición y práctica.</mark></span><span class=\"ref-norma\">Art. 120 · De los Procedimientos Especiales</span>. El artículo 120 de la LJCA dispone que el período probatorio \"no será en ningún caso superior a veinte días comunes para su proposición y práctica\"."},{"i":"13-264","p":"Jurisdicción Contencioso-administrativa. Procedimientos especiales. El letrado o letrada de la Administración de Justicia, y haciendo entrega del expediente si se hubiera recibido, convocará al representante legal de la Administración, al Ministerio Fiscal y a los recurrentes o a la persona que éstos designen como representante a una audiencia en la que el tribunal, de manera contradictoria, oirá a todos los personados y resolverá sin ulterior recurso.","o":["En el plazo improrrogable de dos días.","En el plazo improrrogable de tres días.","En el plazo improrrogable de cuatro días.","En el plazo improrrogable de cinco días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el plazo improrrogable de cuatro días</mark></span>Según el <span class=\"ref-norma\">art. 122.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"El letrado o letrada de la Administración de Justicia, en el plazo improrrogable de cuatro días, y haciendo entrega del expediente si se hubiera recibido, convocará al representante legal de la Administración, al Ministerio Fiscal y a los recurrentes o a la persona que éstos designen como representante a una audiencia...\"</span> (verificado con el texto del temario)."},{"i":"13-288","p":"Ley reguladora de la jurisdicción contencioso-administrativa. Actividad administrativa impugnable. Cuestión de ilegalidad. Cuando un Juez o Tribunal de lo Contencioso-administrativo hubiera dictado sentencia firme estimatoria por considerar ilegal el contenido de la disposición general aplicada: ¿Ante quién se deberá plantear la cuestión de ilegalidad?","o":["Ante el Tribunal competente para conocer del recurso directo contra la disposición.","Ante el Tribunal que haya conocido la actuación contraria a la disposición.","Ante el órgano contencioso-administrativo del Tribunal que haya conocido la resolución contraria a la disposición.","Ante el Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ante el Tribunal competente para conocer del recurso directo contra la disposición.</mark></span><span class=\"ref-norma\">Art. 27 · De los Procedimientos Especiales</span> dispone: <span class=\"ref-concepto\">\"Cuando un Juez o Tribunal de lo Contencioso-administrativo hubiere dictado sentencia firme estimatoria por considerar ilegal el contenido de la disposición general aplicada, deberá plantear la cuestión de ilegalidad ante el Tribunal competente para conocer del recurso directo contra la disposición, salvo lo dispuesto en los dos apartados siguientes.\"</span> De conformidad con el artículo 27.1 LJCA."},{"i":"13-337","p":"Procedimiento para la protección de los derechos fundamentales de la persona. El período probatorio no será en ningún caso superior a:","o":["Siete días comunes para su proposición y práctica.","Diez días comunes para su proposición y práctica.","Veinte días comunes para su proposición y práctica.","Quince días comunes para su proposición y práctica."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte días comunes para su proposición y práctica.</mark></span><span class=\"ref-norma\">Art. 120 · De los Procedimientos Especiales</span>. De conformidad con el artículo 120 LJCA."},{"i":"13-ia-7","p":"Ley 29/1998, art. 121.1. En el procedimiento para la protección de los derechos fundamentales, conclusas las actuaciones, ¿en qué plazo dictará sentencia el órgano jurisdiccional?","o":["Diez días.","Cinco días.","Veinte días.","Ocho días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cinco días</mark></span>El <span class=\"ref-norma\">art. 121.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Conclusas las actuaciones, el órgano jurisdiccional dictará sentencia en el plazo de cinco días.\"</span>. Por qué fallan las otras: los diez días son el plazo del procedimiento ordinario (art. 67.1); el ocho es el de la demanda y alegaciones (arts. 118 y 119). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-27","p":"Ley 29/1998, art. 116.4. La falta de envío del expediente administrativo dentro del plazo previsto en el procedimiento de protección de los derechos fundamentales:","o":["Suspenderá el curso de los autos hasta su recepción.","Determinará el archivo del recurso.","No suspenderá el curso de los autos.","Obligará a declarar la inadmisión del procedimiento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No suspenderá el curso de los autos</mark></span>El <span class=\"ref-norma\">art. 116.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La falta de envío del expediente administrativo dentro del plazo previsto en el apartado anterior no suspenderá el curso de los autos.\"</span>. Por qué fallan las otras: el carácter preferente y urgente del procedimiento impide la suspensión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-28","p":"Ley 29/1998, art. 122.3. En el recurso contra la prohibición o propuesta de modificación de reuniones (Ley Orgánica reguladora del Derecho de Reunión), ¿qué podrá hacer únicamente la decisión que se adopte?","o":["Mantener o revocar la prohibición o las modificaciones propuestas.","Modificar libremente las condiciones de la reunión.","Imponer sanciones a los promotores de la reunión.","Declarar la nulidad de la Ley Orgánica reguladora del Derecho de Reunión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mantener o revocar la prohibición o las modificaciones propuestas</mark></span>El <span class=\"ref-norma\">art. 122.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La decisión que se adopte únicamente podrá mantener o revocar la prohibición o las modificaciones propuestas.\"</span>. Por qué fallan las otras: el tribunal no puede crear una modificación distinta: solo mantiene o revoca. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-29","p":"Ley 29/1998, art. 122 bis.1. En el procedimiento de autorización judicial del art. 8.2 de la Ley 34/2002 (servicios de la sociedad de la información), ¿en qué plazo dictará resolución el Juzgado desde la petición, previa audiencia del Ministerio Fiscal?","o":["En las 48 horas siguientes a la petición.","En el plazo de dos días hábiles.","En las 24 horas siguientes a la petición.","En el plazo de cinco días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En las 24 horas siguientes a la petición</mark></span>El <span class=\"ref-norma\">art. 122 bis.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El Juzgado, en el plazo de 24 horas siguientes a la petición y, previa audiencia del Ministerio Fiscal, dictará resolución autorizando la solicitud efectuada siempre que no resulte afectado el artículo 18 apartados 1 y 3 de la Constitución.\"</span>. Por qué fallan las otras: las 48 horas son el plazo del recurso del Derecho de Reunión (art. 122.1) y los dos días son los del art. 122 bis.2. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-39","p":"Ley 29/1998, art. 116.5. Cuando el expediente administrativo se reciba en el juzgado o Sala una vez transcurrido el plazo de cinco días (procedimiento de derechos fundamentales), el letrado de la Administración de Justicia lo entregará a las partes por plazo de:","o":["Cinco días, con suspensión del curso del procedimiento.","Veinticuatro horas, con suspensión del curso del procedimiento.","Cuarenta y ocho horas, en el que podrán hacer alegaciones, sin alteración del curso del procedimiento.","Tres días, sin alteración del curso del procedimiento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuarenta y ocho horas, en el que podrán hacer alegaciones, sin alteración del curso del procedimiento</mark></span>El <span class=\"ref-norma\">art. 116.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Cuando el expediente administrativo se recibiese en el juzgado o Sala una vez transcurrido el plazo establecido en el apartado 1, el letrado o letrada de la Administración de Justicia lo entregará a las partes por plazo de cuarenta y ocho horas, en el que podrán hacer alegaciones, y sin alteración del curso del procedimiento.\"</span>. Por qué fallan las otras: el curso de los autos no se altera (art. 116.4). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-40","p":"Ley 29/1998, art. 117.2. Ante posibles motivos de inadmisión del procedimiento de derechos fundamentales, el Secretario judicial convocará a las partes y al Ministerio Fiscal a una comparecencia que habrá de tener lugar:","o":["Antes de transcurrir tres días.","Dentro de los diez días siguientes.","En el mismo día de la presentación del recurso.","Antes de transcurrir cinco días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Antes de transcurrir cinco días</mark></span>El <span class=\"ref-norma\">art. 117.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En el supuesto de posibles motivos de inadmisión del procedimiento, el Secretario judicial convocará a las partes y al Ministerio Fiscal a una comparecencia, que habrá de tener lugar antes de transcurrir cinco días, en la que se les oirá sobre la procedencia de dar al recurso la tramitación prevista en este capítulo.\"</span>. Por qué fallan las otras: tras la comparecencia, el órgano dicta auto «en el siguiente día» (art. 117.3). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-41","p":"Ley 29/1998, art. 122 ter.7. Finalizados los trámites del procedimiento de autorización judicial de conformidad de una decisión de la Comisión Europea sobre transferencia internacional de datos, si el Tribunal considera que la decisión es contraria al Derecho de la Unión Europea, en el plazo de diez días:","o":["Dictará auto de planteamiento de cuestión prejudicial de validez de la decisión ante el Tribunal de Justicia de la Unión Europea.","Dictará sentencia concediendo directamente la autorización solicitada, sin más trámite.","Dictará sentencia anulando la decisión de la Comisión Europea por ser contraria al Derecho de la Unión.","Remitirá las actuaciones a la autoridad de protección de datos para que sea ella quien decida."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dictará auto de planteamiento de cuestión prejudicial de validez de la decisión ante el Tribunal de Justicia de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 122 ter.7 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En caso de considerar que la decisión es contraria al Derecho de la Unión Europea, dictará auto de planteamiento de cuestión prejudicial de validez de la citada decisión ante el Tribunal de Justicia de la Unión Europea, en los términos del artículo 267 del Tratado de Funcionamiento de la Unión Europea. La autorización solamente podrá ser concedida si la decisión de la Comisión Europea cuestionada fuera declarada inválida por el Tribunal de Justicia de la Unión Europea.\"</span>. Por qué fallan las otras: el tribunal nacional no puede anular la decisión europea: solo plantea la cuestión prejudicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-68","p":"Ley 29/1998, art. 116.2. En el procedimiento de protección de derechos fundamentales, al remitir el expediente el órgano administrativo lo comunicará a todos los que aparezcan como interesados, emplazándoles para que puedan comparecer como demandados ante el Juzgado o Sala en el plazo de:","o":["Tres días.","Diez días.","Veinte días.","Cinco días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco días</mark></span>El <span class=\"ref-norma\">art. 116.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Al remitir el expediente, el órgano administrativo lo comunicará a todos los que aparezcan como interesados en el mismo, acompañando copia del escrito de interposición y emplazándoles para que puedan comparecer como demandados ante el Juzgado o Sala en el plazo de cinco días\"</span>. Por qué fallan las otras: el emplazamiento a los interesados es de cinco días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-69","p":"Ley 29/1998, art. 115.1. En el procedimiento para la protección de los derechos fundamentales de la persona, el plazo para interponer el recurso será de:","o":["Dos meses.","Veinte días.","Cinco días.","Diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 115.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer este recurso será de diez días, que se computarán, según los casos, desde el día siguiente al de notificación del acto, publicación de la disposición impugnada, requerimiento para el cese de la vía de hecho, o transcurso del plazo fijado para la resolución, sin más trámites\"</span>. Por qué fallan las otras: el plazo ordinario es de dos meses (art. 46); en este procedimiento especial son diez días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-74","p":"Ley 29/1998, art. 116.1. En el procedimiento de protección de derechos fundamentales, el órgano administrativo requerido debe remitir el expediente administrativo en soporte electrónico en el plazo máximo de, a contar desde la recepción del requerimiento:","o":["Cinco días.","Veinte días.","Diez días.","Cuarenta y ocho horas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cinco días</mark></span>El <span class=\"ref-norma\">art. 116.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"para que en el plazo máximo de cinco días a contar desde la recepción del requerimiento remita el expediente administrativo en soporte electrónico\"</span>. Por qué fallan las otras: el plazo general del art. 48.3 es de veinte días improrrogables; aquí se reduce a cinco. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-75","p":"Ley 29/1998, art. 116.3. En el procedimiento de protección de derechos fundamentales, la Administración con el envío del expediente, y los demás demandados al comparecer, podrán solicitar razonadamente:","o":["La suspensión cautelar del acto impugnado y la prestación de caución.","El recibimiento a prueba y la celebración de vista.","La acumulación del recurso a otros pendientes y la declaración de preferencia.","La inadmisión del recurso y la celebración de la comparecencia a que se refiere el art. 117.2."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La inadmisión del recurso y la celebración de la comparecencia a que se refiere el art. 117.2</mark></span>El <span class=\"ref-norma\">art. 116.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La Administración, con el envío del expediente, y los demás demandados, al comparecer, podrán solicitar razonadamente la inadmisión del recurso y la celebración de la comparecencia a que se refiere el artículo 117.2\"</span>. Por qué fallan las otras: pueden pedir la inadmisión y la comparecencia del art. 117.2. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-77","p":"Ley 29/1998, art. 122 ter.4. En el procedimiento de autorización judicial de conformidad de una decisión de la Comisión Europea en materia de transferencia internacional de datos, admitida a trámite la solicitud, quienes intervinieron en el procedimiento ante la autoridad de protección de datos se personarán en el plazo de:","o":["Cinco días.","Diez días.","Quince días.","Tres días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tres días</mark></span>El <span class=\"ref-norma\">art. 122 ter.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Admitida a trámite la solicitud, el Tribunal competente lo notificará a la autoridad de protección de datos a fin de que dé traslado a quienes interviniesen en el procedimiento tramitado ante la misma para que se personen en el plazo de tres días\"</span>. Por qué fallan las otras: el plazo de personación es de tres días; las alegaciones posteriores son de diez (art. 122 ter.5). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-80","p":"Ley 29/1998, art. 122 bis.2. En la autorización judicial para ejecutar las medidas de la Sección Segunda de la Comisión de Propiedad Intelectual, en el plazo improrrogable de ___ siguientes a la recepción de la notificación de la resolución de la Comisión, el Juzgado dará traslado de ésta para alegaciones.","o":["Dos días.","Cinco días.","Veinticuatro horas.","Diez días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos días</mark></span>El <span class=\"ref-norma\">art. 122 bis.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En el plazo improrrogable de dos días siguientes a la recepción de la notificación de la resolución de la Comisión y poniendo de manifiesto el expediente, el Juzgado dará traslado de la resolución de la Comisión al representante legal de la Administración, al del Ministerio Fiscal y a los titulares de los derechos y libertades afectados ... para que puedan efectuar alegaciones escritas por plazo común de cinco días\"</span>. Por qué fallan las otras: dos días improrrogables para el traslado y cinco días comunes para alegar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-81","p":"Ley 29/1998, art. 122 ter.5. En el procedimiento de autorización judicial de conformidad de una decisión de la Comisión Europea en materia de transferencia internacional de datos, concluido el plazo de personación, se da traslado de la solicitud a las partes personadas para que aleguen lo que estimen procedente en el plazo de:","o":["Tres días.","Diez días.","Cinco días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 122 ter.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Concluido el plazo mencionado en la letra anterior, se dará traslado de la solicitud de autorización a las partes personadas a fin de que en el plazo de diez días aleguen lo que estimen procedente, pudiendo solicitar en ese momento la práctica de las pruebas que estimen necesarias\"</span>. Por qué fallan las otras: tres días es el plazo de personación (apartado 4); las alegaciones son diez días y en ese momento pueden pedir prueba. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-83","p":"Ley 29/1998, art. 117.1. Recibido el expediente administrativo en el procedimiento de protección de derechos fundamentales, o transcurrido el plazo para su remisión y el del emplazamiento a los demás interesados, el letrado de la Administración de Justicia dictará decreto mandando seguir las actuaciones:","o":["Dentro de los cinco días siguientes.","Dentro de los tres días siguientes.","Dentro del siguiente día.","Dentro de los ocho días siguientes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dentro del siguiente día</mark></span>El <span class=\"ref-norma\">art. 117.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Recibido el expediente o transcurrido el plazo para su remisión y, en su caso, el del emplazamiento a los demás interesados, el Secretario judicial, dentro del siguiente día, dictará decreto mandando seguir las actuaciones\"</span>. Por qué fallan las otras: es un trámite de urgencia: decreto dentro del siguiente día. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-99","p":"Ley 29/1998, art. 121.3. Contra las sentencias de los Juzgados de lo Contencioso-administrativo dictadas en el procedimiento para la protección de los derechos fundamentales:","o":["Procederá la apelación en ambos efectos.","No cabrá recurso alguno.","Procederá siempre la apelación en un solo efecto.","Procederá la apelación solo si la cuantía excede de 30.050 euros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Procederá siempre la apelación en un solo efecto</mark></span>El <span class=\"ref-norma\">art. 121.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Contra las sentencias de los Juzgados de lo Contencioso-administrativo procederá siempre la apelación en un solo efecto\"</span>. Por qué fallan las otras: la apelación siempre procede y lo hace en un solo efecto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-100","p":"Ley 29/1998, art. 122.2. En el recurso contra la prohibición o propuesta de modificación de reuniones, ¿en qué plazo improrrogable convoca el letrado de la Administración de Justicia a la audiencia, y cómo resuelve el tribunal?","o":["En diez días, y el tribunal resuelve con recurso de apelación.","En cuatro días, y el tribunal resuelve sin ulterior recurso.","En veinticuatro horas, y el tribunal resuelve con recurso de reposición.","En cinco días, y el tribunal resuelve con recurso de apelación en un solo efecto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En cuatro días, y el tribunal resuelve sin ulterior recurso</mark></span>El <span class=\"ref-norma\">art. 122.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El letrado o letrada de la Administración de Justicia, en el plazo improrrogable de cuatro días, ... convocará al representante legal de la Administración, al Ministerio Fiscal y a los recurrentes ... a una audiencia en la que el tribunal, de manera contradictoria, oirá a todos los personados y resolverá sin ulterior recurso\"</span>. Por qué fallan las otras: cuatro días improrrogables y resolución sin ulterior recurso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-132","p":"Ley 29/1998, art. 122 ter.2. En el procedimiento de autorización judicial de conformidad de una decisión de la Comisión Europea en materia de transferencia internacional de datos, ¿quiénes serán partes además de la autoridad de protección de datos?","o":["Únicamente quienes lo fueran en el procedimiento ante la autoridad de protección de datos.","El Ministerio Fiscal y el Defensor del Pueblo.","Quienes lo fueran en el procedimiento tramitado ante ella y, en todo caso, la Comisión Europea.","Los Estados miembros de la Unión Europea afectados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Quienes lo fueran en el procedimiento tramitado ante ella y, en todo caso, la Comisión Europea</mark></span>El <span class=\"ref-norma\">art. 122 ter.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Serán partes en el procedimiento, además de la autoridad de protección de datos, quienes lo fueran en el procedimiento tramitado ante ella y, en todo caso, la Comisión Europea\"</span>. Por qué fallan las otras: la Comisión Europea es siempre parte, junto con quienes lo fueran ante la autoridad de protección de datos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-136","p":"Ley 29/1998, art. 115.2. En el procedimiento de protección de los derechos fundamentales, el escrito de interposición expresará:","o":["Con precisión y claridad el derecho o derechos cuya tutela se pretende y, de manera concisa, los argumentos sustanciales que den fundamento al recurso.","Únicamente el acto impugnado, sin referencia a los derechos invocados.","Los fundamentos de derecho completos y la propuesta de prueba.","Solo la cuantía del recurso y la Administración demandada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con precisión y claridad el derecho o derechos cuya tutela se pretende y, de manera concisa, los argumentos sustanciales que den fundamento al recurso</mark></span>El <span class=\"ref-norma\">art. 115.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En el escrito de interposición se expresará con precisión y claridad el derecho o derechos cuya tutela se pretende y, de manera concisa, los argumentos sustanciales que den fundamento al recurso\"</span>. Por qué fallan las otras: debe precisar el derecho cuya tutela se pide y dar, de forma concisa, los argumentos sustanciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-137","p":"Ley 29/1998, art. 122 ter.3. En el procedimiento de autorización judicial de conformidad de una decisión de la Comisión Europea en materia de transferencia internacional de datos, el acuerdo de admisión o inadmisión a trámite:","o":["Confirmará, modificará o levantará la suspensión del procedimiento tramitado ante la autoridad de protección de datos.","Pondrá fin al procedimiento ante la autoridad de protección de datos.","Suspenderá automáticamente el procedimiento ante la autoridad de protección de datos.","No producirá efecto alguno sobre el procedimiento ante la autoridad de protección de datos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Confirmará, modificará o levantará la suspensión del procedimiento tramitado ante la autoridad de protección de datos</mark></span>El <span class=\"ref-norma\">art. 122 ter.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El acuerdo de admisión o inadmisión a trámite del procedimiento confirmará, modificará o levantará la suspensión del procedimiento por posible vulneración de la normativa de protección de datos tramitado ante la autoridad de protección de datos, del que trae causa este procedimiento de autorización judicial\"</span>. Por qué fallan las otras: incide sobre la suspensión del procedimiento previo: la confirma, modifica o levanta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-138","p":"Ley 29/1998, art. 122 ter.6. En el procedimiento de autorización judicial de conformidad de una decisión de la Comisión Europea, transcurrido el período de prueba, ¿cuándo se celebrará una vista?","o":["Si alguna de las partes lo hubiese solicitado y el órgano jurisdiccional lo estimase pertinente.","Siempre, de oficio.","Solo si lo solicita la Comisión Europea.","Solo si lo solicita la autoridad de protección de datos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Si alguna de las partes lo hubiese solicitado y el órgano jurisdiccional lo estimase pertinente</mark></span>El <span class=\"ref-norma\">art. 122 ter.6 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Transcurrido el período de prueba, si alguna de las partes lo hubiese solicitado y el órgano jurisdiccional lo estimase pertinente, se celebrará una vista\"</span>. Por qué fallan las otras: exige solicitud de parte y valoración de pertinencia del tribunal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"}]},{"a":"De las Partes","q":[{"i":"13-75","p":"Contencioso-administrativa. Están legitimados ante el orden jurisdiccional contencioso-administrativo: Señale la incorrecta.","o":["El Ministerio Fiscal en los procesos en que estime oportuno.","La Administración del Estado, cuando ostentando un derecho o interés legítimo, para impugnar los actos y disposiciones de la Administración de las demás Comunidades Autónomas y de los Organismos Públicos vinculados a éstas, así como los de las Entidades locales.","Las Entidades locales territoriales para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de las Administraciones del Estado y de las Comunidades Autónomas, así como los de Organismos públicos con personalidad jurídica vinculados a éstas y otros de los de otras Entidades locales.","Cualesquiera ciudadanos, en ejercicio de la acción popular, en los casos expresamente previstos por las Leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal en los procesos en que estime oportuno</mark></span><span class=\"ref-norma\">Art. 19.1.h) · De las Partes</span>. Fundamento: *Explicación:* La opción a) es la incorrecta por su redacción. El artículo 19.1.h) de la LJCA legitima al Ministerio Fiscal, pero solo \"para intervenir en los procesos que determine la ley\", no en aquellos que \"estime oportuno\", lo que confiere la legitimación en base a un mandato legal y no a una simple apreciación."},{"i":"13-76","p":"Contencioso-administrativa. Legitimación. No pueden interponer recurso contencioso-administrativo contra la actividad de una Administración pública","o":["Los órganos de la misma y los miembros de sus órganos colegiados, salvo que una Ley lo autorice expresamente.","Los particulares cuando obren por delegación o como meros agentes o mandatarios de ella.","Las entidades de Derecho público que estén dependientes o vinculadas al Estado, las Comunidades Autónomas o las Entidades locales, respecto de la actividad de la Administración de la que dependan. Se exceptúan aquéllos a los que por Ley se haya dotado de un estatuto específico de autonomía respecto de dicha Administración.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 20 · De las Partes</span>. Fundamento: *Explicación:* Los supuestos descritos en las opciones a), b) y c) son exactamente los establecidos en el artículo 20 de la LJCA como supuestos de limitación de la legitimación (o prohibición de recurrir). Por lo tanto, todas son correctas."},{"i":"13-127","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Las partes. Legitimación. Respecto a las partes demandadas, ¿quién será considerada parte codemandada junto con la Administración?","o":["Las personas o entidades cuyos derechos o intereses legítimos pudieran quedar afectados por la estimación de las pretensiones del demandante.","Las corporaciones de las Administraciones públicas.","El órgano que dictó el acto o disposición impugnable.","Todos son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las personas o entidades cuyos derechos o intereses legítimos pudieran quedar afectados por la estimación d...</mark></span><span class=\"ref-norma\">Art. 21.1.c) · De las Partes</span>. Fundamento: El artículo 21.1.c) de la LJCA establece que podrán ser parte codemandada las personas o entidades cuyos derechos o intereses legítimos pudieran quedar afectados por la estimación de las pretensiones del demandante."},{"i":"13-128","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Están legitimados ante el orden jurisdiccional contencioso- administrativo. Señale la INCORRECTA.","o":["Las personas físicas o jurídicas que ostenten un derecho o interés legítimo.","La Administración de las Comunidades Autónomas, para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de la Administración del Estado y de cualquier otra Administración u organismo público ajeno, así como de las Entidades locales, si una Ley lo dispone en la legislación de régimen local.","Las Entidades del Estado, para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de los Organismos Públicos del Estado y de las Comunidades Autónomas.","Las Entidades locales territoriales para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de Organismos públicos con personalidad jurídica propia vinculados a unos y otros o los de estos Entidades estatales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Entidades del Estado, para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, em...</mark></span><span class=\"ref-norma\">Art. 19.1 · De las Partes</span>. Fundamento: La opción (c) no se corresponde con la redacción del artículo 19.1 de la LJCA, que regula la legitimación activa de las Administraciones. La letra b) de dicho artículo se refiere a la Administración del Estado, de las CCAA y de las Entidades locales para impugnar actos de otras Administraciones (y sus organismos) que afecten a su autonomía. La opción (c) utiliza una terminología inexacta (\"Entidades del Estado\") y no refleja correctamente el alcance de la legitimación interadministrativa."},{"i":"13-135","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa. Legitimación. Señale la incorrecta.","o":["La Administración autora de un acto está legitimada para impugnar el acto ante este orden jurisdiccional, previa su declaración de lesividad para el interés público en los términos establecidos por la Ley.","El ejercicio de acciones por los vecinos en nombre o interés de las Entidades locales se regirá por lo dispuesto en la legislación de régimen local.","Las Administraciones públicas o los particulares podrán interponer recurso contencioso-administrativo contra las decisiones adoptadas por los órganos administrativos a los que corresponda resolver los recursos especiales y las reclamaciones en materia de contratación a que se refiere la legislación de Contratos del Sector Público, previo requisito, en el primer caso, de declaración de lesividad.","Tendrán legitimación para recurrir las resoluciones del Tribunal Administrativo del Deporte en asuntos de disciplina deportiva en materia de dopaje, todas las personas mencionadas en el artículo 40.4 de la Ley Orgánica de Protección de la Salud del Deportista y Lucha contra el Dopaje en la Actividad Deportiva."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Administraciones públicas o los particulares podrán interponer recurso contencioso-administrativo contr...</mark></span><span class=\"ref-norma\">Art. 19.1.h) · De las Partes</span>. Fundamento: El artículo 19.1.h) de la LJCA permite la interposición del recurso contra las resoluciones en materia de contratación sin que se exija el requisito de la declaración de lesividad para el primer caso mencionado. La declaración de lesividad solo es necesaria cuando la propia Administración autora del acto es la que lo impugna (Art. 19.3)."},{"i":"13-161","p":"Contencioso-Administrativa. En los litigios sobre acoso sexual y acoso discriminatorio, están legitimados ante el orden jurisdiccional contencioso- administrativo: I) El Ministerio Fiscal. II) La persona acosada. III) El Ministerio de Justicia. IV) El Fiscal General del Estado.","o":["I y III.","II y IV.","Solo II.","Todos son correctos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Solo II</mark></span>Según el <span class=\"ref-norma\">art. 19.1.i) de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"La persona acosada será la única legitimada en los litigios sobre acoso sexual y acoso discriminatorio.\"</span> (verificado con el texto del temario)."},{"i":"13-204","p":"Jurisdicción contencioso-administrativa. Legitimación. Si el demandante fundara sus pretensiones en la ilegalidad de una disposición general","o":["No es necesario que ostente un derecho o interés legítimo.","Es necesario que ostente un derecho o interés legítimo.","Podrá fundarlas en la ilegalidad de otra disposición general que sirva de fundamento a aquélla.","Las opciones b y c son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones b y c son correctas</mark></span><span class=\"ref-norma\">Art. 26.2 · De las Partes</span>. Fundamento: El artículo 26.2 de la LJCA establece que \"La interposición del recurso contencioso-administrativo es admisible no sólo contra la disposición de carácter general, sino también contra los actos que se produzcan en aplicación de las mismas. Si el demandante fundara sus pretensiones en la ilegalidad de una disposición general, será necesario que ostente un derecho o interés legítimo (opción b). Asimismo, podrá fundarlas en la ilegalidad de otra disposición general que sirva de fundamento a aquélla (opción c)\"."},{"i":"13-224","p":"Jurisdicción Contencioso-administrativa. Las partes. Capacidad procesal. Tienen capacidad procesal ante el orden jurisdiccional contencioso-administrativo","o":["Las personas que lo ostenten con arreglo a la Ley de Enjuiciamiento Civil.","Los menores de edad para la defensa de aquellos de sus derechos e intereses legítimos cuya actuación les esté permitida por el ordenamiento jurídico sin necesidad de asistencia de la persona que ejerza la patria potestad, tutela o curatela.","Los grupos de afectados, uniones sin personalidad o patrimonios independientes o autónomos, cuando la Ley así lo declare expresamente.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Fundamento: Las tres opciones describen supuestos en los que se ostenta capacidad procesal, de acuerdo con la Ley 29/1998 y remisión a la Ley de Enjuiciamiento Civil."},{"i":"13-226","p":"Jurisdicción Contencioso-administrativa. Las partes. Capacidad procesal. Tienen capacidad procesal ante el orden jurisdiccional contencioso-administrativo","o":["Las personas que lo ostenten con arreglo a la Ley de Enjuiciamiento Civil.","Los menores de edad para la defensa de aquellos de sus derechos e intereses legítimos cuya actuación les esté permitida por el ordenamiento jurídico sin necesidad de asistencia de la persona que ejerza la patria potestad, tutela o curatela.","Los grupos de afectados, uniones sin personalidad o patrimonios independientes o autónomos, cuando la Ley así lo declare expresamente.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Fundamento: Pregunta idéntica a la 8. Las tres opciones describen supuestos en los que se ostenta capacidad procesal."},{"i":"13-ia-2","p":"Ley 29/1998, art. 21.1.c). ¿Qué posición procesal tienen las aseguradoras de las Administraciones públicas?","o":["Podrán ser parte codemandada si la Administración asegurada lo solicita.","Solo serán parte codemandada si así lo acuerda el Juez de oficio.","Siempre serán parte codemandada junto con la Administración a quien aseguren.","Nunca serán parte, pues la responsabilidad es exclusiva de la Administración."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Siempre serán parte codemandada junto con la Administración a quien aseguren</mark></span>El <span class=\"ref-norma\">art. 21.1.c) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Se considera parte demandada: [...] c) Las aseguradoras de las Administraciones públicas, que siempre serán parte codemandada junto con la Administración a quien aseguren.\"</span>. Por qué fallan las otras: el texto dice «siempre»: no es potestativo ni depende del Juez. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-32","p":"Ley 29/1998, art. 19.1.k). ¿En qué condiciones están legitimados los sindicatos para actuar en defensa de los derechos individuales del personal funcionario y estatutario?","o":["En nombre e interés del personal afiliado que así lo autorice, recayendo sobre dichos afiliados los efectos de aquella actuación.","En nombre propio y sin necesidad de autorización de los afiliados, recayendo los efectos sobre el sindicato.","Solo cuando el Ministerio Fiscal lo solicite expresamente y lo autorice el órgano judicial.","En nombre de todo el personal funcionario y estatutario, esté o no afiliado a ellos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En nombre e interés del personal afiliado que así lo autorice, recayendo sobre dichos afiliados los efectos de aquella actuación</mark></span>El <span class=\"ref-norma\">art. 19.1.k) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Los sindicatos estarán también legitimados para actuar, en nombre e interés del personal funcionario y estatutario afiliado a ellos que así lo autorice, en defensa de sus derechos individuales, recayendo sobre dichos afiliados los efectos de aquella actuación.\"</span>. Por qué fallan las otras: se exige afiliación y autorización, y los efectos recaen sobre los afiliados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-33","p":"Ley 29/1998, art. 22. Si la legitimación de las partes derivare de alguna relación jurídica transmisible, ¿qué podrá hacer el causahabiente?","o":["Suceder en cualquier estado del proceso a la persona que inicialmente hubiere actuado como parte.","Suceder a la parte solo antes de la interposición del recurso.","Suceder a la parte únicamente si lo autoriza el Ministerio Fiscal.","Intervenir solo como coadyuvante, sin sustituir a la parte inicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Suceder en cualquier estado del proceso a la persona que inicialmente hubiere actuado como parte</mark></span>El <span class=\"ref-norma\">art. 22 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si la legitimación de las partes derivare de alguna relación jurídica transmisible, el causahabiente podrá suceder en cualquier estado del proceso a la persona que inicialmente hubiere actuado como parte.\"</span>. Por qué fallan las otras: la sucesión es posible en cualquier estado del proceso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-46","p":"Ley 29/1998, art. 21.3. En los recursos contra las decisiones de los órganos administrativos que resuelven los recursos especiales y las reclamaciones en materia de contratación, ¿qué consideración tienen esos órganos?","o":["Serán siempre parte demandada junto con la Administración contratante y las personas favorecidas por el acto.","No tendrán la consideración de parte demandada, siéndolo las personas o Administraciones favorecidas por el acto objeto del recurso.","Serán parte demandada únicamente si así lo solicita el recurrente en su escrito de interposición.","Serán parte coadyuvante de la Administración contratante, con derecho a formular alegaciones propias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No tendrán la consideración de parte demandada, siéndolo las personas o Administraciones favorecidas por el acto objeto del recurso</mark></span>El <span class=\"ref-norma\">art. 21.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En los recursos contra las decisiones adoptadas por los órganos administrativos a los que corresponde resolver los recursos especiales y las reclamaciones en materia de contratación [...] los citados órganos no tendrán la consideración de parte demandada, siéndolo las personas o Administraciones favorecidas por el acto objeto del recurso, o que se personen en tal concepto...\"</span>. Por qué fallan las otras: el órgano resolutor actúa como árbitro, no como parte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-47","p":"Ley 29/1998, art. 21.2. Cuando se trate de Organismos o Corporaciones públicos sujetos a fiscalización de una Administración territorial, ¿qué Administración se entiende demandada si mediante la fiscalización no se aprueba íntegramente el acto o disposición?","o":["El Organismo o Corporación autores del acto o disposición fiscalizados.","Ambas Administraciones, en litisconsorcio necesario.","La Administración General del Estado, en todo caso.","La que ejerza la fiscalización."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La que ejerza la fiscalización</mark></span>El <span class=\"ref-norma\">art. 21.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"...se entiende por Administración demandada: a) El Organismo o Corporación autores del acto o disposición fiscalizados, si el resultado de la fiscalización es aprobatorio. b) La que ejerza la fiscalización, si mediante ella no se aprueba íntegramente el acto o disposición.\"</span>. Por qué fallan las otras: si la fiscalización es aprobatoria, la demandada es el Organismo o Corporación autor del acto; si no lo aprueba íntegramente, la que fiscaliza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-82","p":"Ley 29/1998, art. 19.1.e). ¿Quién está legitimado para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de las Administraciones del Estado y de las Comunidades Autónomas?","o":["Cualquier ciudadano, en ejercicio de la acción popular.","Las Entidades locales territoriales.","Las Entidades de Derecho público dependientes de la Administración autora del acto.","El Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las Entidades locales territoriales</mark></span>El <span class=\"ref-norma\">art. 19.1.e) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Las Entidades locales territoriales, para impugnar los actos y disposiciones que afecten al ámbito de su autonomía, emanados de las Administraciones del Estado y de las Comunidades Autónomas, así como los de Organismos públicos con personalidad jurídica propia vinculados a una y otras o los de otras Entidades locales\"</span>. Por qué fallan las otras: la legitimación por razón de autonomía local corresponde a las Entidades locales territoriales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-84","p":"Ley 29/1998, art. 21.4. Si el demandante fundara sus pretensiones en la ilegalidad de una disposición general, ¿quién se considerará también parte demandada?","o":["La Administración autora de la disposición general, aunque no proceda de ella la actuación recurrida.","Únicamente la Administración autora del acto recurrido.","El Ministerio Fiscal, como defensor de la legalidad.","La Administración que ejerza la fiscalización de la disposición."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Administración autora de la disposición general, aunque no proceda de ella la actuación recurrida</mark></span>El <span class=\"ref-norma\">art. 21.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si el demandante fundara sus pretensiones en la ilegalidad de una disposición general, se considerará también parte demandada a la Administración autora de la misma, aunque no proceda de ella la actuación recurrida\"</span>. Por qué fallan las otras: también es demandada la Administración autora de la disposición general. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-85","p":"Ley 29/1998, art. 21.1.b). Además de las Administraciones públicas contra cuya actividad se dirija el recurso, ¿quiénes se consideran parte demandada?","o":["Las personas o entidades que hubieran intervenido en el procedimiento administrativo, aunque no resulten afectadas.","Las personas o entidades cuyos derechos o intereses legítimos pudieran quedar afectados por la estimación de las pretensiones del demandante.","Cualquier ciudadano que se persone en ejercicio de la acción popular.","El Ministerio Fiscal en todo caso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las personas o entidades cuyos derechos o intereses legítimos pudieran quedar afectados por la estimación de las pretensiones del demandante</mark></span>El <span class=\"ref-norma\">art. 21.1.b) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Las personas o entidades cuyos derechos o intereses legítimos pudieran quedar afectados por la estimación de las pretensiones del demandante\"</span>. Por qué fallan las otras: lo decisivo es que puedan resultar afectados por la estimación de las pretensiones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-87","p":"Ley 29/1998, art. 20.c). No pueden recurrir las Entidades de Derecho público dependientes o vinculadas al Estado, las Comunidades Autónomas o las Entidades locales, respecto de la actividad de la Administración de la que dependan. ¿Qué excepción prevé el precepto?","o":["Las que tengan personalidad jurídica propia.","Las que cuenten con autorización del órgano de tutela.","Aquellos a los que por Ley se haya dotado de un estatuto específico de autonomía respecto de dicha Administración.","Las entidades vinculadas a las Entidades locales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Aquellos a los que por Ley se haya dotado de un estatuto específico de autonomía respecto de dicha Administración</mark></span>El <span class=\"ref-norma\">art. 20.c) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Las Entidades de Derecho público que sean dependientes o estén vinculadas al Estado, las Comunidades Autónomas o las Entidades locales, respecto de la actividad de la Administración de la que dependan. Se exceptúan aquellos a los que por Ley se haya dotado de un estatuto específico de autonomía respecto de dicha Administración\"</span>. Por qué fallan las otras: la única excepción es el estatuto específico de autonomía otorgado por Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-103","p":"Ley 29/1998, art. 19.3. El ejercicio de acciones por los vecinos en nombre e interés de las Entidades locales se rige por:","o":["Lo dispuesto en la Ley de Enjuiciamiento Civil.","Lo dispuesto en la legislación de régimen local.","Lo dispuesto en la Ley Orgánica del Poder Judicial.","Lo dispuesto en la Ley de Asistencia Jurídica al Estado e Instituciones Públicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Lo dispuesto en la legislación de régimen local</mark></span>El <span class=\"ref-norma\">art. 19.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"El ejercicio de acciones por los vecinos en nombre e interés de las Entidades locales se rige por lo dispuesto en la legislación de régimen local\"</span>. Por qué fallan las otras: la remisión es a la legislación de régimen local. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-104","p":"Ley 29/1998, art. 24. La representación y defensa de las Administraciones públicas y de los órganos constitucionales se rige por lo dispuesto en:","o":["La Ley Orgánica del Poder Judicial y en la Ley de Asistencia Jurídica al Estado e Instituciones Públicas, así como en las normas autonómicas dictadas en el marco de sus competencias.","La Ley de Enjuiciamiento Civil y el Estatuto General de la Abogacía exclusivamente.","La Ley de Régimen Jurídico del Sector Público exclusivamente.","La Ley de Enjuiciamiento Criminal y la Ley Orgánica del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Ley Orgánica del Poder Judicial y en la Ley de Asistencia Jurídica al Estado e Instituciones Públicas, así como en las normas autonómicas dictadas en el marco de sus competencias</mark></span>El <span class=\"ref-norma\">art. 24 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"La representación y defensa de las Administraciones públicas y de los órganos constitucionales se rige por lo dispuesto en la Ley Orgánica del Poder Judicial y en la Ley de Asistencia Jurídica al Estado e Instituciones Públicas, así como en las normas que sobre la materia y en el marco de sus competencias hayan dictado las Comunidades Autónomas\"</span>. Por qué fallan las otras: las normas aplicables son la LOPJ, la Ley de Asistencia Jurídica al Estado y las autonómicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-105","p":"Ley 29/1998, art. 23.4. La representación procesal prevista en el art. 23 podrá conferirse:","o":["Únicamente mediante poder notarial presencial.","Solo ante el letrado de la Administración de Justicia en comparecencia personal.","Electrónicamente, a través de los medios establecidos para ello.","Únicamente por escrito firmado ante el Juzgado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Electrónicamente, a través de los medios establecidos para ello</mark></span>El <span class=\"ref-norma\">art. 23.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"En todo caso, la representación prevista en este artículo podrá conferirse electrónicamente a través de los medios establecidos para ello\"</span>. Por qué fallan las otras: siempre cabe conferirla electrónicamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"13-ia-116","p":"Ley 29/1998, art. 19.1.b). Están legitimados las corporaciones, asociaciones, sindicatos y grupos y entidades del art. 18 que:","o":["Cuenten con la autorización expresa del Ministerio Fiscal.","Tengan personalidad jurídica propia y ámbito estatal.","Estén inscritos en el registro de la Administración demandada.","Resulten afectados o estén legalmente habilitados para la defensa de los derechos e intereses legítimos colectivos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Resulten afectados o estén legalmente habilitados para la defensa de los derechos e intereses legítimos colectivos</mark></span>El <span class=\"ref-norma\">art. 19.1.b) de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Las corporaciones, asociaciones, sindicatos y grupos y entidades a que se refiere el artículo 18 que resulten afectados o estén legalmente habilitados para la defensa de los derechos e intereses legítimos colectivos\"</span>. Por qué fallan las otras: basta con estar afectados o legalmente habilitados para defender intereses colectivos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-117","p":"Ley 29/1998, art. 19.5. Para recurrir ante el orden contencioso-administrativo las resoluciones del Tribunal Administrativo del Deporte en asuntos de disciplina deportiva en materia de dopaje, ¿quiénes tienen legitimación?","o":["Todas las personas mencionadas en el art. 40.4 de la Ley Orgánica de Protección de la Salud del Deportista y Lucha contra el Dopaje en la Actividad Deportiva.","Únicamente el deportista sancionado.","El Ministerio Fiscal en exclusiva.","Cualquier ciudadano en ejercicio de la acción popular."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Todas las personas mencionadas en el art. 40.4 de la Ley Orgánica de Protección de la Salud del Deportista y Lucha contra el Dopaje en la Actividad Deportiva</mark></span>El <span class=\"ref-norma\">art. 19.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Tendrán legitimación para recurrir ante el orden jurisdiccional contencioso-administrativo las resoluciones del Tribunal Administrativo del Deporte que se dicten en asuntos de disciplina deportiva en materia de dopaje, todas las personas mencionadas en el artículo 40.4 de la Ley Orgánica de Protección de la Salud del Deportista y Lucha contra el Dopaje en la Actividad Deportiva\"</span>. Por qué fallan las otras: la legitimación se remite a las personas del art. 40.4 de la Ley Orgánica de dopaje. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-118","p":"Ley 29/1998, art. 23.1. Cuando las partes confieran su representación al Abogado en sus actuaciones ante órganos unipersonales, ¿a quién se notifican las actuaciones?","o":["Al Procurador designado de oficio.","A la parte representada.","Al Abogado.","Al letrado de la Administración de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Abogado</mark></span>El <span class=\"ref-norma\">art. 23.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Cuando las partes confieran su representación al Abogado, será a éste a quien se notifiquen las actuaciones\"</span>. Por qué fallan las otras: si el Abogado ostenta la representación, las notificaciones van a él. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"}]},{"a":"De las Medidas Cautelares","q":[{"i":"13-175","p":"Contencioso-Administrativa. Si de las alegaciones escritas efectuadas resultaren nuevos hechos de trascendencia para la resolución, el Juez, atendida la índole del asunto, podrá acordar la celebración de vista oral o, en caso contrario, si de las alegaciones escritas efectuadas no resultaran nuevos hechos de trascendencia para la resolución, el Juez resolverá en el plazo improrrogable de __________ mediante auto. La decisión que se adopte únicamente podrá autorizar o denegar la ejecución de la medida.","o":["Dos días.","Cinco días.","Diez días.","Treinta días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos días</mark></span>Según el <span class=\"ref-norma\">art. 122 bis.2 de la Ley 29/1998</span>: <span class=\"ref-concepto\">\"...el Juez resolverá en el plazo improrrogable de dos días mediante auto. La decisión que se adopte únicamente podrá autorizar o denegar la ejecución de la medida.\"</span> (verificado con el texto del temario)."}]},{"a":"Órganos y competencias","q":[{"i":"13-352","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Juzgados de lo Contencioso-administrativo. Los Juzgados de lo Contencioso-administrativo conocerán, en única o primera instancia, de los recursos contra actos administrativos de la Administración de las Comunidades Autónomas, salvo cuando procedan del respectivo:","o":["Presidente de la Comunidad Autónoma.","Consejo de Gobierno.","Parlamento autonómico.","Tribunal Superior de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Consejo de Gobierno</mark></span>El <span class=\"ref-norma\">art. 8.2 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"salvo cuando procedan del respectivo Consejo de Gobierno\"</span> Se excluyen los actos del Consejo de Gobierno."},{"i":"13-ia-142","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Órganos. El orden jurisdiccional contencioso-administrativo se halla integrado por los Juzgados de lo Contencioso-administrativo, los Juzgados Centrales, las Salas de los Tribunales Superiores de Justicia, la Sala de la Audiencia Nacional y:","o":["la Sala de lo Penal del Tribunal Supremo.","la Sala de lo Contencioso-administrativo del Tribunal Constitucional.","los Juzgados de lo Contencioso-administrativo del Tribunal Supremo.","la Sala de lo Contencioso-administrativo del Tribunal Supremo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Sala de lo Contencioso-administrativo del Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 6 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"Sala de lo Contencioso-administrativo del Tribunal Supremo.\"</span> Sala del Tribunal Supremo."},{"i":"13-ia-143","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Juzgados de lo Contencioso-administrativo. Los Juzgados de lo Contencioso-administrativo conocerán en única o primera instancia de los recursos contra actos de los organismos, entes, entidades o corporaciones de derecho público cuya competencia:","o":["se extienda a todo el territorio nacional.","no se extienda a todo el territorio nacional.","se extienda a más de una Comunidad Autónoma, sin perjuicio de lo que establezcan los tratados internacionales.","se limite a una sola provincia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no se extienda a todo el territorio nacional</mark></span>El <span class=\"ref-norma\">art. 8.3 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"cuya competencia no se extienda a todo el territorio nacional\"</span> Competencia que no se extiende a todo el territorio nacional."}]},{"a":"Legitimación","q":[{"i":"13-353","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Legitimación. Están legitimados ante el orden jurisdiccional contencioso-administrativo:","o":["las personas que ostenten únicamente un derecho subjetivo.","las personas físicas, pero no las jurídicas, que ostenten un interés directo.","las personas físicas o jurídicas que ostenten un derecho o interés legítimo.","cualquier ciudadano en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las personas físicas o jurídicas que ostenten un derecho o interés legítimo</mark></span>El <span class=\"ref-norma\">art. 19.1.a) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"Las personas físicas o jurídicas que ostenten un derecho o interés legítimo.\"</span> Derecho o interés legítimo."},{"i":"13-354","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Igualdad de trato y no discriminación. Para la defensa del derecho a la igualdad de trato y no discriminación e intolerancia, además de las personas afectadas y siempre con su autorización, estará también legitimada:","o":["la Autoridad Independiente para la Igualdad de Trato y la No Discriminación.","el Defensor del Pueblo.","el Ministerio Fiscal.","el Instituto de las Mujeres, sin perjuicio de lo que establezcan los tratados internacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Autoridad Independiente para la Igualdad de Trato y la No Discriminación</mark></span>El <span class=\"ref-norma\">art. 19.1.i) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"estará también legitimada la Autoridad Independiente para la Igualdad de Trato y la No Discriminación\"</span> La Autoridad Independiente para la Igualdad de Trato."},{"i":"13-ia-145","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Intereses difusos. Cuando las personas afectadas por una discriminación sean una pluralidad indeterminada o de difícil determinación, la legitimación para instar acciones judiciales en defensa de derechos o intereses difusos corresponderá, entre otros, a los partidos políticos, los sindicatos y las asociaciones profesionales de trabajadores autónomos:","o":["inscritos en el registro correspondiente.","de ámbito autonómico.","con personalidad jurídica propia.","más representativos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">más representativos</mark></span>El <span class=\"ref-norma\">art. 19.1.i) (párrafo 2) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"los partidos políticos, los sindicatos y las asociaciones profesionales de trabajadores autónomos más representativos\"</span> Los más representativos."},{"i":"13-ia-146","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Quiénes no pueden recurrir. No pueden interponer recurso contencioso-administrativo contra la actividad de una Administración pública los particulares cuando obren:","o":["por delegación o como meros agentes o mandatarios de ella.","en representación de una persona jurídica.","en interés de un tercero.","como terceros interesados en el procedimiento, en los términos que determine la ley orgánica correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por delegación o como meros agentes o mandatarios de ella</mark></span>El <span class=\"ref-norma\">art. 20.b) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"Los particulares cuando obren por delegación o como meros agentes o mandatarios de ella.\"</span> Por delegación o como agentes o mandatarios."}]},{"a":"Artículo 106 — Condena al pago de cantidad R17","q":[{"i":"13-356","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Condena al pago de cantidad líquida. Cuando la Administración fuere condenada al pago de cantidad líquida, el pago se hará con cargo al crédito correspondiente de su presupuesto, que tendrá siempre la consideración de:","o":["transferible.","ampliable.","extraordinario.","vinculante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ampliable</mark></span>El <span class=\"ref-norma\">art. 106.1 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"que tendrá siempre la consideración de ampliable.\"</span> Ampliable."},{"i":"13-ia-21","p":"Ley 29/1998, art. 106.1. Si para pagar la cantidad líquida a que fue condenada la Administración fuese necesaria una modificación presupuestaria, el procedimiento correspondiente deberá concluirse dentro de:","o":["El mes siguiente a la firmeza de la sentencia.","Los dos meses siguientes a la comunicación de la sentencia.","Los seis meses siguientes al día de notificación de la resolución judicial.","Los tres meses siguientes al día de notificación de la resolución judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los tres meses siguientes al día de notificación de la resolución judicial</mark></span>El <span class=\"ref-norma\">art. 106.1 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si para el pago fuese necesario realizar una modificación presupuestaria, deberá concluirse el procedimiento correspondiente dentro de los tres meses siguientes al día de notificación de la resolución judicial.\"</span>. Por qué fallan las otras: no confundir con los dos meses del art. 104.2. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-37","p":"Ley 29/1998, art. 106.3. Transcurridos tres meses desde que la sentencia firme sea comunicada al órgano que deba cumplirla, se podrá instar la ejecución forzosa. En ese caso, si apreciase falta de diligencia, la autoridad judicial podrá incrementar el interés legal a devengar en:","o":["Un punto.","Dos puntos.","Tres puntos.","Cinco puntos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos puntos</mark></span>El <span class=\"ref-norma\">art. 106.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"No obstante lo dispuesto en el artículo 104.2, transcurridos tres meses desde que la sentencia firme sea comunicada al órgano que deba cumplirla, se podrá instar la ejecución forzosa. En este supuesto, la autoridad judicial, oído el órgano encargado de hacerla efectiva, podrá incrementar en dos puntos el interés legal a devengar, siempre que apreciase falta de diligencia en el cumplimiento.\"</span>. Por qué fallan las otras: en el pago de cantidad líquida el plazo es de TRES meses (en la ejecución general, DOS meses, art. 104.2). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-97","p":"Ley 29/1998, art. 106.2. Cuando la Administración es condenada al pago de cantidad líquida, a la cantidad se añadirá el interés legal del dinero, calculado:","o":["Desde la fecha de firmeza de la sentencia.","Desde la fecha de interposición del recurso.","Desde la fecha de notificación de la sentencia dictada en única o primera instancia.","Desde que transcurran tres meses de la comunicación de la sentencia firme al órgano obligado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Desde la fecha de notificación de la sentencia dictada en única o primera instancia</mark></span>El <span class=\"ref-norma\">art. 106.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"A la cantidad a que se refiere el apartado anterior se añadirá el interés legal del dinero, calculado desde la fecha de notificación de la sentencia dictada en única o primera instancia\"</span>. Por qué fallan las otras: el cómputo arranca con la notificación de la sentencia de única o primera instancia, no con su firmeza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-128","p":"Ley 29/1998, art. 106.4. Si la Administración condenada al pago de cantidad estimase que el cumplimiento de la sentencia habría de producir trastorno grave a su Hacienda:","o":["Podrá suspender el cumplimiento de la sentencia hasta que mejore su situación presupuestaria.","Podrá declarar por sí misma la inejecución parcial del fallo.","Deberá pagar en todo caso en el plazo de un mes, sin posibilidad de propuesta.","Lo pondrá en conocimiento del Juez o Tribunal acompañado de una propuesta razonada para que, oídas las partes, se resuelva sobre el modo de ejecutar la sentencia en la forma menos gravosa para aquélla."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Lo pondrá en conocimiento del Juez o Tribunal acompañado de una propuesta razonada para que, oídas las partes, se resuelva sobre el modo de ejecutar la sentencia en la forma menos gravosa para aquélla</mark></span>El <span class=\"ref-norma\">art. 106.4 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"lo pondrá en conocimiento del Juez o Tribunal acompañado de una propuesta razonada para que, oídas las partes, se resuelva sobre el modo de ejecutar la sentencia en la forma que sea menos gravosa para aquélla\"</span>. Por qué fallan las otras: no puede suspender ni inejecutar; propone una forma menos gravosa que decide el Juez o Tribunal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-129","p":"Ley 29/1998, art. 106.6. Cuando la Administración es condenada al pago de cantidad, ¿qué podrá solicitar cualquiera de las partes?","o":["Que la cantidad se fraccione en pagos anuales.","Que la cantidad a satisfacer se compense con créditos que la Administración ostente contra el recurrente.","Que la cantidad se abone con cargo a un crédito extraordinario.","Que la cantidad se reduzca en un tercio por razones de interés público."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que la cantidad a satisfacer se compense con créditos que la Administración ostente contra el recurrente</mark></span>El <span class=\"ref-norma\">art. 106.6 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Cualquiera de las partes podrá solicitar que la cantidad a satisfacer se compense con créditos que la Administración ostente contra el recurrente\"</span>. Por qué fallan las otras: la compensación con créditos de la Administración contra el recurrente puede pedirla cualquiera de las partes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"13-ia-130","p":"Ley 29/1998, art. 106.5. Lo dispuesto en los apartados anteriores del art. 106 sobre condena al pago de cantidad líquida será de aplicación asimismo:","o":["Solo a las sentencias firmes dictadas por el Tribunal Supremo.","A las sentencias de inadmisibilidad y desestimación del recurso.","A los supuestos en que se lleve a efecto la ejecución provisional de las sentencias conforme a esta Ley.","Únicamente a las sentencias dictadas en el procedimiento de derechos fundamentales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los supuestos en que se lleve a efecto la ejecución provisional de las sentencias conforme a esta Ley</mark></span>El <span class=\"ref-norma\">art. 106.5 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Lo dispuesto en los apartados anteriores será de aplicación asimismo a los supuestos en que se lleve a efecto la ejecución provisional de las sentencias conforme a esta Ley\"</span>. Por qué fallan las otras: el régimen de pago se aplica también a la ejecución provisional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"}]},{"a":"Extensión de efectos","q":[{"i":"13-357","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Extensión de efectos de las sentencias. Los efectos de una sentencia firme que hubiera reconocido una situación jurídica individualizada podrán extenderse a otras personas, en ejecución de la sentencia, en materia:","o":["civil, penal y tributaria.","tributaria y de personal, pero no de unidad de mercado, en los términos que determine la ley orgánica correspondiente.","tributaria, de personal al servicio de la Administración pública y de unidad de mercado.","de personal y de contratación pública."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tributaria, de personal al servicio de la Administración pública y de unidad de mercado</mark></span>El <span class=\"ref-norma\">art. 110.1 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"En materia tributaria, de personal al servicio de la Administración pública y de unidad de mercado, los efectos de una sentencia firme\"</span> Tributaria, personal y unidad de mercado."}]},{"a":"Artículo 75 — Allanamiento","q":[{"i":"13-ia-13","p":"Ley 29/1998, art. 75.2. Si el allanamiento supusiere infracción manifiesta del ordenamiento jurídico, el órgano jurisdiccional comunicará a las partes los motivos que pudieran oponerse a la estimación y las oirá por plazo común de:","o":["Cinco días.","Quince días.","Veinte días.","Diez días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Diez días</mark></span>El <span class=\"ref-norma\">art. 75.2 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"...en cuyo caso el órgano jurisdiccional comunicará a las partes los motivos que pudieran oponerse a la estimación de las pretensiones y las oirá por plazo común de diez días, dictando luego la sentencia que estime ajustada a Derecho.\"</span>. Por qué fallan las otras: los cinco días son los del reconocimiento en vía administrativa (art. 76.2) y los del traslado del desistimiento (art. 74.3). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"13-ia-57","p":"Ley 29/1998, art. 75.3. Si fueren varios los demandados y alguno de ellos se allana, ¿qué ocurre con el procedimiento?","o":["Terminará para todos los demandados.","Quedará suspendido hasta que todos los demandados se allanen.","Seguirá respecto de aquellos que no se hubiesen allanado.","Se dictará sentencia conforme a las pretensiones del demandante respecto de todos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seguirá respecto de aquellos que no se hubiesen allanado</mark></span>El <span class=\"ref-norma\">art. 75.3 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa</span> dispone: <span class=\"ref-concepto\">\"Si fueren varios los demandados, el procedimiento seguirá respecto de aquellos que no se hubiesen allanado\"</span>. Por qué fallan las otras: el allanamiento de uno no pone fin al proceso respecto de los demás. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"}]},{"a":"Ámbito","q":[{"i":"13-ia-141","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Administraciones públicas. A los efectos de la Ley, se entenderá por Administraciones públicas la Administración General del Estado, las Administraciones de las Comunidades Autónomas, las Entidades de Derecho público dependientes o vinculadas y:","o":["las Entidades que integran la Administración local.","las Entidades que integran la Administración institucional.","las Entidades que integran la Administración regional.","las Entidades que integran la Administración electoral."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las Entidades que integran la Administración local</mark></span>El <span class=\"ref-norma\">art. 1.2.c) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"Las Entidades que integran la Administración local.\"</span> Administración local."}]},{"a":"Competencia territorial","q":[{"i":"13-ia-144","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Competencia territorial. Cuando el recurso tenga por objeto actos de las Administraciones públicas en materia de responsabilidad patrimonial, personal, propiedades especiales y sanciones, será competente el juzgado o tribunal en cuya circunscripción tenga el demandante su domicilio o se halle la sede del órgano autor del acto. La elección corresponde:","o":["a la Administración demandada.","al Ministerio Fiscal.","al demandante.","al órgano jurisdiccional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al demandante</mark></span>El <span class=\"ref-norma\">art. 14.1 (regla segunda) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"será competente, a elección del demandante, el juzgado o el tribunal en cuya circunscripción tenga aquél su domicilio\"</span> A elección del demandante."}]},{"a":"Partes","q":[{"i":"13-ia-147","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Parte demandada. Se considera parte demandada las Administraciones públicas o cualesquiera de los órganos mencionados en el artículo 1.3:","o":["que hayan dictado la resolución impugnada en alzada.","contra cuya actividad se dirija el recurso.","que hayan emitido el informe preceptivo.","que sean titulares de un interés legítimo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">contra cuya actividad se dirija el recurso</mark></span>El <span class=\"ref-norma\">art. 21.1.a) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"contra cuya actividad se dirija el recurso\"</span> Contra cuya actividad se dirija el recurso."}]},{"a":"Representación y defensa","q":[{"i":"13-ia-148","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Representación y defensa de las Administraciones públicas. La representación y defensa de las Administraciones públicas y de los órganos constitucionales se rige por lo dispuesto en la Ley Orgánica del Poder Judicial y en:","o":["la Ley de Enjuiciamiento Civil.","la Ley del Régimen Jurídico del Sector Público, salvo que el órgano competente acuerde otra cosa de forma motivada.","la Ley de Asistencia Jurídica al Estado e Instituciones Públicas.","el Estatuto de la Abogacía del Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Ley de Asistencia Jurídica al Estado e Instituciones Públicas</mark></span>El <span class=\"ref-norma\">art. 24 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"en la Ley de Asistencia Jurídica al Estado e Instituciones Públicas\"</span> Ley de Asistencia Jurídica al Estado."}]},{"a":"Procedimiento","q":[{"i":"13-ia-149","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Requerimiento previo. En los litigios entre Administraciones públicas, el requerimiento previo deberá producirse en el plazo de:","o":["quince días desde la notificación del acto, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","un mes desde la publicación de la norma.","tres meses desde la publicación del acto.","dos meses contados desde la publicación de la norma o desde que la Administración requirente hubiera conocido o podido conocer el acto, actuación o inactividad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos meses contados desde la publicación de la norma o desde que la Administración requirente hubiera conocido o podido conocer el acto, actuación o inactividad</mark></span>El <span class=\"ref-norma\">art. 44.2 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"deberá producirse en el plazo de dos meses contados desde la publicación de la norma\"</span> Dos meses."},{"i":"13-ia-150","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Recurso de lesividad. El recurso de lesividad se iniciará por:","o":["escrito reducido de interposición.","demanda.","requerimiento previo.","denuncia ante el Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">demanda</mark></span>El <span class=\"ref-norma\">art. 45.4 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"El recurso de lesividad se iniciará por demanda\"</span> Por demanda."},{"i":"13-ia-151","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Inicio por demanda. El recurso dirigido contra una disposición general, acto, inactividad o vía de hecho en que no existan terceros interesados podrá iniciarse también mediante:","o":["demanda.","requerimiento previo.","escrito de aclaración.","declaración de lesividad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">demanda</mark></span>El <span class=\"ref-norma\">art. 45.5 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"en que no existan terceros interesados podrá iniciarse también mediante demanda\"</span> Mediante demanda."}]},{"a":"Sentencia","q":[{"i":"13-ia-152","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Fallos de la sentencia. La sentencia pronunciará alguno de los fallos siguientes: inadmisibilidad del recurso contencioso-administrativo o:","o":["sobreseimiento o archivo del recurso.","caducidad del recurso o desistimiento, en los términos que determine la ley orgánica correspondiente.","estimación o desestimación del recurso contencioso-administrativo.","allanamiento o reconocimiento total."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">estimación o desestimación del recurso contencioso-administrativo</mark></span>El <span class=\"ref-norma\">art. 68.1.a) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"Estimación o desestimación del recurso contencioso-administrativo.\"</span> Inadmisibilidad, estimación o desestimación."},{"i":"13-ia-153","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Contenido de la sentencia estimatoria. Cuando la sentencia estimase el recurso contencioso-administrativo, declarará no ser conforme a Derecho y, en su caso, anulará total o parcialmente la disposición o acto recurrido o dispondrá:","o":["que se inicie nuevo procedimiento.","que se indemnice al recurrente.","que se retrotraigan las actuaciones, salvo que el órgano competente acuerde otra cosa de forma motivada.","que cese o se modifique la actuación impugnada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">que cese o se modifique la actuación impugnada</mark></span>El <span class=\"ref-norma\">art. 71.1.a) de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"o dispondrá que cese o se modifique la actuación impugnada.\"</span> Que cese o se modifique la actuación."},{"i":"13-ia-154","p":"Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa. Efectos de la sentencia. La sentencia que declare la inadmisibilidad o desestimación del recurso contencioso-administrativo sólo producirá efectos:","o":["frente a todos.","entre las partes.","respecto del recurrente.","para la Administración demandada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">entre las partes</mark></span>El <span class=\"ref-norma\">art. 72.1 de la Ley 29/1998 (LJCA)</span> dispone: <span class=\"ref-concepto\">\"sólo producirá efectos entre las partes.\"</span> Solo entre las partes."}]}];
